INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94049, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "每周是每一个星期。", "primary_collocate": null, "pronunciation": "měi zhōu", "ipa": "mei˨˩˦ ʈʂou˥", "syllable_count": 2, "sentences": [{"text": "我每周去两次游泳馆。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每周给妈妈打一个电话。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每周开一次会。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每周我都会去图书馆借书。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师每周给我们留三次作业。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周跑步三次，身体很好。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每周都买一束花放在家里。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每周换一次菜单。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥每周坐火车回家看我们。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每周学习汉语五个小时。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每周：每一个星期，表示动作按周重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每周", "is_correct": true, "explanation": "正确：“每周”表示每个星期，修饰动词“去”，与“两次”表示的按周次数相合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未，与“去两次”表示有次数的行为相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立即，不与表示周期次数的“两次”搭配。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与按周重复的行为不相符。"}], "explanations": {"每周": "正确：“每周”表示每个星期，修饰动词“去”，与“两次”表示的按周次数相合。", "从来": "语义：“从来”表示从未，与“去两次”表示有次数的行为相矛盾。", "马上": "搭配：“马上”表示立即，不与表示周期次数的“两次”搭配。", "忽然": "语义：“忽然”表示突然，与按周重复的行为不相符。"}, "sentence_index": 0, "correct_answer": "每周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周在这所大学毕业了。", "explanation": "这里应该用〈那年〉，删去“每周”。“毕业”是一次性事件，不能按周重复。"}, {"text": "我们每周都回老家过春节。", "explanation": "这里应该用〈每年〉。“春节”一年只有一次，不能按周重复。"}, {"text": "爷爷每周去世了，我们都很难过。", "explanation": "这里不应用〈每周〉。“去世”只发生一次，不能按周重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每周", "is_correct": true, "explanation": "正确：“每周”表示每个星期，与“都”配合，说明按周重复的习惯。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不定时发生，与“都”表示每次都的意思相矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上，不能与表示反复习惯的“都”搭配。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示一下子，与按周重复的习惯不相符。"}], "explanations": {"每周": "正确：“每周”表示每个星期，与“都”配合，说明按周重复的习惯。", "偶尔": "语义：“偶尔”表示不定时发生，与“都”表示每次都的意思相矛盾。", "立刻": "搭配：“立刻”表示马上，不能与表示反复习惯的“都”搭配。", "顿时": "语义：“顿时”表示一下子，与按周重复的习惯不相符。"}, "sentence_index": 6, "correct_answer": "每周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每周十号学习汉语五个小时。", "explanation": "这里应该用〈每月〉。“十号”是每月的固定日期，不能按周重复。"}, {"text": "她每周在医院出生了。", "explanation": "这里不应用〈每周〉。“出生”只发生一次，不能按周重复。"}, {"text": "我每周的老家是北京。", "explanation": "这里不应用〈每周〉修饰“老家”。“每周的”只能修饰周期性发生的事，如“每周的例会”，“老家”不具周期性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周的去一次公园。", "corrected_sentence": "我每周去一次公园。", "error_description": "多余的“的”：“每周”在此作状语，修饰动词“去”，后面不应加“的”。（“每周的”可作定语，如“每周的例会”。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每周的都给奶奶打一次电话。", "corrected_sentence": "我每周都给奶奶打一次电话。", "error_description": "多余的“的”：“每周”在此作状语，修饰动词“打”，后面不应加“的”，应说“每周都”。（“每周的”可作定语，如“每周的例会”，但此处不能作状语。）", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
