INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94050, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "每一个星期。", "primary_collocate": null, "pronunciation": "měi zhōu", "ipa": "mei˨˩˦ ʈʂou˥", "syllable_count": 2, "sentences": [{"text": "每周我们都吃一次饺子。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周写一封信给奶奶。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每周发一次通知。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每周都去上钢琴课。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每周洗两次车。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每周来学校一次。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每周都早起去爬山。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目每周播出一次。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每周去市场买两次菜。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每周花一个小时整理房间。", "target_word": "每周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每周：每一个星期，做状语说明频率", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每周", "is_correct": true, "explanation": "正确：“每周”作状语，表示每个星期，与“都吃一次饺子”表示的习惯相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与按周重复的习惯相矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上，不能与表示周期习惯的“都”搭配作句首。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向或从未，与“每周”限定的周期及“一次”的次数不相容。"}], "explanations": {"每周": "正确：“每周”作状语，表示每个星期，与“都吃一次饺子”表示的习惯相合。", "忽然": "语义：“忽然”表示突然，与按周重复的习惯相矛盾。", "立刻": "搭配：“立刻”表示马上，不能与表示周期习惯的“都”搭配作句首。", "从来": "语义：“从来”表示一向或从未，与“每周”限定的周期及“一次”的次数不相容。"}, "sentence_index": 0, "correct_answer": "每周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周在上个月结婚了。", "explanation": "这里不应用〈每周〉。“结婚”只发生一次，不能按周重复，且与“上个月”冲突。"}, {"text": "爷爷每周去世了，我们都很伤心。", "explanation": "这里不应用〈每周〉。“去世”是一次性事件，不能按周重复。"}, {"text": "我每周过一次生日。", "explanation": "这里应该用〈每年〉。“生日”一年一次，不能按周重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
