INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94051, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "毒品是吃了会伤害身体、让人上瘾的坏东西。", "primary_collocate": null, "pronunciation": "dú pǐn", "ipa": "tu˧˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "毒品会伤害身体，让人上瘾。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在他的车里找到了毒品。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友一直在买毒品，身体越来越差。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请警察来讲毒品的危害。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要告诉孩子，一定不能碰毒品。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家严格禁止买卖毒品。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毒品很难戒掉，吃了就会上瘾。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他想把毒品带进城。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为卖毒品，进了监狱。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毒品毁了他的家，也毁了他的身体。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "毒品交易", "label": "复合"}], "register": "中性", "sense_fingerprint": "毒品：吃了会伤害身体、让人上瘾的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不会让人上瘾，句中的“让人上瘾”只能指毒品一类的东西。"}, {"text": "毒品", "is_correct": true, "explanation": "毒品是吃了会伤害身体、让人上瘾的东西，正好符合句意。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌说的是人的长相，不会伤害身体，也不会让人上瘾。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不会让人上瘾，与“让人上瘾”的意思不合。"}], "explanations": {"空气": "语义：空气不会让人上瘾，句中的“让人上瘾”只能指毒品一类的东西。", "毒品": "毒品是吃了会伤害身体、让人上瘾的东西，正好符合句意。", "外貌": "语义：外貌说的是人的长相，不会伤害身体，也不会让人上瘾。", "阳光": "语义：阳光不会让人上瘾，与“让人上瘾”的意思不合。"}, "sentence_index": 0, "correct_answer": "毒品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给病人开了毒品，让他按时服用。", "explanation": "这里应该用〈药品〉。毒品吃了会伤害身体、让人上瘾，不能当药开给病人。"}, {"text": "他每天早上用毒品洗脸。", "explanation": "这里应该用〈洗面奶〉。毒品是伤害身体、让人上瘾的东西，不能用来洗脸。"}, {"text": "妈妈每天早上给孩子的牛奶里加一包毒品。", "explanation": "这里应该用〈糖〉。毒品会伤害身体、让人上瘾，不能像糖一样加进牛奶里当甜味剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香水", "is_correct": false, "explanation": "语义：香水不能吃，句中“吃了就会上瘾”说的是可以吃进去的东西。"}, {"text": "毒品", "is_correct": true, "explanation": "毒品吃了就会上瘾，很难戒掉，正好符合句意。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“戒掉”的对象是习惯、烟瘾之类，不能说“戒掉疾病”。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言不能吃，也谈不上“吃了就会上瘾”，句意不通。"}], "explanations": {"香水": "语义：香水不能吃，句中“吃了就会上瘾”说的是可以吃进去的东西。", "毒品": "毒品吃了就会上瘾，很难戒掉，正好符合句意。", "疾病": "搭配：“戒掉”的对象是习惯、烟瘾之类，不能说“戒掉疾病”。", "语言": "语义：语言不能吃，也谈不上“吃了就会上瘾”，句意不通。"}, "sentence_index": 6, "correct_answer": "毒品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生戴着毒品走进病房。", "explanation": "这里应该用〈口罩〉。“戴”搭配口罩、眼镜等物品，毒品不能戴。"}, {"text": "他用毒品给手机充了电。", "explanation": "这里应该用〈电池〉。毒品不能用来给手机充电，它是伤害身体、让人上瘾的东西。"}, {"text": "妈妈用毒品洗衣服。", "explanation": "这里应该用〈洗衣粉〉。毒品不能用来洗衣服，它是吃了会伤害身体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于戒掉了毒品们。", "corrected_sentence": "他终于戒掉了毒品。", "error_description": "后缀错误：“们”只用于指人的名词，“毒品”不能加“们”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察查获了两台毒品。", "corrected_sentence": "警察查获了两包毒品。", "error_description": "量词错误：毒品应用“包”计量，“台”用于机器、设备，不能用于毒品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
