INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能使人上瘾并危害健康的麻醉品，如鸦片、海洛因。", "primary_collocate": null, "pronunciation": "dú pǐn", "ipa": "tu˧˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "海洛因是一种很危险的毒品。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸦片和海洛因都属于毒品。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种毒品能让人上瘾，还会伤害健康。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关查到了一大包毒品。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察今天抓到了几个卖毒品的人。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都在努力减少毒品的危害。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了买毒品，把家里的钱都用完了。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贩卖毒品是严重的犯罪。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吸过毒品，现在在医院接受治疗。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在讲毒品对年轻人的影响。", "target_word": "毒品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "包", "label": "量词"}], "register": "中性", "sense_fingerprint": "毒品：鸦片、海洛因一类使人上瘾、危害健康的麻醉品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "武器", "is_correct": false, "explanation": "语义：海洛因是毒品，不是武器，句子说的是它的危害。"}, {"text": "毒品", "is_correct": true, "explanation": "海洛因是能使人上瘾、危害健康的麻醉品，属于毒品。"}, {"text": "植物", "is_correct": false, "explanation": "语义：海洛因是提炼出来的药物，不是植物。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：海洛因是使人上瘾的麻醉品，不是乐器，句意不通。"}], "explanations": {"武器": "语义：海洛因是毒品，不是武器，句子说的是它的危害。", "毒品": "海洛因是能使人上瘾、危害健康的麻醉品，属于毒品。", "植物": "语义：海洛因是提炼出来的药物，不是植物。", "乐器": "语义：海洛因是使人上瘾的麻醉品，不是乐器，句意不通。"}, "sentence_index": 0, "correct_answer": "毒品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口渴了，喝了一杯毒品。", "explanation": "这里应该用〈水〉。毒品是使人上瘾、危害健康的麻醉品，不是解渴的饮料。"}, {"text": "孩子们最喜欢吃毒品。", "explanation": "这里应该用〈糖果〉。毒品会伤害身体并让人上瘾，不能当零食吃。"}, {"text": "医生让病人每天吃毒品。", "explanation": "这里应该用〈维生素〉。毒品吃了会伤害身体，不是用来补充营养的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空买不到，句意说不通。"}, {"text": "毒品", "is_correct": true, "explanation": "毒品能用钱买到，买了之后会用完家里的钱，正好符合句意。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想不是可以用钱买的东西，句意不合。"}, {"text": "友情", "is_correct": false, "explanation": "搭配：“买”说的是能用钱买到的物品，不说“为了买友情”。"}], "explanations": {"天空": "语义：天空买不到，句意说不通。", "毒品": "毒品能用钱买到，买了之后会用完家里的钱，正好符合句意。", "思想": "语义：思想不是可以用钱买的东西，句意不合。", "友情": "搭配：“买”说的是能用钱买到的物品，不说“为了买友情”。"}, "sentence_index": 6, "correct_answer": "毒品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写完了毒品。", "explanation": "这里应该用〈作业〉。“写完”搭配作业、文章等，毒品不能被写完。"}, {"text": "他用毒品拍了一张照片。", "explanation": "这里应该用〈相机〉。毒品不能用来拍照，拍照需要相机之类的工具。"}, {"text": "他早上用毒品刷牙。", "explanation": "这里应该用〈牙膏〉。毒品不能用来刷牙，“刷牙”只能用牙膏之类的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人曾经戒过很毒品。", "corrected_sentence": "那个人曾经戒过毒品。", "error_description": "词性错误：“毒品”是名词，不能受副词“很”修饰，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他藏了一台毒品。", "corrected_sentence": "他藏了一包毒品。", "error_description": "量词错误：毒品应用“包”计量，“台”用于机器、设备，不能用于毒品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
