INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法治是大家都按照法律来做事。", "primary_collocate": null, "pronunciation": "fǎ zhì", "ipa": "fa˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "大家都讲法治，遇事先看法律再行动。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法治让每个人都按法律做事。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在讲法治的社会里，人人都守法。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习法治的知识。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常提醒学生做事要守法，讲法治。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法治让大家的生活更安全。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要讲法治，不能只听某一个人的。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法治意识要从小培养。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都守法，这个城市的法治很好。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校教育我们，人人都要讲法治。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法治国家", "label": "复合词"}, {"form": "法治社会", "label": "复合词"}], "register": "书面", "sense_fingerprint": "人人按法律做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94053, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确答案：法治（fǎ zhì），指大家都按照法律做事。"}, {"text": "法事", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法事（宗教仪式）。"}, {"text": "仿制", "is_correct": false, "explanation": "fǎng（第三声）与 fǎ（第三声）韵母不同，多了后鼻音 ng，意思是仿制（仿照做出）。"}, {"text": "反制", "is_correct": false, "explanation": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反制（反击并制约）。"}], "explanations": {"法治": "正确答案：法治（fǎ zhì），指大家都按照法律做事。", "法事": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法事（宗教仪式）。", "仿制": "fǎng（第三声）与 fǎ（第三声）韵母不同，多了后鼻音 ng，意思是仿制（仿照做出）。", "反制": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反制（反击并制约）。"}, "sentence_index": null, "correct_answer": "法治"}, "level_3": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确：“讲法治”指大家都按法律做事，与后面的“先看法律再行动”一致。"}, {"text": "人情", "is_correct": false, "explanation": "语义：“讲人情”与“遇事先看法律再行动”的做法相冲突，句意矛盾。"}, {"text": "面子", "is_correct": false, "explanation": "语义：“讲面子”与“遇事先看法律”的做法相反，前后语意不一致。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“讲”一般接“道理”“规矩”等，不接“力气”。"}], "explanations": {"法治": "正确：“讲法治”指大家都按法律做事，与后面的“先看法律再行动”一致。", "人情": "语义：“讲人情”与“遇事先看法律再行动”的做法相冲突，句意矛盾。", "面子": "语义：“讲面子”与“遇事先看法律”的做法相反，前后语意不一致。", "力气": "搭配：“讲”一般接“道理”“规矩”等，不接“力气”。"}, "sentence_index": 0, "correct_answer": "法治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法治讲了一个有趣的故事。", "explanation": "这里应该用〈作者〉。作者能讲故事；法治是治理原则，不能讲故事。"}, {"text": "这部新法治已经正式施行。", "explanation": "这里应该用〈条例〉。条例是有名称、可以施行的具体规定；法治是治理原则，不是可以“施行”的文件，不能用“部”计量。"}, {"text": "政府正在制定新的法治。", "explanation": "这里应该用〈法规〉。法规是具体的规章，可以制定；法治是治理原则，不能“制定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94053, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确答案：法治（fǎ zhì），指大家都按照法律做事。"}, {"text": "法式", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法式（法国式样）。"}, {"text": "反智", "is_correct": false, "explanation": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反智（反对理性与知识）。"}, {"text": "法纪", "is_correct": false, "explanation": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是法纪（法律与纪律）。"}], "explanations": {"法治": "正确答案：法治（fǎ zhì），指大家都按照法律做事。", "法式": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法式（法国式样）。", "反智": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反智（反对理性与知识）。", "法纪": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是法纪（法律与纪律）。"}, "sentence_index": null, "correct_answer": "法治"}, "level_3": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确：“讲法治”指按法律办事，与“不能只听某一个人的”的意思一致。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“讲天气”与“不能只听某一个人的”句意无关，句子不通。"}, {"text": "崇拜", "is_correct": false, "explanation": "搭配：“讲”后面一般不接“崇拜”，这个搭配不成立。"}, {"text": "顺从", "is_correct": false, "explanation": "语义：“顺从”指听话照办，与“不能只听某一个人的”相矛盾。"}], "explanations": {"法治": "正确：“讲法治”指按法律办事，与“不能只听某一个人的”的意思一致。", "天气": "语义：“讲天气”与“不能只听某一个人的”句意无关，句子不通。", "崇拜": "搭配：“讲”后面一般不接“崇拜”，这个搭配不成立。", "顺从": "语义：“顺从”指听话照办，与“不能只听某一个人的”相矛盾。"}, "sentence_index": 6, "correct_answer": "法治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法治判决了这起案子。", "explanation": "这里应该用〈法院〉。法院是审判机关，能作判决；法治是治理原则，不能作判决的主语。"}, {"text": "政府颁布了一项新法治。", "explanation": "这里应该用〈法令〉。法令是政府颁布的具体命令，可以颁布；法治是治理原则，不能颁布。"}, {"text": "法治为客户辩护。", "explanation": "这里应该用〈律师〉。律师是人，能为当事人辩护；法治是原则，不能辩护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都吃法治，做事前先想想法律。", "corrected_sentence": "大家都讲法治，做事前先想想法律。", "error_description": "搭配错误：“吃”不能接“法治”这类抽象概念，应改为“讲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
