INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以法律作为管理国家和社会的依据。", "primary_collocate": null, "pronunciation": "fǎ zhì", "ipa": "fa˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我国坚持用法治管理国家。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要依靠法治来管理社会。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法治是国家管理的重要依据。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的法治越来越完善。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法治比人治更可靠。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们希望建设一个法治的国家。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家发展离不开法治。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法治是现代国家的基础。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府提出要加强法治建设。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有法治，社会就会很乱。", "target_word": "法治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法治国家", "label": "复合词"}, {"form": "法治建设", "label": "复合词"}], "register": "书面", "sense_fingerprint": "以法律管理国家和社会的制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确答案：法治（fǎ zhì），指以法律作为管理国家和社会的依据。"}, {"text": "法式", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法式（法国式样）。"}, {"text": "仿制", "is_correct": false, "explanation": "fǎng（第三声）与 fǎ（第三声）韵母不同，多了后鼻音 ng，意思是仿制（仿照做出）。"}, {"text": "反制", "is_correct": false, "explanation": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反制（反击并制约）。"}], "explanations": {"法治": "正确答案：法治（fǎ zhì），指以法律作为管理国家和社会的依据。", "法式": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法式（法国式样）。", "仿制": "fǎng（第三声）与 fǎ（第三声）韵母不同，多了后鼻音 ng，意思是仿制（仿照做出）。", "反制": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反制（反击并制约）。"}, "sentence_index": null, "correct_answer": "法治"}, "level_3": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确：“用法治管理国家”指以法律为依据治理国家，符合句意。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“用感情管理国家”不符合治国的道理，句意荒谬。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：国家管理不能依靠“脾气”，与“坚持”的治理原则相冲突。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：“用玩笑管理国家”荒唐可笑，与“坚持”的治国原则不符。"}], "explanations": {"法治": "正确：“用法治管理国家”指以法律为依据治理国家，符合句意。", "感情": "语义：“用感情管理国家”不符合治国的道理，句意荒谬。", "脾气": "语义：国家管理不能依靠“脾气”，与“坚持”的治理原则相冲突。", "玩笑": "语义：“用玩笑管理国家”荒唐可笑，与“坚持”的治国原则不符。"}, "sentence_index": 0, "correct_answer": "法治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法治唱了一首好听的歌。", "explanation": "这里应该用〈歌手〉。歌手能唱歌，法治是治国的原则，不能唱歌。"}, {"text": "这位老师的法治很好，字写得很漂亮。", "explanation": "这里应该用〈书法〉。书法指写字的技艺；法治是以法律管理国家的制度，不能用来说字写得好。"}, {"text": "法治是研究法律的学科。", "explanation": "这里应该用〈法学〉。法学是研究法律的学科；法治是国家治理的原则，不能说“研究法律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94054, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确答案：法治（fǎ zhì），指以法律作为管理国家和社会的依据。"}, {"text": "法事", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法事（宗教仪式）。"}, {"text": "反智", "is_correct": false, "explanation": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反智（反对理性与知识）。"}, {"text": "法纪", "is_correct": false, "explanation": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是法纪（法律与纪律）。"}], "explanations": {"法治": "正确答案：法治（fǎ zhì），指以法律作为管理国家和社会的依据。", "法事": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是法事（宗教仪式）。", "反智": "fǎn（第三声）与 fǎ（第三声）韵母不同，多了 n，意思是反智（反对理性与知识）。", "法纪": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是法纪（法律与纪律）。"}, "sentence_index": null, "correct_answer": "法治"}, "level_3": {"options": [{"text": "法治", "is_correct": true, "explanation": "正确：“离不开法治”指国家发展需要依法治理，与句意一致。"}, {"text": "谣言", "is_correct": false, "explanation": "语义：国家发展不可能“离不开谣言”，句意荒谬。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”不是国家发展所依赖的条件，句意荒谬。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：国家发展不依赖“八卦”（闲聊传闻），说“离不开八卦”句意荒谬。"}], "explanations": {"法治": "正确：“离不开法治”指国家发展需要依法治理，与句意一致。", "谣言": "语义：国家发展不可能“离不开谣言”，句意荒谬。", "游戏": "语义：“游戏”不是国家发展所依赖的条件，句意荒谬。", "八卦": "语义：国家发展不依赖“八卦”（闲聊传闻），说“离不开八卦”句意荒谬。"}, "sentence_index": 6, "correct_answer": "法治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物理学中有很多法治。", "explanation": "这里应该用〈法则〉。法则指事物的客观规律，如物理法则；法治是依法治理国家的制度，不能指自然规律。"}, {"text": "这个游戏的法治很复杂。", "explanation": "这里应该用〈规则〉。规则指具体的条例或玩法约定；法治是国家以法律治理社会的制度，不能用来形容一个游戏。"}, {"text": "政府发布了一份新的法治。", "explanation": "这里应该用〈公告〉。公告是政府向公众发布的文件，可以发布；法治是治理原则，不是文件，不能用“一份”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把法治把落实到每个人身上。", "corrected_sentence": "我们要把法治落实到每个人身上。", "error_description": "结构错误：一句话中“把”只能用一次，“把法治”之后不能再加“把”，应删去多余的“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家要是没有把法治，就容易混乱。", "corrected_sentence": "国家要是没有法治，就容易混乱。", "error_description": "结构错误：“没有”后面直接接名词“法治”，中间不能插入“把”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
