INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "症状是生病时身体出现的样子，比如发烧、咳嗽。", "primary_collocate": null, "pronunciation": "zhèng zhuàng", "ipa": "ʈʂɤŋ˥˩ ʈʂwaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "发烧和咳嗽是感冒的常见症状。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有什么症状？发烧还是咳嗽？", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我有没有头疼的症状。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，我的症状好多了。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子有发烧的症状，要马上去医院。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天我一直有咳嗽的症状。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的症状太重了，要多休息。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的症状写在了纸上。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点症状也没有，检查却发现有病。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病的症状很轻，不用太担心。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "症狀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "症状：生病时身体出现的样子，如发烧、咳嗽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病因", "is_correct": false, "explanation": "语义：发烧和咳嗽是感冒的表现，不是感冒的原因。"}, {"text": "症状", "is_correct": true, "explanation": "症状是生病时身体出现的样子，发烧和咳嗽正是感冒的症状。"}, {"text": "药物", "is_correct": false, "explanation": "语义：发烧和咳嗽是身体的表现，不是药物。"}, {"text": "体形", "is_correct": false, "explanation": "体貌：体形说的是人的身材，不是感冒时身体出现的表现。"}], "explanations": {"病因": "语义：发烧和咳嗽是感冒的表现，不是感冒的原因。", "症状": "症状是生病时身体出现的样子，发烧和咳嗽正是感冒的症状。", "药物": "语义：发烧和咳嗽是身体的表现，不是药物。", "体形": "体貌：体形说的是人的身材，不是感冒时身体出现的表现。"}, "sentence_index": 0, "correct_answer": "症状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听到好消息，就把自己的症状送给了朋友。", "explanation": "这里应该用〈礼物〉。症状是生病时身体出现的样子，不是可以送给朋友的东西。"}, {"text": "警察在现场找到了症状。", "explanation": "这里应该用〈证据〉。症状是身体的表现，不是可以在现场找到的东西。"}, {"text": "他身上有一颗症状，是咳嗽。", "explanation": "量词错误：症状应用〈种〉或〈个〉计量，〈颗〉用于小而圆的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色的深浅与“要多休息”没有关系，句意不通。"}, {"text": "症状", "is_correct": true, "explanation": "症状太重，身体不舒服，所以要多休息，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音说的是音量，不是需要休息的身体状况。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不说“太重”，应说“太紧”。"}], "explanations": {"颜色": "语义：颜色的深浅与“要多休息”没有关系，句意不通。", "症状": "症状太重，身体不舒服，所以要多休息，符合句意。", "声音": "语义：声音说的是音量，不是需要休息的身体状况。", "时间": "搭配：“时间”不说“太重”，应说“太紧”。"}, "sentence_index": 6, "correct_answer": "症状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试的症状很好。", "explanation": "这里应该用〈成绩〉。症状指疾病在身体上的表现，不能用来评价考试。"}, {"text": "他的工资涨了，症状也涨了。", "explanation": "这里应该用〈物价〉。症状是身体的异常表现，不会像物价那样上涨。"}, {"text": "我身上只有一张症状。", "explanation": "量词错误：症状应用〈种〉或〈个〉，〈张〉用于纸、桌子等扁平的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有两只症状，发烧和咳嗽。", "corrected_sentence": "他有两种症状，发烧和咳嗽。", "error_description": "量词错误：症状应用“种”计量，“只”用于动物或成对物中的一个，不能用于症状。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃了药，这种病的一颗症状消失了。", "corrected_sentence": "吃了药，这种病的症状消失了。", "error_description": "量词错误：症状应用“种”或“个”计量，“颗”用于小而圆的东西，不能用于症状，应去掉“一颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
