INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "疾病在身体上表现出来的异常现象。", "primary_collocate": null, "pronunciation": "zhèng zhuàng", "ipa": "ʈʂɤŋ˥˩ ʈʂwaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生根据症状判断是什么病。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病早期没有明显的症状。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有胸痛的症状，需要做检查。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人出现了呼吸困难的症状。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的人，症状可能不一样。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "症状严重的病人要住院治疗。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药以后，疼痛的症状慢慢消失了。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些症状说明他的身体有问题。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要把症状告诉医生，别不好意思。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤发红也是过敏的一种症状。", "target_word": "症状", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "症狀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "症状：疾病在身体上表现出来的异常现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜料", "is_correct": false, "explanation": "语义：颜料不是身体的表现，不能用来判断是什么病。"}, {"text": "症状", "is_correct": true, "explanation": "症状是疾病在身体上表现出来的异常现象，医生根据它判断病，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能用来判断是什么病。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与判断病情无关，句意不通。"}], "explanations": {"颜料": "语义：颜料不是身体的表现，不能用来判断是什么病。", "症状": "症状是疾病在身体上表现出来的异常现象，医生根据它判断病，符合句意。", "名字": "语义：名字不能用来判断是什么病。", "价格": "语义：价格与判断病情无关，句意不通。"}, "sentence_index": 0, "correct_answer": "症状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官要求律师提交症状。", "explanation": "这里应该用〈证据〉。症状是疾病在身体上的表现，不能提交给法官。"}, {"text": "他每天都收到很多症状。", "explanation": "这里应该用〈邮件〉。症状指身体的异常表现，不是可以收到的东西。"}, {"text": "他身上有一块症状，是咳嗽。", "explanation": "量词错误：症状应用〈种〉或〈个〉计量，〈块〉用于块状的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“疼痛”修饰身体感受，“作业”不能疼痛，句意不通。"}, {"text": "烟雾", "is_correct": false, "explanation": "语义：烟雾不是疼痛的表现，句意说不通。"}, {"text": "脸庞", "is_correct": false, "explanation": "体貌：脸庞说的是面部外形，不是身体的异常表现，不能说“疼痛的脸庞”。"}, {"text": "症状", "is_correct": true, "explanation": "吃药后疼痛的症状慢慢消失，“症状”指疾病的异常表现，符合句意。"}], "explanations": {"作业": "搭配：“疼痛”修饰身体感受，“作业”不能疼痛，句意不通。", "烟雾": "语义：烟雾不是疼痛的表现，句意说不通。", "脸庞": "体貌：脸庞说的是面部外形，不是身体的异常表现，不能说“疼痛的脸庞”。", "症状": "吃药后疼痛的症状慢慢消失，“症状”指疾病的异常表现，符合句意。"}, "sentence_index": 6, "correct_answer": "症状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的症状写完了。", "explanation": "这里应该用〈作业〉。“写完”搭配作业、文章等，症状不能被写完。"}, {"text": "我身上只有一张症状。", "explanation": "量词错误：症状应用〈种〉或〈个〉计量，〈张〉用于纸、桌子等扁平的东西。"}, {"text": "他参加了一次症状。", "explanation": "这里应该用〈考试〉。“参加”搭配考试、比赛等活动，症状不能被参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的几种症状们都很明显。", "corrected_sentence": "他的几种症状都很明显。", "error_description": "“们”用错：“们”只加在指人的名词后面，症状不能加“们”，应说“症状都很明显”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的一条症状减轻了。", "corrected_sentence": "他的症状减轻了。", "error_description": "量词错误：症状不用〈条〉计量，〈条〉用于细长的东西，应去掉“一条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
