INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公开发布消息或新产品的会议。", "primary_collocate": null, "pronunciation": "fā bù huì", "ipa": "fa˥˥ pu˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "公司明天开新产品发布会。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机发布会在北京举行。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场发布会吸引了很多记者。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在发布会上回答了问题。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们下个月要开新书发布会。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发布会上，经理介绍了新汽车。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上看了那家公司的发布会。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发布会结束后，记者们都走了。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司每年春天开一次发布会。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影的发布会邀请了很多明星。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场发布会", "label": "量词"}, {"form": "一次发布会", "label": "量词"}, {"form": "新闻发布会", "label": "复合"}, {"form": "产品发布会", "label": "复合"}], "register": "中性", "sense_fingerprint": "公开发布新产品或消息的正式会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发布会", "is_correct": true, "explanation": "正确：“开新产品发布会”指公开发布新产品的会议，符合句中的“新产品”和“开”。"}, {"text": "期末考试", "is_correct": false, "explanation": "语义：期末考试是学校的测验，公司发布新产品时不会举行，句意不通。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是哀悼逝者的仪式，与发布新产品毫无关系。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是为新人举办的仪式，不会用来发布新产品。"}], "explanations": {"发布会": "正确：“开新产品发布会”指公开发布新产品的会议，符合句中的“新产品”和“开”。", "期末考试": "语义：期末考试是学校的测验，公司发布新产品时不会举行，句意不通。", "葬礼": "语义：葬礼是哀悼逝者的仪式，与发布新产品毫无关系。", "婚礼": "语义：婚礼是为新人举办的仪式，不会用来发布新产品。"}, "sentence_index": 0, "correct_answer": "发布会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市长在发布会上跑完了马拉松。", "explanation": "这里应该用〈马拉松赛道〉。发布会是公开宣布消息的会，跑马拉松要在赛道上进行。"}, {"text": "求职者在发布会上递简历。", "explanation": "这里应该用〈招聘会〉。发布会是公开宣布消息的场合，求职者递简历要去招聘会。"}, {"text": "老师在发布会上讲了三个小时的历史。", "explanation": "这里应该用〈讲座〉。发布会是公开宣布消息的会，讲历史要在讲座上进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发布会", "is_correct": true, "explanation": "正确：“看了那家公司的发布会”指看该公司的新品发布，与“在网上看了”相合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只描述人的高矮，不能指公司的活动，句子不通。"}, {"text": "毕业典礼", "is_correct": false, "explanation": "语义：毕业典礼是学校的仪式，公司不会举办毕业典礼供人观看。"}, {"text": "开学典礼", "is_correct": false, "explanation": "语义：开学典礼是学校新学期开始时的仪式，与公司的活动无关。"}], "explanations": {"发布会": "正确：“看了那家公司的发布会”指看该公司的新品发布，与“在网上看了”相合。", "身高": "体貌：“身高”只描述人的高矮，不能指公司的活动，句子不通。", "毕业典礼": "语义：毕业典礼是学校的仪式，公司不会举办毕业典礼供人观看。", "开学典礼": "语义：开学典礼是学校新学期开始时的仪式，与公司的活动无关。"}, "sentence_index": 6, "correct_answer": "发布会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新人在发布会上交换了戒指。", "explanation": "这里应该用〈婚礼〉。发布会是公开宣布消息的会，交换戒指要在婚礼上进行。"}, {"text": "他在发布会上跑赢了所有人。", "explanation": "这里应该用〈运动会〉。发布会是公开宣布消息的会，比赛跑步要在运动会上进行。"}, {"text": "毕业生在发布会上抛起了学士帽。", "explanation": "这里应该用〈毕业典礼〉。发布会是公开宣布消息的会，抛学士帽要在毕业典礼上进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午三点有一条新手机的发布会。", "corrected_sentence": "下午三点有一场新手机的发布会。", "error_description": "量词错误：“发布会”应该用量词“场”或“次”，说“一场发布会”。“条”用于细长的东西，不能修饰会议。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在发布会下拍了照片。", "corrected_sentence": "我们在发布会上拍了照片。", "error_description": "方位词错误：“发布会”后应用方位词“上”，说“发布会上”。“下”表示位置在下方，不能用于会议。正确形式是“我们在发布会上拍了照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
