INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94063, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "确是真的，一点也不假。", "primary_collocate": null, "pronunciation": "què", "ipa": "tɕʰyɛ˥˩", "syllable_count": 1, "sentences": [{"text": "这件事确有其事，不是谣言。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话确是事实。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息确属真实，请大家放心。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的包子确是名不虚传。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他确是我们学校的老师。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位英雄确有其人。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的那件事确是真的，不是编的。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画确是真品，不是假的。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤的消息确属实。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "账单上的数字确无错误。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "確", "label": "繁体"}], "register": "书面", "sense_fingerprint": "确：强调事情真实可靠，不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94063, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "确", "is_correct": true, "explanation": "正确：què（第四声），意思是确实、真的。"}, {"text": "缺", "is_correct": false, "explanation": "quē（第一声）与 què（第四声）声调不同，意思是缺少。"}, {"text": "怯", "is_correct": false, "explanation": "qiè 与 què 介音不同（i 与 ü），声调相同，意思是胆怯。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 què 韵母不同（没有 e 韵尾），声调相同，意思是离开。"}], "explanations": {"确": "正确：què（第四声），意思是确实、真的。", "缺": "quē（第一声）与 què（第四声）声调不同，意思是缺少。", "怯": "qiè 与 què 介音不同（i 与 ü），声调相同，意思是胆怯。", "去": "qù 与 què 韵母不同（没有 e 韵尾），声调相同，意思是离开。"}, "sentence_index": null, "correct_answer": "确"}, "level_3": {"options": [{"text": "只", "is_correct": false, "explanation": "语义：只表示限定范围，不表示真实可靠，与“不是谣言”不合。"}, {"text": "确", "is_correct": true, "explanation": "正确：确表示确实，强调“这件事确有其事”的真实性。"}, {"text": "很", "is_correct": false, "explanation": "搭配：很修饰形容词或心理动词，不能修饰“有其事”。"}, {"text": "未", "is_correct": false, "explanation": "语义：“未有其事”意为没有这回事，与“不是谣言”相反。"}], "explanations": {"只": "语义：只表示限定范围，不表示真实可靠，与“不是谣言”不合。", "确": "正确：确表示确实，强调“这件事确有其事”的真实性。", "很": "搭配：很修饰形容词或心理动词，不能修饰“有其事”。", "未": "语义：“未有其事”意为没有这回事，与“不是谣言”相反。"}, "sentence_index": 0, "correct_answer": "确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们准备了很久，没有确通过考试。", "explanation": "这里应用〈却〉：“我们准备了很久，却没有通过考试”。“确”不能插在“没有”与动词之间。"}, {"text": "这件事是确上个月发生的。", "explanation": "这里应用〈才〉：“这件事是上个月才发生的”。“确”是副词，不能直接修饰时间名词。"}, {"text": "我一看见他确就明白了。", "explanation": "这里应删去〈确〉，直接用〈就〉：“我一看见他就明白了”。“确”不能与“就”并列修饰同一动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94063, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "确", "is_correct": true, "explanation": "正确：què（第四声），意思是确实、真的。"}, {"text": "血", "is_correct": false, "explanation": "xuè 与 què 声母不同（x 与 q），声调相同，意思是血液。"}, {"text": "趣", "is_correct": false, "explanation": "qù 与 què 韵母不同（没有 e 韵尾），声调相同，意思是兴趣。"}, {"text": "窃", "is_correct": false, "explanation": "qiè 与 què 介音不同（i 与 ü），声调相同，意思是偷。"}], "explanations": {"确": "正确：què（第四声），意思是确实、真的。", "血": "xuè 与 què 声母不同（x 与 q），声调相同，意思是血液。", "趣": "qù 与 què 韵母不同（没有 e 韵尾），声调相同，意思是兴趣。", "窃": "qiè 与 què 介音不同（i 与 ü），声调相同，意思是偷。"}, "sentence_index": null, "correct_answer": "确"}, "level_3": {"options": [{"text": "并", "is_correct": false, "explanation": "搭配：并通常与否定词连用，不能直接修饰“是真的”。"}, {"text": "确", "is_correct": true, "explanation": "正确：确强调事情属实，符合“确是真的，不是编的”的句意。"}, {"text": "丝毫", "is_correct": false, "explanation": "搭配：丝毫多用于否定句，不能用于肯定句“是真的”。"}, {"text": "再", "is_correct": false, "explanation": "语义：再表示重复或追加，与事情真假无关。"}], "explanations": {"并": "搭配：并通常与否定词连用，不能直接修饰“是真的”。", "确": "正确：确强调事情属实，符合“确是真的，不是编的”的句意。", "丝毫": "搭配：丝毫多用于否定句，不能用于肯定句“是真的”。", "再": "语义：再表示重复或追加，与事情真假无关。"}, "sentence_index": 6, "correct_answer": "确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子里有确两本书。", "explanation": "这里应用〈只〉：“这个箱子里只有两本书”。“确”不能插在“有”与数量词之间。"}, {"text": "他到家确，还没吃饭。", "explanation": "这里应用〈刚〉：“他刚到家，还没吃饭”。“确”不能用在句末。"}, {"text": "他没确来。", "explanation": "这里应用〈竟然〉：“他竟然没来”。“确”不能插在“没”与动词之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
