INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94064, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "确实；真的。", "primary_collocate": null, "pronunciation": "què", "ipa": "tɕʰyɛ˥˩", "syllable_count": 1, "sentences": [{"text": "这个办法确可行。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的汉语确有很大进步。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天确是很热。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药对感冒确有效果。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我确不知道他去了哪里。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜确很有特色。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法确有道理。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试确比上次难。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李确已回家了。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他确需要我们的帮助。", "target_word": "确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "確", "label": "繁体"}], "register": "书面", "sense_fingerprint": "确：表示情况属实，用来肯定或加强语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id 