INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94064, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "确", "is_correct": true, "explanation": "正确：què（第四声），意思是确实、真的。"}, {"text": "缺", "is_correct": false, "explanation": "quē（第一声）与 què（第四声）声调不同，意思是缺少。"}, {"text": "怯", "is_correct": false, "explanation": "qiè 与 què 介音不同（i 与 ü），声调相同，意思是胆怯。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 què 韵母不同（没有 e 韵尾），声调相同，意思是离开。"}], "explanations": {"确": "正确：què（第四声），意思是确实、真的。", "缺": "quē（第一声）与 què（第四声）声调不同，意思是缺少。", "怯": "qiè 与 què 介音不同（i 与 ü），声调相同，意思是胆怯。", "去": "qù 与 què 韵母不同（没有 e 韵尾），声调相同，意思是离开。"}, "sentence_index": null, "correct_answer": "确"}, "level_3": {"options": [{"text": "再", "is_correct": false, "explanation": "语义：再表示重复或之后，不表示情况属实。"}, {"text": "确", "is_correct": true, "explanation": "正确：确表示情况属实，符合“这个办法确可行”的句意。"}, {"text": "并", "is_correct": false, "explanation": "搭配：并通常与否定词连用，不能直接修饰“可行”。"}, {"text": "丝毫", "is_correct": false, "explanation": "搭配：丝毫用于否定句，不能修饰“可行”。"}], "explanations": {"再": "语义：再表示重复或之后，不表示情况属实。", "确": "正确：确表示情况属实，符合“这个办法确可行”的句意。", "并": "搭配：并通常与否定词连用，不能直接修饰“可行”。", "丝毫": "搭配：丝毫用于否定句，不能修饰“可行”。"}, "sentence_index": 0, "correct_answer": "确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药有很多副作用，有确效果。", "explanation": "这里应用〈却〉：“这种药有很多副作用，却有效果”。“确”不能插在“有”与“效果”之间。"}, {"text": "他昨天吃了确这种药，病就好了。", "explanation": "这里应用〈才〉：“他昨天才吃了这种药”。“确”不能直接修饰“这种药”。"}, {"text": "这个问题我们确明天讨论。", "explanation": "这里应用〈再〉：“这个问题我们明天再讨论”。“确”不能直接修饰时间名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
