INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "江河湖海边供船停靠和装卸货物、乘客上下的地方。", "primary_collocate": null, "pronunciation": "mǎ tou", "ipa": "ma˨˩˦ tʰou", "syllable_count": 2, "sentences": [{"text": "船慢慢开到码头边。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在码头等去岛上的船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "码头上有很多工人在搬货。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个码头每天有三班船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在江边的码头上钓鱼。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货船到了码头，工人开始卸货。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人从码头走上了大船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边新建了一座码头。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船都停在小码头旁边。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船到了对岸的码头，再坐车去城里。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "货运码头", "label": "复合"}, {"form": "碼頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水边供船停靠、装卸货物和上下客的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "码头", "is_correct": true, "explanation": "正确：“码头边”指江河湖海边供船停靠的地方，船开到这里合理。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不临水，船不能开到教室边。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不靠水，船无法开到图书馆边。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：“停车场”是车辆停放的地方，船不会停在那里。"}], "explanations": {"码头": "正确：“码头边”指江河湖海边供船停靠的地方，船开到这里合理。", "教室": "语义：教室不临水，船不能开到教室边。", "图书馆": "语义：图书馆不靠水，船无法开到图书馆边。", "停车场": "搭配：“停车场”是车辆停放的地方，船不会停在那里。"}, "sentence_index": 0, "correct_answer": "码头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在河边新建了一只码头。", "explanation": "这里应该用〈座〉。码头是固定的建筑，量词用“座”，“只”一般用于船、动物等。"}, {"text": "他每周去码头剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，码头是船靠岸、装卸货物的地方。"}, {"text": "这个码头每天有三百位病人就诊。", "explanation": "这里应该用〈医院〉。就诊看病要去医院，码头是船靠岸、装卸货物的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "码头", "is_correct": true, "explanation": "正确：“从码头走上大船”指客人从码头登上大船，符合语境。"}, {"text": "跑道", "is_correct": false, "explanation": "语义：跑道供飞机起降，客人不能从跑道走上大船。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是登船的地方，不能从厨房走上大船。"}, {"text": "卧室", "is_correct": false, "explanation": "搭配：“卧室”不是登船处，与“走上大船”搭配不当。"}], "explanations": {"码头": "正确：“从码头走上大船”指客人从码头登上大船，符合语境。", "跑道": "语义：跑道供飞机起降，客人不能从跑道走上大船。", "厨房": "语义：厨房不是登船的地方，不能从厨房走上大船。", "卧室": "搭配：“卧室”不是登船处，与“走上大船”搭配不当。"}, "sentence_index": 6, "correct_answer": "码头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个码头每天生产三千台机器。", "explanation": "这里应该用〈工厂〉。生产机器的是工厂，码头是船靠岸、装卸货物的地方。"}, {"text": "这个码头养了三百只猴子。", "explanation": "这里应该用〈动物园〉。饲养动物的是动物园，码头是船靠岸、装卸货物的地方。"}, {"text": "这个码头每晚都住满了客人。", "explanation": "这里应该用〈宾馆〉。住宿留客的是宾馆，码头是船靠岸、装卸货物的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里新修了一只码头。", "corrected_sentence": "村里新修了一座码头。", "error_description": "错误：量词“只”一般用于船、动物等，码头是固定建筑，应用“座”。正确：“一座码头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔船靠到这台码头了。", "corrected_sentence": "渔船靠到这个码头了。", "error_description": "错误：码头是固定建筑，量词应用“个”或“座”，“台”一般用于机器、车辆等。正确：“这个码头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
