INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94067, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "笑话是让人听了哈哈大笑的有趣的话。", "primary_collocate": null, "pronunciation": "xiào hua", "ipa": "ɕiɑʊ̯˥˩ xwa", "syllable_count": 2, "sentences": [{"text": "他讲了一个笑话，大家都笑了。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个笑话太好笑了，我笑了很久。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸最爱讲笑话。", "target_word": "笑话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听了他的笑话，全班同学哈哈大笑。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给你讲个笑话吧。", "target_word": "笑话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个笑话我已经听过三次了。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑话一点儿也不好笑。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友讲了一个很冷的笑话，没人笑。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先讲了一个笑话，课堂气氛一下子轻松了。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢听他讲的笑话。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "则", "label": "量词"}, {"form": "冷笑话", "label": "复合"}], "register": "口语", "sense_fingerprint": "笑话|名词|让人听了哈哈大笑的有趣的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "笑话", "is_correct": true, "explanation": "笑话（xiào hua）指让人听了哈哈大笑的有趣的话。"}, {"text": "校花", "is_correct": false, "explanation": "校花（xiàohuā）与笑话的第二个音节声调不同（huā 为阴平，笑话的 hua 读轻声），意思是校园里最漂亮的女生。"}, {"text": "消化", "is_correct": false, "explanation": "消化（xiāohuà）两个音节的声调都与笑话不同，意思是把食物分解并吸收。"}, {"text": "小画", "is_correct": false, "explanation": "小画（xiǎohuà）第一个音节声调不同（xiǎo 为上声），意思是小幅的画。"}], "explanations": {"笑话": "笑话（xiào hua）指让人听了哈哈大笑的有趣的话。", "校花": "校花（xiàohuā）与笑话的第二个音节声调不同（huā 为阴平，笑话的 hua 读轻声），意思是校园里最漂亮的女生。", "消化": "消化（xiāohuà）两个音节的声调都与笑话不同，意思是把食物分解并吸收。", "小画": "小画（xiǎohuà）第一个音节声调不同（xiǎo 为上声），意思是小幅的画。"}, "sentence_index": null, "correct_answer": "笑话"}, "level_3": {"options": [{"text": "笑话", "is_correct": true, "explanation": "笑话指能让人发笑的话，可以“讲了一个”，后句“大家都笑了”也与之呼应。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讲”后面不能接“窗户”，窗户不是可以讲述的内容。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不是可以讲述的内容，也与“大家都笑了”的情境冲突。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“讲了一个”说的是可以讲述的内容，闹钟不能被讲述。"}], "explanations": {"笑话": "笑话指能让人发笑的话，可以“讲了一个”，后句“大家都笑了”也与之呼应。", "窗户": "搭配：“讲”后面不能接“窗户”，窗户不是可以讲述的内容。", "眼泪": "语义：眼泪不是可以讲述的内容，也与“大家都笑了”的情境冲突。", "闹钟": "搭配：“讲了一个”说的是可以讲述的内容，闹钟不能被讲述。"}, "sentence_index": 0, "correct_answer": "笑话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部长篇小说的笑话情节非常曲折。", "explanation": "这里应该用〈故事〉。“情节曲折”说的是故事，笑话是短小、只为逗人笑的话，不能这样用。"}, {"text": "别笑话我，我的普通话还不太标准。", "explanation": "这里的“笑话”是动词，意思是嘲笑别人，不是指能引人发笑的话，与本句所要表达的意思不同。"}, {"text": "他这次忘了台词，成了全场的笑话。", "explanation": "这里的“笑话”指成为大家嘲笑的对象，是另一个意思，不是能让人发笑的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑话", "is_correct": true, "explanation": "笑话指能让人发笑的话，“不好笑”正是对这种话的评价。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是能“好笑”或“不好笑”的内容，这个评价用在椅子上说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞本身不能被评价为“好笑”，与“一点儿也不好笑”的说法冲突。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能被评价为“好笑”或“不好笑”，这个评价用在钥匙上说不通。"}], "explanations": {"笑话": "笑话指能让人发笑的话，“不好笑”正是对这种话的评价。", "椅子": "语义：椅子不是能“好笑”或“不好笑”的内容，这个评价用在椅子上说不通。", "雨伞": "语义：雨伞本身不能被评价为“好笑”，与“一点儿也不好笑”的说法冲突。", "钥匙": "语义：钥匙不能被评价为“好笑”或“不好笑”，这个评价用在钥匙上说不通。"}, "sentence_index": 6, "correct_answer": "笑话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他高兴得发出一阵笑话，大家都回头看他。", "explanation": "这里应该用〈笑声〉。“发出”后接的是声音，笑话是言语内容，不能说“发出一阵笑话”。"}, {"text": "他摔了一跤，成了大家的笑话。", "explanation": "这里的“笑话”指被人嘲笑的对象，是另一个意思，不是能让人发笑的话。"}, {"text": "这次考试没考好，他被大家当成了笑话。", "explanation": "这里的“笑话”指被大家嘲笑的对象，是另一个意思，不是能让人发笑的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天听了一本笑话，笑了很久。", "corrected_sentence": "我昨天听了一个笑话，笑了很久。", "error_description": "量词错误：“笑话”应使用量词“个”，不用“本”。“本”用于书籍，“一本笑话”只能指笑话书；这里说的是口头讲的笑话，应说“一个笑话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲了一条笑话，大家都笑个不停。", "corrected_sentence": "他讲了一个笑话，大家都笑个不停。", "error_description": "量词错误：“条”用于细长的事物，不用来数笑话；应说“一个笑话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
