INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能引人发笑的话或故事。", "primary_collocate": null, "pronunciation": "xiào hua", "ipa": "ɕiɑʊ̯˥˩ xwa", "syllable_count": 2, "sentences": [{"text": "这个关于小狗的笑话很有意思。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是在饭桌上讲笑话。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶给孙子讲了一个有趣的笑话。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上看到一个笑话，笑了半天。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了几个笑话，发给朋友们看。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笑话的最后一句最好笑。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我记不住那么长的笑话。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲的笑话，我听不懂。", "target_word": "笑话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听完这个笑话，没有人觉得好笑。", "target_word": "笑话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再讲一个笑话吧。", "target_word": "笑话", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "则", "label": "量词"}, {"form": "冷笑话", "label": "复合"}], "register": "口语", "sense_fingerprint": "笑话|名词|能引人发笑的话或故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笑话", "is_correct": true, "explanation": "笑话指能引人发笑的话或故事，“很有意思”正是对它的评价。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单不是有意思的故事，“很有意思”用来评价账单说不通。"}, {"text": "血压", "is_correct": false, "explanation": "语义：血压是生理指标，不是可以讲述的故事，与“很有意思”的评价不符。"}, {"text": "公文", "is_correct": false, "explanation": "语义：公文是公务文书，不是能引人发笑的话或故事，用“很有意思”来评价公文说不通。"}], "explanations": {"笑话": "笑话指能引人发笑的话或故事，“很有意思”正是对它的评价。", "账单": "语义：账单不是有意思的故事，“很有意思”用来评价账单说不通。", "血压": "语义：血压是生理指标，不是可以讲述的故事，与“很有意思”的评价不符。", "公文": "语义：公文是公务文书，不是能引人发笑的话或故事，用“很有意思”来评价公文说不通。"}, "sentence_index": 0, "correct_answer": "笑话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都在笑话他，他却一点儿也不在意。", "explanation": "这里的“笑话”是动词，意思是嘲笑，与指能引人发笑的话或故事的名词不同。"}, {"text": "他看见我，露出一个笑话。", "explanation": "这里应该用〈笑容〉。“露出”后接的是表情，笑话不是表情，不能这样说。"}, {"text": "这次比赛我输得很惨，成了全队的笑话。", "explanation": "这里的“笑话”指被人嘲笑的对象，是另一个意思，不是能让人发笑的话或故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑话", "is_correct": true, "explanation": "笑话是可以记住、讲述的内容，“记不住那么长的”指的正是这类话。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以像故事那样记住的内容，与“那么长的”也搭配不上。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是金属导线，不能被“记住”，与“记不住那么长的”所指的可记忆内容不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“记不住”所针对的应是可以记忆的内容，冰箱不能用“那么长的”和“记不住”来描述。"}], "explanations": {"笑话": "笑话是可以记住、讲述的内容，“记不住那么长的”指的正是这类话。", "心情": "语义：心情不是可以像故事那样记住的内容，与“那么长的”也搭配不上。", "电线": "语义：电线是金属导线，不能被“记住”，与“记不住那么长的”所指的可记忆内容不符。", "冰箱": "搭配：“记不住”所针对的应是可以记忆的内容，冰箱不能用“那么长的”和“记不住”来描述。"}, "sentence_index": 6, "correct_answer": "笑话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演出结束后，观众发出一阵笑话，大家都笑了。", "explanation": "这里应该用〈掌声〉。“发出”后接的是声音，笑话是言语内容，不能用“发出”来修饰。"}, {"text": "我这次又出了丑，成了大家的笑话。", "explanation": "这里的“笑话”指被人嘲笑的对象，是另一个意思，不是能让人发笑的话。"}, {"text": "他的失误让全班都把他当成了笑话。", "explanation": "这里的“笑话”指被全班嘲笑的对象，是另一个意思，不是能让人发笑的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前在书上看过这只笑话。", "corrected_sentence": "我以前在书上看过这个笑话。", "error_description": "量词错误：“笑话”的量词应用“个”或“则”，不用“只”（“只”多用于动物等）。应说“看过这个笑话”，不说“看过这只笑话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把那首笑话讲给我们听。", "corrected_sentence": "妈妈把那个笑话讲给我们听。", "error_description": "量词错误：“首”用于诗词、歌曲，不用来数笑话；应说“那个笑话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有希望", "is_correct": true, "explanation": "“有希望”与“绝望”相对，指心里还存有盼头。"}, {"text": "平静", "is_correct": false, "explanation": "“平静”指心情安稳，不是“绝望”的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“绝望”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“绝望”没有反义关系。"}], "correct_answer": "有希望", "explanations": {"有希望": "“有希望”与“绝望”相对，指心里还存有盼头。", "平静": "“平静”指心情安稳，不是“绝望”的反义词。", "清楚": "“清楚”指明白、不模糊，与“绝望”没有反义关系。", "整齐": "“整齐”指排列有序，与“绝望”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有希望", "is_correct": true, "explanation": "“有希望”与“绝望”相对，指心里还存有盼头。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不紧张、不费力，与“绝望”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”指态度认真或庄重，与“绝望”没有反义关系。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”指干净利落，与“绝望”没有反义关系。"}], "correct_answer": "有希望", "explanations": {"有希望": "“有希望”与“绝望”相对，指心里还存有盼头。", "轻松": "“轻松”指不紧张、不费力，与“绝望”没有反义关系。", "严肃": "“严肃”指态度认真或庄重，与“绝望”没有反义关系。", "整洁": "“整洁”指干净利落，与“绝望”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "绝望是心里觉得再也没有办法了，一点盼头也没有。", "primary_collocate": null, "pronunciation": "jué wàng", "ipa": "tɕɥe˧˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "考试没过，他心里很绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她绝望地坐在地上哭了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了一个月工作，越找越绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着空空的钱包，觉得很绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迷路的人在大雨里感到绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绝望的眼神让人心疼。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人帮忙，她一个人绝望极了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那个坏消息，大家都很绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一次次失败，一天比一天绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太绝望，也许明天会有办法。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝望地", "label": "状语形式"}, {"form": "绝望了", "label": "体标"}, {"form": "絕望", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里觉得没有办法、没有盼头的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”指心里觉得没有办法、没有盼头，与“考试没过”的情境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：考试没过，心里不会高兴，与句中的情况相反。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容心情。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写人的身材，不能用来说心里的感受。"}], "explanations": {"绝望": "“绝望”指心里觉得没有办法、没有盼头，与“考试没过”的情境相符。", "高兴": "语义：考试没过，心里不会高兴，与句中的情况相反。", "清脆": "搭配：“清脆”形容声音，不能用来形容心情。", "高大": "体貌：“高大”描写人的身材，不能用来说心里的感受。"}, "sentence_index": 0, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他收到录取通知，绝望地跳了起来。", "explanation": "这里应该用〈高兴〉。收到录取通知是喜事，“绝望”表示彻底没有希望，不能用来修饰高兴地跳起来的动作。"}, {"text": "他刚买的新车特别好，他很绝望。", "explanation": "这里应该用〈满意〉。买到称心的新车是好事，“绝望”表示彻底没有希望，与此矛盾。"}, {"text": "听到好消息，她终于绝望了。", "explanation": "这里应该用〈放心〉。听到好消息应该说“放心”，“绝望”表示彻底没有希望，与好消息正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”指彻底没有希望，与“没有人帮忙、一个人”的处境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声响，与“没有人帮忙”“一个人”矛盾。"}, {"text": "齐全", "is_correct": false, "explanation": "搭配：“齐全”指东西完备，不能用来形容人的心情。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或眼神，不用来说心里的感受。"}], "explanations": {"绝望": "“绝望”指彻底没有希望，与“没有人帮忙、一个人”的处境相符。", "热闹": "语义：“热闹”指人多、有声响，与“没有人帮忙”“一个人”矛盾。", "齐全": "搭配：“齐全”指东西完备，不能用来形容人的心情。", "明亮": "体貌：“明亮”形容光线或眼神，不用来说心里的感受。"}, "sentence_index": 6, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考了全班第一，很绝望。", "explanation": "这里应该用〈得意〉。考了全班第一是值得骄傲的事，“绝望”表示彻底没有希望，两者正好相反。"}, {"text": "手术很顺利，家人都很绝望。", "explanation": "这里应该用〈安心〉。手术顺利时家人应该安心，“绝望”表示彻底没有希望，与结果相反。"}, {"text": "天气很好，我特别绝望。", "explanation": "这里应该用〈愉快〉。天气好时心情应该说“愉快”，“绝望”表示彻底没有希望，两者正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他绝望的看着窗外的雨。", "corrected_sentence": "他绝望地看着窗外的雨。", "error_description": "“绝望”修饰动词“看”时要用“地”，不能用“的”。应说“绝望地看着”，写成“绝望的看着”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找不到出路，成了绝望地人。", "corrected_sentence": "我找不到出路，成了绝望的人。", "error_description": "“绝望”修饰名词“人”时要用“的”，不能用“地”。“地”用来修饰动词或形容词，此处“绝望地人”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "希望", "is_correct": true, "explanation": "“希望”与“绝望”相对，指对事情仍抱有盼望。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指动脑子想问题，与“绝望”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指大家交换意见，与“绝望”没有反义关系。"}, {"text": "解释", "is_correct": false, "explanation": "“解释”指说明道理，与“绝望”没有反义关系。"}], "correct_answer": "希望", "explanations": {"希望": "“希望”与“绝望”相对，指对事情仍抱有盼望。", "思考": "“思考”指动脑子想问题，与“绝望”没有反义关系。", "讨论": "“讨论”指大家交换意见，与“绝望”没有反义关系。", "解释": "“解释”指说明道理，与“绝望”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "希望", "is_correct": true, "explanation": "“希望”与“绝望”相对，指对事情仍抱有盼望。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把杂乱的东西归置好，与“绝望”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨问题，与“绝望”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“绝望”没有反义关系。"}], "correct_answer": "希望", "explanations": {"希望": "“希望”与“绝望”相对，指对事情仍抱有盼望。", "整理": "“整理”指把杂乱的东西归置好，与“绝望”没有反义关系。", "研究": "“研究”指深入探讨问题，与“绝望”没有反义关系。", "旅行": "“旅行”指到外地游览，与“绝望”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "完全失去希望，认为不可能再有转机。", "primary_collocate": null, "pronunciation": "jué wàng", "ipa": "tɕɥe˧˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他对生活绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说还有办法，你别绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这个人已经绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的家人从没有绝望过。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的未来完全绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援还在继续，我们不能对他绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟对学习绝望，不想再读书了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对儿子绝望，决定一个人生活。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛只剩一分钟，球迷对结果绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾经对爱情绝望，现在又相信了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝望了", "label": "体标"}, {"form": "绝望过", "label": "体标"}, {"form": "絕望", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事完全失去希望，认为没有转机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”作动词，表示对生活完全失去希望，与句子相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说“对生活参观”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不能用于“生活”。"}, {"text": "瞻仰", "is_correct": false, "explanation": "语域：“瞻仰”是书面语，只用于人物或遗迹，不能说“对生活瞻仰”。"}], "explanations": {"绝望": "“绝望”作动词，表示对生活完全失去希望，与句子相符。", "参观": "搭配：“参观”的对象是场所或展览，不能说“对生活参观”。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不能用于“生活”。", "瞻仰": "语域：“瞻仰”是书面语，只用于人物或遗迹，不能说“对生活瞻仰”。"}, "sentence_index": 0, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务好极了，我对它很绝望。", "explanation": "这里应该用〈满意〉。服务好极了应该说“满意”，“绝望”表示对事情彻底不抱希望，与这样的评价矛盾。"}, {"text": "学校为他安排了好老师，他对此很绝望。", "explanation": "这里应该用〈欣慰〉。学校安排了好老师是让人欣慰的事，“绝望”表示彻底不抱希望，与此相反。"}, {"text": "孩子的身体已经完全康复了，她对此很绝望。", "explanation": "这里应该用〈放心〉。身体康复后应该说“放心”，“绝望”表示对事情不再抱任何希望，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”作动词，表示对学习失去希望，与后句“不想再读书了”相符。"}, {"text": "热衷", "is_correct": false, "explanation": "语义：“热衷”表示积极投入，与后句“不想再读书了”矛盾。"}, {"text": "请教", "is_correct": false, "explanation": "配价：“请教”要求说明对象是人，不能带“对学习”这样的宾语。"}, {"text": "珍惜", "is_correct": false, "explanation": "搭配：“珍惜”直接带宾语（如“珍惜时间”），不说“对学习珍惜”，且与后句“不想再读书了”矛盾。"}], "explanations": {"绝望": "“绝望”作动词，表示对学习失去希望，与后句“不想再读书了”相符。", "热衷": "语义：“热衷”表示积极投入，与后句“不想再读书了”矛盾。", "请教": "配价：“请教”要求说明对象是人，不能带“对学习”这样的宾语。", "珍惜": "搭配：“珍惜”直接带宾语（如“珍惜时间”），不说“对学习珍惜”，且与后句“不想再读书了”矛盾。"}, "sentence_index": 6, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们大获全胜，大家都很绝望。", "explanation": "这里应该用〈兴奋〉。大获全胜是令人振奋的事，“绝望”表示对事情彻底不抱希望，与此矛盾。"}, {"text": "他拿到了满分，妈妈为此很绝望。", "explanation": "这里应该用〈骄傲〉。拿到满分值得骄傲，“绝望”表示彻底失去希望，两者正好相反。"}, {"text": "终于找到了失散多年的亲人，她很绝望。", "explanation": "这里应该用〈激动〉。找到失散多年的亲人是让人激动的事，“绝望”表示不再抱任何希望，不能用于这种情形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这份工作绝望了。", "corrected_sentence": "他对这份工作绝望了。", "error_description": "“绝望”作动词时，它的对象要由介词“对”引出，漏掉“对”就不通。应说“他对这份工作绝望了”，不能说“他这份工作绝望了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟这场比赛绝望过，后来又振作起来了。", "corrected_sentence": "他对这场比赛绝望过，后来又振作起来了。", "error_description": "“绝望”的对象要由介词“对”引出，不能用“跟”。应说“对这场比赛绝望过”，不能说“跟这场比赛绝望过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
