INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94071, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "练是一遍又一遍地做，直到做得越来越好。", "primary_collocate": null, "pronunciation": "liàn", "ipa": "ljɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这首歌我练了十遍，还是不太好。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一遍又一遍地练这个动作。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多练几次，你就会做得更好。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她练舞练到很晚才回家。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在家练篮球，投得越来越准。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车要多练，才不会害怕。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天练写汉字，进步很快。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把这首曲子练了又练。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再练练，一定能做得更好。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每个周末都去公园练太极拳。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "练了", "label": "体标"}, {"form": "练过", "label": "体标"}, {"form": "练练", "label": "重叠"}, {"form": "練", "label": "繁体"}], "register": "中性", "sense_fingerprint": "练：一遍又一遍地做，直到越来越好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94071, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "练", "is_correct": true, "explanation": "正确答案：练（liàn），意思是一遍又一遍地做，直到越来越好。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn 与 liàn 声调不同（第三声与第四声），意思是脸部。"}, {"text": "联", "is_correct": false, "explanation": "lián 与 liàn 声调不同（第二声与第四声），意思是联合、联系。"}, {"text": "量", "is_correct": false, "explanation": "liàng 与 liàn 韵母不同（-ang 与 -an），意思是数量、测量。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 liàn 声母不同（j 与 l），意思是看见。"}], "explanations": {"练": "正确答案：练（liàn），意思是一遍又一遍地做，直到越来越好。", "脸": "liǎn 与 liàn 声调不同（第三声与第四声），意思是脸部。", "联": "lián 与 liàn 声调不同（第二声与第四声），意思是联合、联系。", "量": "liàng 与 liàn 韵母不同（-ang 与 -an），意思是数量、测量。", "见": "jiàn 与 liàn 声母不同（j 与 l），意思是看见。"}, "sentence_index": null, "correct_answer": "练"}, "level_3": {"options": [{"text": "练", "is_correct": true, "explanation": "“练”表示一遍又一遍地做，与“练了十遍”的句意相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与唱歌、学习的意思无关，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“这首歌”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“歌”搭配，不能说喝这首歌。"}], "explanations": {"练": "“练”表示一遍又一遍地做，与“练了十遍”的句意相合。", "吃": "语义：“吃”与唱歌、学习的意思无关，句子不通。", "睡": "配价：“睡”是不及物动词，不能带“这首歌”作宾语。", "喝": "搭配：“喝”不能与“歌”搭配，不能说喝这首歌。"}, "sentence_index": 0, "correct_answer": "练"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在炉子里练铁，把铁变得更纯。", "explanation": "这里应该用〈炼〉。练指反复操练技能，炼指用高温熔化、提纯金属，如炼铁。"}, {"text": "这双鞋我练了一下，很合脚。", "explanation": "这里应该用〈试〉。试鞋是试穿看合不合脚，练指反复操练技能，不能用于试穿鞋子。"}, {"text": "他在路边练了一块漂亮的石头。", "explanation": "这里应该用〈捡〉。捡是从地上拿起东西，练指反复操练技能，不能用于拿石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94071, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "练", "is_correct": true, "explanation": "正确答案：练（liàn），意思是一遍又一遍地做，直到越来越好。"}, {"text": "念", "is_correct": false, "explanation": "niàn 与 liàn 声母不同（n 与 l），意思是念书、朗读。"}, {"text": "亮", "is_correct": false, "explanation": "liàng 与 liàn 韵母不同（-ang 与 -an），意思是明亮。"}, {"text": "电", "is_correct": false, "explanation": "diàn 与 liàn 声母不同（d 与 l），意思是电力、电子。"}], "explanations": {"练": "正确答案：练（liàn），意思是一遍又一遍地做，直到越来越好。", "念": "niàn 与 liàn 声母不同（n 与 l），意思是念书、朗读。", "亮": "liàng 与 liàn 韵母不同（-ang 与 -an），意思是明亮。", "电": "diàn 与 liàn 声母不同（d 与 l），意思是电力、电子。"}, "sentence_index": null, "correct_answer": "练"}, "level_3": {"options": [{"text": "练", "is_correct": true, "explanation": "“练”表示反复操练，直到写得越来越好，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能与“汉字”搭配，不能说跳写汉字。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“汉字”搭配，汉字不能咬。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”与写字的意思无关，句子不通。"}], "explanations": {"练": "“练”表示反复操练，直到写得越来越好，符合句意。", "跳": "搭配：“跳”不能与“汉字”搭配，不能说跳写汉字。", "咬": "搭配：“咬”不能与“汉字”搭配，汉字不能咬。", "骑": "语义：“骑”与写字的意思无关，句子不通。"}, "sentence_index": 6, "correct_answer": "练"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师每周练我们一次拼音，希望我们进步。", "explanation": "这里应该用〈教〉。练是学习者自己反复操练，老师传授知识要用教。"}, {"text": "她终于练成了每天运动的习惯。", "explanation": "这里应该用〈养成〉。习惯要说养成，练成多用于本领、技艺，如练成绝技。"}, {"text": "他们每个周末都去公园练一个朋友。", "explanation": "练只用于可以反复操练的技能或动作，宾语不能是“朋友”这样的人。这里说的是交朋友，不是操练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天练着三个小时的钢琴。", "corrected_sentence": "他昨天练了三个小时的钢琴。", "error_description": "体标错误：表示昨天已经完成、持续了三个小时的练习，“练”后要用“了”，不能用表示状态持续的“着”，应说“练了三个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不练过游泳，所以不敢下水。", "corrected_sentence": "他没练过游泳，所以不敢下水。", "error_description": "错误在“练”前的否定词：表示过去没有这种经历，要用“没”，不能用“不”，应说“没练过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
