INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反复学习或操练，以求熟练或提高技能。", "primary_collocate": null, "pronunciation": "liàn", "ipa": "ljɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他每天早上练一个小时钢琴。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想练好口语，所以常找朋友聊天。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在操场上练跑步。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想写好字，就得天天练。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多练，才能提高水平。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟练了三年书法。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在教室练唱歌，老师在旁边听着。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练过游泳，所以游得很快。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，她对着镜子练了好几遍。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想考好，就要多练题。", "target_word": "练", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "练了", "label": "体标"}, {"form": "练过", "label": "体标"}, {"form": "练练", "label": "重叠"}, {"form": "練", "label": "繁体"}], "register": "中性", "sense_fingerprint": "练：反复学习、操练，为了熟练或提高技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "练", "is_correct": true, "explanation": "正确答案：练（liàn），意思是反复操练以求熟练。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 liàn 声调不同（第二声与第四声），意思是连接。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn 与 liàn 声调不同（第三声与第四声），意思是脸部。"}, {"text": "念", "is_correct": false, "explanation": "niàn 与 liàn 声母不同（n 与 l），意思是念书、朗读。"}, {"text": "亮", "is_correct": false, "explanation": "liàng 与 liàn 韵母不同（-ang 与 -an），意思是明亮。"}], "explanations": {"练": "正确答案：练（liàn），意思是反复操练以求熟练。", "连": "lián 与 liàn 声调不同（第二声与第四声），意思是连接。", "脸": "liǎn 与 liàn 声调不同（第三声与第四声），意思是脸部。", "念": "niàn 与 liàn 声母不同（n 与 l），意思是念书、朗读。", "亮": "liàng 与 liàn 韵母不同（-ang 与 -an），意思是明亮。"}, "sentence_index": null, "correct_answer": "练"}, "level_3": {"options": [{"text": "练", "is_correct": true, "explanation": "“练”表示反复操练，与每天练琴的句意相合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“钢琴”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“钢琴”搭配，钢琴不能喝。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”表示记不住，与每天练琴的意思相反。"}], "explanations": {"练": "“练”表示反复操练，与每天练琴的句意相合。", "睡": "配价：“睡”是不及物动词，不能带“钢琴”作宾语。", "喝": "搭配：“喝”不能与“钢琴”搭配，钢琴不能喝。", "忘": "语义：“忘”表示记不住，与每天练琴的意思相反。"}, "sentence_index": 0, "correct_answer": "练"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在炉子里练钢，把铁变得更纯。", "explanation": "这里应该用〈炼〉。练指反复操练技能，炼指用高温熔化、提纯金属，如炼钢。"}, {"text": "这件衣服我练了一下，很合身。", "explanation": "这里应该用〈试〉。试衣服是试穿看合不合身，练指反复操练技能，不能用于试穿衣服。"}, {"text": "他每天练一个小时的电视。", "explanation": "练只用于可以反复操练的技能或动作，宾语不能是“电视”这样的事物。这里说的是看电视，不是操练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
