INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹每天练很认真，进步很快。", "corrected_sentence": "妹妹每天练得很认真，进步很快。", "error_description": "错误在“练”后的程度补语：要用“得”引出补语，应说“练得很认真”，漏掉“得”说“练很认真”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天她练一个小时舞，腿都酸了。", "corrected_sentence": "昨天她练了一个小时舞，腿都酸了。", "error_description": "错误在“练”后的“了”：表示已经完成的动作，“昨天”之后应说“练了一个小时”，漏掉“了”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与“聚集”相反，指人或物从一处散开，是反义词"}, {"text": "生长", "is_correct": false, "explanation": "生长：同为动词，但与“聚集”没有反义或近义关系"}, {"text": "保持", "is_correct": false, "explanation": "保持：指维持原样，与“聚集”的意思无关"}, {"text": "修建", "is_correct": false, "explanation": "修建：指建造工程，与“聚集”的意思不相关"}], "correct_answer": "分散", "explanations": {"分散": "分散：与“聚集”相反，指人或物从一处散开，是反义词", "生长": "生长：同为动词，但与“聚集”没有反义或近义关系", "保持": "保持：指维持原样，与“聚集”的意思无关", "修建": "修建：指建造工程，与“聚集”的意思不相关"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与“聚集”相反，指人或物从一处散开，是反义词"}, {"text": "停留", "is_correct": false, "explanation": "停留：指暂时待在某处，与“聚集”没有反义关系"}, {"text": "运转", "is_correct": false, "explanation": "运转：指机器或天体运行，与“聚集”的意思不相关"}, {"text": "写作", "is_correct": false, "explanation": "写作：指写文章，与“聚集”没有反义或近义关系"}], "correct_answer": "分散", "explanations": {"分散": "分散：与“聚集”相反，指人或物从一处散开，是反义词", "停留": "停留：指暂时待在某处，与“聚集”没有反义关系", "运转": "运转：指机器或天体运行，与“聚集”的意思不相关", "写作": "写作：指写文章，与“聚集”没有反义或近义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚集是很多人或很多东西来到同一个地方。", "primary_collocate": null, "pronunciation": "jù jí", "ipa": "tɕy˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "广场上聚集了很多人。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，孩子们聚集在操场上玩。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，鸟儿都聚集在那棵大树上。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，亲戚们聚集在奶奶家。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口聚集着一群等车的人。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到响声，邻居们很快聚集到楼下。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末公园里聚集了不少跳舞的人。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼聚集在桥下，等着吃东西。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们聚集在山顶看日出。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们常常聚集在小区门口聊天。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚集了", "label": "体标（完成）"}, {"form": "聚集着", "label": "体标（持续）"}, {"form": "聚集过", "label": "体标（经历）"}, {"form": "聚集地", "label": "复合词"}], "register": "中性", "sense_fingerprint": "很多人或动物来到同一个地方，聚在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "续集", "is_correct": false, "explanation": "续集（xù jí）与“聚集”第一个音节声母不同（x 与 j），意思是故事的续篇"}, {"text": "距离", "is_correct": false, "explanation": "距离（jù lí）与“聚集”第二个音节声母不同（l 与 j），意思是两地之间的间隔"}, {"text": "聚集", "is_correct": true, "explanation": "聚集（jù jí）：许多人或东西来到同一处，正是要听的词"}, {"text": "局级", "is_correct": false, "explanation": "局级（jú jí）与“聚集”第一个音节声调不同（jú 第二声，jù 第四声），意思是政府机关的局一级"}, {"text": "聚积", "is_correct": false, "explanation": "聚积（jù jī）与“聚集”第二个音节声调不同（jī 第一声，jí 第二声），意思是逐渐积累"}], "explanations": {"续集": "续集（xù jí）与“聚集”第一个音节声母不同（x 与 j），意思是故事的续篇", "距离": "距离（jù lí）与“聚集”第二个音节声母不同（l 与 j），意思是两地之间的间隔", "聚集": "聚集（jù jí）：许多人或东西来到同一处，正是要听的词", "局级": "局级（jú jí）与“聚集”第一个音节声调不同（jú 第二声，jù 第四声），意思是政府机关的局一级", "聚积": "聚积（jù jī）与“聚集”第二个音节声调不同（jī 第一声，jí 第二声），意思是逐渐积累"}, "sentence_index": null, "correct_answer": "聚集"}, "level_3": {"options": [{"text": "飞", "is_correct": false, "explanation": "语义：“飞”指飞行，人不能飞，“广场上飞了很多人”不合逻辑"}, {"text": "聚集", "is_correct": true, "explanation": "聚集：许多人从各处来到同一处，与句中“广场上”“很多人”相符"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”的宾语是物品，不能带人作宾语"}, {"text": "摆", "is_correct": false, "explanation": "搭配：“摆”指陈设物品，不能说摆了很多人"}], "explanations": {"飞": "语义：“飞”指飞行，人不能飞，“广场上飞了很多人”不合逻辑", "聚集": "聚集：许多人从各处来到同一处，与句中“广场上”“很多人”相符", "搬": "配价：“搬”的宾语是物品，不能带人作宾语", "摆": "搭配：“摆”指陈设物品，不能说摆了很多人"}, "sentence_index": 0, "correct_answer": "聚集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小就爱聚集邮票。", "explanation": "这里应该用〈收集〉。收集指有目的地搜集东西，聚集指许多人或物来到同一处，不能用于搜集邮票"}, {"text": "下课前，老师把大家的作业聚集起来交给校长。", "explanation": "这里应该用〈收〉。收作业指把各人的作业拿到一起；聚集指许多人或物自己来到同一处，不能用于人把作业收齐"}, {"text": "他在这一行干了十年，聚集了很多经验。", "explanation": "这里应该用〈积累〉。积累指逐渐增多地存留，经验是慢慢积累起来的；聚集指人或物来到同一处，不说聚集经验"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "狙击", "is_correct": false, "explanation": "狙击（jū jī）与“聚集”两个音节声调都不同（jū 第一声、jī 第一声），意思是暗中伺机射击"}, {"text": "据悉", "is_correct": false, "explanation": "据悉（jù xī）与“聚集”第二个音节声母和声调不同（xī 与 jí），意思是根据得到的消息知道"}, {"text": "聚集", "is_correct": true, "explanation": "聚集（jù jí）：许多人或东西来到同一处，正是要听的词"}, {"text": "据实", "is_correct": false, "explanation": "据实（jù shí）与“聚集”第二个音节声母不同（sh 与 j），意思是依照实际情况"}], "explanations": {"狙击": "狙击（jū jī）与“聚集”两个音节声调都不同（jū 第一声、jī 第一声），意思是暗中伺机射击", "据悉": "据悉（jù xī）与“聚集”第二个音节声母和声调不同（xī 与 jí），意思是根据得到的消息知道", "聚集": "聚集（jù jí）：许多人或东西来到同一处，正是要听的词", "据实": "据实（jù shí）与“聚集”第二个音节声母不同（sh 与 j），意思是依照实际情况"}, "sentence_index": null, "correct_answer": "聚集"}, "level_3": {"options": [{"text": "装", "is_correct": false, "explanation": "语义：“装”指装载或假装，与“跳舞的人”不搭"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”说挂物件，不能说挂了人"}, {"text": "聚集", "is_correct": true, "explanation": "聚集：许多人来到同一处，与句意相符"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，句子说的是人群，不合逻辑"}], "explanations": {"装": "语义：“装”指装载或假装，与“跳舞的人”不搭", "挂": "搭配：“挂”说挂物件，不能说挂了人", "聚集": "聚集：许多人来到同一处，与句意相符", "扔": "语义：“扔”是丢弃，句子说的是人群，不合逻辑"}, "sentence_index": 6, "correct_answer": "聚集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司聚集以后，规模一下子大了很多。", "explanation": "这里应该用〈合并〉。合并指两个或几个合成一个；聚集只是人或物来到同一处，不能说公司聚集成一体"}, {"text": "大家聚集了三百块钱，给他买了生日礼物。", "explanation": "这里应该用〈凑〉。凑钱是各人出一部分钱，“聚集”只用于人或东西自然来到一处，不能用于钱款"}, {"text": "他把旧报纸聚集在墙角，准备下个月卖掉。", "explanation": "这里应该用〈堆〉。堆指把东西一层层放在一处，“聚集”不能用来说人把物品摆成一堆"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们听到消息，很快都聚集了操场上。", "corrected_sentence": "学生们听到消息，很快都聚集到操场上。", "error_description": "“聚集”后引出地点要用介词“到”，不能说“聚集了操场上”，应说“聚集到操场上”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们听到铃声，很快聚集下来。", "corrected_sentence": "孩子们听到铃声，很快聚集起来。", "error_description": "“聚集”的趋向补语应用“起来”，不能说“下来”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
