INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "许多人或事物从各处集中到一处。", "primary_collocate": null, "pronunciation": "jù jí", "ipa": "tɕy˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "各地的客人都聚集到北京参加会议。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司聚集了来自各国的人才。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的云从四面八方聚集过来。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的目光都聚集在她身上。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市聚集了很多有名的大学。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们从各个学校聚集到这里比赛。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的资金都聚集到这个城市。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从各个村子来的人聚集在镇上开会。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越来越多的力量聚集到一起。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们从各地聚集到这里盖房子。", "target_word": "聚集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚集了", "label": "体标（完成）"}, {"form": "聚集着", "label": "体标（持续）"}, {"form": "聚集过", "label": "体标（经历）"}, {"form": "聚集地", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人、资金、目光等从各个地方集中到一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94074, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "续集", "is_correct": false, "explanation": "续集（xù jí）与“聚集”第一个音节声母不同（x 与 j），意思是故事的续篇"}, {"text": "聚集", "is_correct": true, "explanation": "聚集（jù jí）：许多人或物从各处来到一处，正是要听的词"}, {"text": "距离", "is_correct": false, "explanation": "距离（jù lí）与“聚集”第二个音节声母不同（l 与 j），意思是两地之间的间隔"}, {"text": "局级", "is_correct": false, "explanation": "局级（jú jí）与“聚集”第一个音节声调不同（jú 第二声，jù 第四声），意思是政府机关的局一级"}, {"text": "聚积", "is_correct": false, "explanation": "聚积（jù jī）与“聚集”第二个音节声调不同（jī 第一声，jí 第二声），意思是逐渐积累"}], "explanations": {"续集": "续集（xù jí）与“聚集”第一个音节声母不同（x 与 j），意思是故事的续篇", "聚集": "聚集（jù jí）：许多人或物从各处来到一处，正是要听的词", "距离": "距离（jù lí）与“聚集”第二个音节声母不同（l 与 j），意思是两地之间的间隔", "局级": "局级（jú jí）与“聚集”第一个音节声调不同（jú 第二声，jù 第四声），意思是政府机关的局一级", "聚积": "聚积（jù jī）与“聚集”第二个音节声调不同（jī 第一声，jí 第二声），意思是逐渐积累"}, "sentence_index": null, "correct_answer": "聚集"}, "level_3": {"options": [{"text": "寄", "is_correct": false, "explanation": "语义：“寄”指邮寄物品，客人不能被寄"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭表面，客人不能被擦到北京"}, {"text": "聚集", "is_correct": true, "explanation": "聚集：许多人从各地来到同一处，与句意相符"}, {"text": "驶", "is_correct": false, "explanation": "搭配：“驶”一般说车船行驶，不能说人驶到北京"}], "explanations": {"寄": "语义：“寄”指邮寄物品，客人不能被寄", "擦": "语义：“擦”指擦拭表面，客人不能被擦到北京", "聚集": "聚集：许多人从各地来到同一处，与句意相符", "驶": "搭配：“驶”一般说车船行驶，不能说人驶到北京"}, "sentence_index": 0, "correct_answer": "聚集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小就爱聚集邮票。", "explanation": "这里应该用〈收集〉。收集指有目的地搜集东西，聚集指许多人或物自然来到一处，不能用于主动搜集邮票"}, {"text": "两家工厂聚集以后，产量一下子高了很多。", "explanation": "这里应该用〈合并〉。合并指两个或几个合成一个；聚集只是人或物来到一处，不能说工厂聚集成一体"}, {"text": "他在这一行干了十年，聚集了很多经验。", "explanation": "这里应该用〈积累〉。积累指逐渐增多地存留，经验是慢慢积累起来的；聚集指人或物来到同一处，不说聚集经验"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94074, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "据实", "is_correct": false, "explanation": "据实（jù shí）与“聚集”第二个音节声母不同（sh 与 j），意思是依照实际情况"}, {"text": "聚集", "is_correct": true, "explanation": "聚集（jù jí）：许多人或物从各处来到一处，正是要听的词"}, {"text": "狙击", "is_correct": false, "explanation": "狙击（jū jī）与“聚集”两个音节声调都不同（jū 第一声、jī 第一声），意思是暗中伺机射击"}, {"text": "据悉", "is_correct": false, "explanation": "据悉（jù xī）与“聚集”第二个音节声母和声调不同（xī 与 jí），意思是根据得到的消息知道"}], "explanations": {"据实": "据实（jù shí）与“聚集”第二个音节声母不同（sh 与 j），意思是依照实际情况", "聚集": "聚集（jù jí）：许多人或物从各处来到一处，正是要听的词", "狙击": "狙击（jū jī）与“聚集”两个音节声调都不同（jū 第一声、jī 第一声），意思是暗中伺机射击", "据悉": "据悉（jù xī）与“聚集”第二个音节声母和声调不同（xī 与 jí），意思是根据得到的消息知道"}, "sentence_index": null, "correct_answer": "聚集"}, "level_3": {"options": [{"text": "扎", "is_correct": false, "explanation": "语义：“扎”指刺入，资金不能被扎到城市"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斧切断，与资金的流动不合"}, {"text": "聚集", "is_correct": true, "explanation": "聚集：许多资金从各地集中到这里，与句意相符"}, {"text": "抛", "is_correct": false, "explanation": "搭配：“抛”指扔掷物件，不能说资金被抛到城市"}], "explanations": {"扎": "语义：“扎”指刺入，资金不能被扎到城市", "砍": "语义：“砍”指用刀斧切断，与资金的流动不合", "聚集": "聚集：许多资金从各地集中到这里，与句意相符", "抛": "搭配：“抛”指扔掷物件，不能说资金被抛到城市"}, "sentence_index": 6, "correct_answer": "聚集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小就喜欢聚集贝壳，攒了一大箱。", "explanation": "这里应该用〈收集〉。收集指有目的地搜集东西，聚集指许多人或物自然来到一处，不能说主动聚集贝壳"}, {"text": "他把旧报纸聚集在墙角，准备下个月卖掉。", "explanation": "这里应该用〈堆〉。堆指把东西一层层放在一处，“聚集”不能用来说人把物品摆成一堆"}, {"text": "她在工作中聚集了很多经验，做事越来越熟练。", "explanation": "这里应该用〈积累〉。积累指逐渐增多地存留，经验要慢慢积累；聚集指人或物来到同一处，不说聚集经验"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各地的游客都聚集去景区门口了。", "corrected_sentence": "各地的游客都聚集到景区门口了。", "error_description": "补语错误：“聚集”后应接“到”表示到达某处，不能用“去”，应说“聚集到景区门口了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各地的人很快聚集下来。", "corrected_sentence": "各地的人很快聚集起来。", "error_description": "“聚集”的趋向补语应用“起来”，不能说“下来”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
