INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94077, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "起义是很多人一起站起来，反对不好的统治者。", "primary_collocate": null, "pronunciation": "qǐ yì", "ipa": "tɕʰi˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "农民们在冬天起义了。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民在去年发动了起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定在晚上起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们起义以后，城市乱了。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们起义了，国王很害怕。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年前，这里的农民起义过。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了自由，人民决定起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个地方又有人起义了。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不愿再忍受，就起义了。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，农民因为没饭吃才起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起义了", "label": "完成体"}, {"form": "起义过", "label": "经历体"}, {"form": "起义军", "label": "复合词"}], "register": "中性", "sense_fingerprint": "起义：众人联合起来反抗统治者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94077, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奇异", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，奇异意思是奇特、罕见。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义（qǐ yì）指众人起来反抗统治者。"}, {"text": "企业", "is_correct": false, "explanation": "yè 与 yì 韵母不同（ie 与 i），声调相同，企业意思是公司。"}, {"text": "起立", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），声调相同，起立意思是站起来。"}, {"text": "起疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，起疑意思是产生怀疑。"}], "explanations": {"奇异": "qí（第二声）与 qǐ（第三声）声调不同，奇异意思是奇特、罕见。", "起义": "正确：起义（qǐ yì）指众人起来反抗统治者。", "企业": "yè 与 yì 韵母不同（ie 与 i），声调相同，企业意思是公司。", "起立": "lì 与 yì 声母不同（l 与 y），声调相同，起立意思是站起来。", "起疑": "yí（第二声）与 yì（第四声）声调不同，起疑意思是产生怀疑。"}, "sentence_index": null, "correct_answer": "起义"}, "level_3": {"options": [{"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠只用于动物，不能指农民。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”的主语是学校或学生，不说“农民们开学”。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义指农民起来反抗统治者，符合句意。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指水等液体变成冰，人不能结冰。"}], "explanations": {"冬眠": "语义：冬眠只用于动物，不能指农民。", "开学": "搭配：“开学”的主语是学校或学生，不说“农民们开学”。", "起义": "正确：起义指农民起来反抗统治者，符合句意。", "结冰": "语义：“结冰”指水等液体变成冰，人不能结冰。"}, "sentence_index": 0, "correct_answer": "起义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的员工起义了，车间全都停了。", "explanation": "这里应该用〈罢工〉。罢工是劳动者停止工作以争取权益，不是反抗统治者；起义用于反抗统治的行动，不用于工厂停工。"}, {"text": "学生们在校门口起义，要求换一位校长。", "explanation": "这里应该用〈抗议〉。抗议是公开表示不满、提出要求，不是推翻统治者的群体反抗；校门口的诉求应说抗议。"}, {"text": "学生们因为食堂涨价，全体起义了。", "explanation": "这里应该用〈罢课〉。罢课是学生停课以表达诉求，不推翻统治者；因涨价而停课应说罢课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94077, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "歧义", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，歧义意思是一句话有多种理解。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义（qǐ yì）指众人起来反抗统治者。"}, {"text": "起夜", "is_correct": false, "explanation": "yè 与 yì 韵母不同，声调相同，起夜意思是夜里起床。"}, {"text": "起疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，起疑意思是产生怀疑。"}], "explanations": {"歧义": "qí（第二声）与 qǐ（第三声）声调不同，歧义意思是一句话有多种理解。", "起义": "正确：起义（qǐ yì）指众人起来反抗统治者。", "起夜": "yè 与 yì 韵母不同，声调相同，起夜意思是夜里起床。", "起疑": "yí（第二声）与 yì（第四声）声调不同，起疑意思是产生怀疑。"}, "sentence_index": null, "correct_answer": "起义"}, "level_3": {"options": [{"text": "结账", "is_correct": false, "explanation": "搭配：“结账”用于买卖或消费，与“为了自由”的决定不搭。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义指人民为争取自由而起来反抗，符合句意。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是个人身体状况，不是为了自由而做的决定。"}, {"text": "发财", "is_correct": false, "explanation": "语义：“发财”指个人致富，与“为了自由”的决定不相符。"}], "explanations": {"结账": "搭配：“结账”用于买卖或消费，与“为了自由”的决定不搭。", "起义": "正确：起义指人民为争取自由而起来反抗，符合句意。", "生病": "语义：“生病”是个人身体状况，不是为了自由而做的决定。", "发财": "语义：“发财”指个人致富，与“为了自由”的决定不相符。"}, "sentence_index": 6, "correct_answer": "起义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几个顾客在餐厅起义，把桌椅都砸坏了。", "explanation": "这里应该用〈闹事〉。闹事指无理取闹、扰乱秩序，不是有组织地反抗统治者。"}, {"text": "农民们去县衙起义，希望减免税收。", "explanation": "这里应该用〈请愿〉。请愿是向官府提出请求，不是武装反抗；去县衙提出减税要求应说请愿。"}, {"text": "市民们在街上起义，举着标语走过市政府。", "explanation": "这里应该用〈游行〉。游行是集体列队行进以表达诉求，不是反抗统治者的武装行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个地方的农民在去年发动了一位起义。", "corrected_sentence": "那个地方的农民在去年发动了一场起义。", "error_description": "量词错误：“位”用于指人，“起义”指一次事件，应用“场”或“次”，说“一位起义”不对，应说“一场起义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人民决定在半夜起义了，推翻了国王。", "corrected_sentence": "人民决定在半夜起义，推翻了国王。", "error_description": "体标错误：“决定”后面接的是尚未发生的行动，“起义”后不能加“了”，应说“决定在半夜起义”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
