INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94078, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为反抗压迫或统治而发动武装行动。", "primary_collocate": null, "pronunciation": "qǐ yì", "ipa": "tɕʰi˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "他们拿起武器起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年秋天，工人在城里起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里有人起义，站到了人民一边。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起义的人先占领了城门。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山里准备了很久，终于起义了。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们为了反对重税而起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军带着士兵起义，离开了国王。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们起义那天，下着大雪。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的村民听到消息后也起义了。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时代常常有人起义。", "target_word": "起义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起义了", "label": "完成体"}, {"form": "起义过", "label": "经历体"}, {"form": "起义军", "label": "复合词"}], "register": "中性", "sense_fingerprint": "起义：为反抗压迫或统治而发动武装行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歧义", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，歧义意思是一句话有多种理解。"}, {"text": "企业", "is_correct": false, "explanation": "yè 与 yì 韵母不同（ie 与 i），声调相同，企业意思是公司。"}, {"text": "起立", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），声调相同，起立意思是站起来。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义（qǐ yì）指为反抗压迫而发动武装行动。"}, {"text": "起夜", "is_correct": false, "explanation": "yè 与 yì 韵母不同，声调相同，起夜意思是夜里起床。"}], "explanations": {"歧义": "qí（第二声）与 qǐ（第三声）声调不同，歧义意思是一句话有多种理解。", "企业": "yè 与 yì 韵母不同（ie 与 i），声调相同，企业意思是公司。", "起立": "lì 与 yì 声母不同（l 与 y），声调相同，起立意思是站起来。", "起义": "正确：起义（qǐ yì）指为反抗压迫而发动武装行动。", "起夜": "yè 与 yì 韵母不同，声调相同，起夜意思是夜里起床。"}, "sentence_index": null, "correct_answer": "起义"}, "level_3": {"options": [{"text": "写作", "is_correct": false, "explanation": "搭配：“拿起武器”后接“写作”不搭，应说拿起笔写作。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义指拿起武器发动武装反抗，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：拿起武器与睡觉无关，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与拿起武器的行为不相干。"}], "explanations": {"写作": "搭配：“拿起武器”后接“写作”不搭，应说拿起笔写作。", "起义": "正确：起义指拿起武器发动武装反抗，符合句意。", "睡觉": "语义：拿起武器与睡觉无关，句意不通。", "结婚": "语义：“结婚”与拿起武器的行为不相干。"}, "sentence_index": 0, "correct_answer": "起义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在办公室门口起义，要求涨工资。", "explanation": "这里应该用〈抗议〉。抗议是公开表示不满、提出要求；起义指武装反抗统治，在办公室门口要求涨工资不能用起义。"}, {"text": "市民们为了环保问题起义，举着标语。", "explanation": "这里应该用〈游行〉。游行是集体列队表达诉求，不是武装反抗统治者。"}, {"text": "学生们因为食堂涨价而起义。", "explanation": "这里应该用〈罢课〉。罢课是学生停课以表达诉求，不推翻统治者；因涨价而停课应说罢课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94078, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奇异", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，奇异意思是奇特、罕见。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义（qǐ yì）指为反抗压迫而发动武装行动。"}, {"text": "起疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，起疑意思是产生怀疑。"}, {"text": "企业", "is_correct": false, "explanation": "yè 与 yì 韵母不同（ie 与 i），声调相同，企业意思是公司。"}], "explanations": {"奇异": "qí（第二声）与 qǐ（第三声）声调不同，奇异意思是奇特、罕见。", "起义": "正确：起义（qǐ yì）指为反抗压迫而发动武装行动。", "起疑": "yí（第二声）与 yì（第四声）声调不同，起疑意思是产生怀疑。", "企业": "yè 与 yì 韵母不同（ie 与 i），声调相同，企业意思是公司。"}, "sentence_index": null, "correct_answer": "起义"}, "level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：将军带兵与“考试”无关，句意不通。"}, {"text": "上学", "is_correct": false, "explanation": "搭配：“上学”指学生去学校，不说将军带着士兵上学。"}, {"text": "下课", "is_correct": false, "explanation": "搭配：“下课”用于课堂，不能用于将军与士兵。"}, {"text": "起义", "is_correct": true, "explanation": "正确：起义指士兵跟随将军反抗国王，符合句意。"}], "explanations": {"考试": "语义：将军带兵与“考试”无关，句意不通。", "上学": "搭配：“上学”指学生去学校，不说将军带着士兵上学。", "下课": "搭配：“下课”用于课堂，不能用于将军与士兵。", "起义": "正确：起义指士兵跟随将军反抗国王，符合句意。"}, "sentence_index": 6, "correct_answer": "起义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们通过法律起义，要求改善待遇。", "explanation": "这里应该用〈维权〉。维权是依法维护自身权益，不是武装反抗统治者；通过法律途径应说维权。"}, {"text": "村民们到县里起义，要求修路。", "explanation": "这里应该用〈上访〉。上访是到上级机关反映问题，不是武装反抗；修路的请求应说上访。"}, {"text": "司机们起义了，公交停运了。", "explanation": "这里应该用〈罢工〉。罢工是劳动者停止工作，公交停运是罢工的结果，不是反抗统治者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, v