INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们往夜里起义，占领了城门。", "corrected_sentence": "他们在夜里起义，占领了城门。", "error_description": "介词错误：“往”表示动作的方向，不用于指时间；表示时间点应用“在”，应说“在夜里起义”，不说“往夜里起义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位起义以后，农民们占领了粮仓。", "corrected_sentence": "那次起义以后，农民们占领了粮仓。", "error_description": "量词错误：“位”用于指人，“起义”指一次事件，指代某次起义应用“次”或“场”，说“那位起义”不对，应说“那次起义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
