INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "辐射是从一个东西向四面八方散出去的光、热或看不见的力量。", "primary_collocate": null, "pronunciation": "fú shè", "ipa": "fu˧˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "太阳的辐射让地面变热。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火炉的辐射让整个房间都暖了。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，太阳辐射很强。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的辐射看不见，也摸不到。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院拍片时，医生要躲开辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳辐射给地球带来光和热。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在火边，能感到火的辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇要少接触辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光的辐射晒黑了他的脸。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷挡住了太阳的辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核辐射", "label": "复合词"}, {"form": "电磁辐射", "label": "复合词"}, {"form": "輻射", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从物体向四周散出的光、热或看不见的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确答案：辐射（fú shè），指能量从物体向四周散出的光、热或看不见的力量。"}, {"text": "服饰", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服饰（衣服和装饰）。"}, {"text": "敷设", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是敷设（铺设管线或电缆）。"}, {"text": "附设", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是附设（附属设立）。"}], "explanations": {"辐射": "正确答案：辐射（fú shè），指能量从物体向四周散出的光、热或看不见的力量。", "服饰": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服饰（衣服和装饰）。", "敷设": "fū（第一声）与 fú（第二声）声调不同，意思是敷设（铺设管线或电缆）。", "附设": "fù（第四声）与 fú（第二声）声调不同，意思是附设（附属设立）。"}, "sentence_index": null, "correct_answer": "辐射"}, "level_3": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确：“太阳的辐射”指太阳向外散出的光和热，与“让地面变热”相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不会让地面变热，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有加热的作用，“太阳的颜色让地面变热”句意荒谬。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”与“让地面变热”不搭配，香味不会产生热。"}], "explanations": {"辐射": "正确：“太阳的辐射”指太阳向外散出的光和热，与“让地面变热”相符。", "影子": "语义：影子不会让地面变热，句意不通。", "颜色": "语义：颜色没有加热的作用，“太阳的颜色让地面变热”句意荒谬。", "香味": "搭配：“香味”与“让地面变热”不搭配，香味不会产生热。"}, "sentence_index": 0, "correct_answer": "辐射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面镜子能辐射阳光。", "explanation": "这里应该用〈反射〉。反射是光线遇到物体后返回；辐射是物体自身向外发出能量，镜子不会自己发光。"}, {"text": "电视台辐射了一部纪录片。", "explanation": "这里应该用〈播放〉。播放是把节目放给观众看；辐射是能量向四周散出，不能用来指播出节目。"}, {"text": "火箭辐射了卫星。", "explanation": "这里应该用〈发射〉。发射是把物体射出去，如火箭送卫星；辐射是能量向四周散出，不能用来送出物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确答案：辐射（fú shè），指能量从物体向四周散出的光、热或看不见的力量。"}, {"text": "服式", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服式（服装的款式）。"}, {"text": "俯射", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是俯射（向下射击）。"}, {"text": "服事", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服事（侍奉）。"}], "explanations": {"辐射": "正确答案：辐射（fú shè），指能量从物体向四周散出的光、热或看不见的力量。", "服式": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服式（服装的款式）。", "俯射": "fǔ（第三声）与 fú（第二声）声调不同，意思是俯射（向下射击）。", "服事": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服事（侍奉）。"}, "sentence_index": null, "correct_answer": "辐射"}, "level_3": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确：“火的辐射”指火向外散出的热，站在火边能感到，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“感到”通常用于触觉、温度，不用于“声音”。"}, {"text": "重量", "is_correct": false, "explanation": "语义：火没有可以被人感到的“重量”，句意荒谬。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是生物的温度，火没有体温，句意荒谬。"}], "explanations": {"辐射": "正确：“火的辐射”指火向外散出的热，站在火边能感到，符合句意。", "声音": "搭配：“感到”通常用于触觉、温度，不用于“声音”。", "重量": "语义：火没有可以被人感到的“重量”，句意荒谬。", "体温": "语义：“体温”是生物的温度，火没有体温，句意荒谬。"}, "sentence_index": 6, "correct_answer": "辐射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条管道辐射了大量天然气。", "explanation": "这里应该用〈输送〉。输送是沿管道把气体、液体送到别处；辐射是能量向四周散出，不能指管道的定向输送。"}, {"text": "花朵辐射出阵阵香味。", "explanation": "这里应该用〈散发〉。散发指气味、热量向四周放出；香味是气体分子，不是光热能量，不能说“辐射香味”。"}, {"text": "消防车辐射出一股水柱。", "explanation": "这里应该用〈喷射〉。喷射指液体或气体从口子里猛烈射出；水柱是液体，辐射只指能量，不能用于水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火炉旁边有一条辐射，让人很暖和。", "corrected_sentence": "火炉旁边有一种辐射，让人很暖和。", "error_description": "量词错误：“条”用于细长的东西（如绳子、河），“辐射”是向四周散出的能量，应改用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器只有一座辐射，可以放心用。", "corrected_sentence": "这台机器只有一种辐射，可以放心用。", "error_description": "量词错误：“辐射”不能用“座”（座用于山、桥等大型固定物），应改用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
