INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能量以波或粒子的形式从物体向四周发射出去的现象。", "primary_collocate": null, "pronunciation": "fú shè", "ipa": "fu˧˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "核电站要防止辐射泄漏。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辐射是能量向四周发射出去的现象。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑工作时会产生辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空里的辐射对宇航员有影响。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究辐射的变化。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紫外线是一种辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铅板可以挡住部分辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些仪器可以测量辐射的大小。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辐射不一定有害，要看多少。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体变热后会向外放出辐射。", "target_word": "辐射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核辐射", "label": "复合词"}, {"form": "电磁辐射", "label": "复合词"}, {"form": "輻射", "label": "繁体"}], "register": "书面", "sense_fingerprint": "能量以波或粒子形式向四周发射的物理现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确答案：辐射（fú shè），指能量以波或粒子的形式从物体向四周发射出去的现象。"}, {"text": "服式", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服式（服装的款式）。"}, {"text": "敷设", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是敷设（铺设管线或电缆）。"}, {"text": "俯射", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是俯射（向下射击）。"}], "explanations": {"辐射": "正确答案：辐射（fú shè），指能量以波或粒子的形式从物体向四周发射出去的现象。", "服式": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服式（服装的款式）。", "敷设": "fū（第一声）与 fú（第二声）声调不同，意思是敷设（铺设管线或电缆）。", "俯射": "fǔ（第三声）与 fú（第二声）声调不同，意思是俯射（向下射击）。"}, "sentence_index": null, "correct_answer": "辐射"}, "level_3": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确：“防止辐射泄漏”指防止能量向外扩散，符合句意。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声不会像气体或液体那样泄漏，句意荒谬。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”一般说“升高”“降低”，不说“泄漏”，二者不搭配。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是核电站需要防止泄漏的对象，句意荒谬。"}], "explanations": {"辐射": "正确：“防止辐射泄漏”指防止能量向外扩散，符合句意。", "笑声": "语义：笑声不会像气体或液体那样泄漏，句意荒谬。", "温度": "搭配：“温度”一般说“升高”“降低”，不说“泄漏”，二者不搭配。", "玩具": "语义：玩具不是核电站需要防止泄漏的对象，句意荒谬。"}, "sentence_index": 0, "correct_answer": "辐射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水面能辐射月光。", "explanation": "这里应该用〈反射〉。水面只是把月光返回，并不自己发出能量；辐射是物体自身向外发出能量。"}, {"text": "工厂辐射了大量废水。", "explanation": "这里应该用〈排放〉。排放是把废水、废气排出去；辐射是能量以波或粒子向外发射，不能指废水。"}, {"text": "出版社辐射了一批书。", "explanation": "这里应该用〈出版〉。出版是把作品印刷发行；辐射是能量向四周发射，不能指出版书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确答案：辐射（fú shè），指能量以波或粒子的形式从物体向四周发射出去的现象。"}, {"text": "服饰", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服饰（衣服和装饰）。"}, {"text": "附设", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是附设（附属设立）。"}, {"text": "服事", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服事（侍奉）。"}], "explanations": {"辐射": "正确答案：辐射（fú shè），指能量以波或粒子的形式从物体向四周发射出去的现象。", "服饰": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服饰（衣服和装饰）。", "附设": "fù（第四声）与 fú（第二声）声调不同，意思是附设（附属设立）。", "服事": "shì 与 shè 韵母不同（i 与 e），声调相同，意思是服事（侍奉）。"}, "sentence_index": null, "correct_answer": "辐射"}, "level_3": {"options": [{"text": "辐射", "is_correct": true, "explanation": "正确：“挡住部分辐射”指铅板阻挡一部分向外发射的能量，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能被铅板挡住，句意荒谬。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：欢乐不是铅板能阻挡的东西，句意荒谬。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“挡住”一般接具体物体，“情绪”与“挡住部分”不搭配。"}], "explanations": {"辐射": "正确：“挡住部分辐射”指铅板阻挡一部分向外发射的能量，符合句意。", "时间": "语义：“时间”不能被铅板挡住，句意荒谬。", "欢乐": "语义：欢乐不是铅板能阻挡的东西，句意荒谬。", "情绪": "搭配：“挡住”一般接具体物体，“情绪”与“挡住部分”不搭配。"}, "sentence_index": 6, "correct_answer": "辐射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火山辐射出大量岩浆。", "explanation": "这里应该用〈喷射〉。喷射指物质从口子里猛烈射出；岩浆是物质，辐射只指能量向四周散出，不能说“辐射岩浆”。"}, {"text": "中国成功辐射了一颗卫星。", "explanation": "这里应该用〈发射〉。发射是把卫星送出去；辐射是能量向四周散出，不能用来送出卫星。"}, {"text": "这位作家辐射了一部小说。", "explanation": "这里应该用〈创作〉。创作是写出作品；辐射是能量向四周发射，不能指写作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种灯工作时会发出一座辐射。", "corrected_sentence": "这种灯工作时会发出辐射。", "error_description": "量词错误：“座”用于山、桥等大型固定物，不能修饰“辐射”，应去掉“一座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太阳每天向地球放出一座辐射。", "corrected_sentence": "太阳每天向地球放出辐射。", "error_description": "量词错误：“座”用于山、桥等大型固定物，不能修饰“辐射”，应去掉“一座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
