INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通道是让人或车从这里走到那里的路。", "primary_collocate": null, "pronunciation": "tōng dào", "ipa": "tʰʊŋ˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "火车站的通道里人很多。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把行李放在通道上。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条通道可以通到地铁站。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的通道很宽，车也能过。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条通道里有一家小店。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "着火时，大家从那条通道跑了出去。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的通道太窄，我们走得很慢。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在通道中间，别人过不去。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个通道只能走人，不能开车。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场的通道上有很多人在买东西。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "让人或车通行的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43035244-64f2-4d65-bc07-110cd48c7371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通道", "is_correct": true, "explanation": "正确。“火车站的通道里人很多”中，通道指供人通行的路，与句子语境相符。"}, {"text": "鱼塘", "is_correct": false, "explanation": "语义：火车站里不会有鱼塘，“火车站的鱼塘里人很多”说不通。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌不是供人通行的地方，“火车站的书桌里人很多”说不通。"}, {"text": "菜园", "is_correct": false, "explanation": "语义：车站不种菜，“火车站的菜园里人很多”不合常理。"}], "explanations": {"通道": "正确。“火车站的通道里人很多”中，通道指供人通行的路，与句子语境相符。", "鱼塘": "语义：火车站里不会有鱼塘，“火车站的鱼塘里人很多”说不通。", "书桌": "语义：书桌不是供人通行的地方，“火车站的书桌里人很多”说不通。", "菜园": "语义：车站不种菜，“火车站的菜园里人很多”不合常理。"}, "sentence_index": 0, "correct_answer": "通道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把通道放进了书包里。", "explanation": "这里应该用〈书〉。通道是供人、车通行的路，不能放进书包；放进书包的是书。"}, {"text": "医院里新建了一只通道，车也能过。", "explanation": "这里应该用〈条〉。通道用量词“条”，“只”多用于动物等，不说“一只通道”。"}, {"text": "他在通道里炒菜。", "explanation": "这里应该用〈厨房〉。通道指供人、车通行的路，不是做饭的地方；炒菜要在厨房里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通道", "is_correct": true, "explanation": "正确。“电影院的通道太窄”中，通道指观众走动的过道，与句子语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：电影院不设厨房，“电影院的厨房太窄，我们走得很慢”与语境不符。"}, {"text": "菜园", "is_correct": false, "explanation": "语义：电影院里没有菜园，“电影院的菜园太窄，我们走得很慢”说不通。"}, {"text": "河道", "is_correct": false, "explanation": "语义：电影院里没有河道，“电影院的河道太窄”说不通。"}], "explanations": {"通道": "正确。“电影院的通道太窄”中，通道指观众走动的过道，与句子语境相符。", "厨房": "语义：电影院不设厨房，“电影院的厨房太窄，我们走得很慢”与语境不符。", "菜园": "语义：电影院里没有菜园，“电影院的菜园太窄，我们走得很慢”说不通。", "河道": "语义：电影院里没有河道，“电影院的河道太窄”说不通。"}, "sentence_index": 6, "correct_answer": "通道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都梳通道。", "explanation": "此处应为〈头发〉。梳的是头发，通道指供人、车通行的路，不能用来梳。"}, {"text": "这块通道很宽，车也能过。", "explanation": "这里应该用〈条〉。通道用量词“条”，“块”多用于块状或片状的东西，不说“一块通道”。"}, {"text": "我家养了一条通道，它很可爱。", "explanation": "这里应该用〈狗〉。通道是供人、车通行的路，不能养；养的是狗等动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那把通道很长，一直通到后门。", "corrected_sentence": "那条通道很长，一直通到后门。", "error_description": "“通道”应用量词“条”，不用“把”（“把”用于有柄的东西）。错误形式：那把通道；正确形式：那条通道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们只能从这条很窄通道过去。", "corrected_sentence": "我们只能从这条很窄的通道过去。", "error_description": "“很窄”修饰“通道”时要加结构助词“的”，应说“很窄的通道”，此处漏掉了“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
