INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房屋、车厢或剧场内供人行走的狭窄通路。", "primary_collocate": null, "pronunciation": "guò dào", "ipa": "kuɔ˥˩ tɑu˥˩", "syllable_count": 2, "sentences": [{"text": "电影院的过道里有小灯。", "target_word": "过道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车车厢的过道里有人推着小车。", "target_word": "过道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧场里的过道很窄，观众走得很慢。", "target_word": "过道", "complexity_tier": "T3", "furigana": "jù chǎng lǐ de guò dào hěn zhǎi, guān zhòng zǒu de hěn màn。", "sentence_source": "generated"}, {"text": "请让一下，我要从过道出去。", "target_word": "过道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地铁车厢的过道上都是人。", "target_word": "过道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼里的过道是公用的，不能放东西。", "target_word": "过道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在过道那边的位子上。", "target_word": "过道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室的过道要留出来，方便大家走。", "target_word": "过道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出开始了，迟到的人只能站在过道。", "target_word": "过道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员推着小车慢慢走进过道。", "target_word": "过道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "過道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "房屋车厢剧场内供人行走的狭窄通路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd71f46b-59ce-4fa8-abe9-85caaf31d755') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过道", "is_correct": true, "explanation": "过道是剧场里供人走的通路，与“电影院的”“里有小灯”相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：电影院里不会有海洋，与“电影院的”矛盾。"}, {"text": "草地", "is_correct": false, "explanation": "语义：电影院里一般没有草地，句子所说的场所不合。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“座位”后一般说“座位上”，不说“座位里有小灯”。"}], "explanations": {"过道": "过道是剧场里供人走的通路，与“电影院的”“里有小灯”相符。", "海洋": "语义：电影院里不会有海洋，与“电影院的”矛盾。", "草地": "语义：电影院里一般没有草地，句子所说的场所不合。", "座位": "搭配：“座位”后一般说“座位上”，不说“座位里有小灯”。"}, "sentence_index": 0, "correct_answer": "过道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧场里有一只过道很窄。", "explanation": "这里应该用〈条〉。过道细长，量词要用“条”，不用“只”。"}, {"text": "我们沿着过道走到了学校。", "explanation": "这里应该用〈马路〉。过道只指房屋、车厢或剧场里的通路，不指户外道路。"}, {"text": "他推开过道，走了进去。", "explanation": "这里应该用〈门〉。过道是通路，不能被“推开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过道", "is_correct": true, "explanation": "过道指剧场或车厢里供人走的通路，“过道那边的位子”指通路一侧的座位，相符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：位子不可能在雨水那边，句子语义不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“那边的位子”要指可以坐的具体处所，天空不能这样搭配。"}, {"text": "想法", "is_correct": false, "explanation": "语义：想法是抽象的念头，不是处所，“想法那边的位子”说不通。"}], "explanations": {"过道": "过道指剧场或车厢里供人走的通路，“过道那边的位子”指通路一侧的座位，相符。", "雨水": "语义：位子不可能在雨水那边，句子语义不通。", "天空": "搭配：“那边的位子”要指可以坐的具体处所，天空不能这样搭配。", "想法": "语义：想法是抽象的念头，不是处所，“想法那边的位子”说不通。"}, "sentence_index": 6, "correct_answer": "过道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他乘过道上了二楼。", "explanation": "这里应该用〈电梯〉。过道是平面通路，不能“乘”着上楼，乘上楼的应是电梯。"}, {"text": "货船在过道里慢慢地驶过。", "explanation": "这里应该用〈河〉。过道是房屋或车厢里的通路，货船不能在其中行驶。"}, {"text": "他把手机放进了过道，找了很久。", "explanation": "这里应该用〈口袋〉。过道是通路，不能装东西；“放进”要用容器，如口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条长长过道通向车厢。", "corrected_sentence": "一条长长的过道通向车厢。", "error_description": "“长长”修饰“过道”时要加“的”，应说“一条长长的过道”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只狭窄的过道通向厨房。", "corrected_sentence": "一条狭窄的过道通向厨房。", "error_description": "量词用错：“过道”是细长的通路，应该用量词“条”，说“一条狭窄的过道”；用“只”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
