INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94087, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "道地是说东西很正宗，跟老地方做的一样。", "primary_collocate": null, "pronunciation": "dào dì", "ipa": "taʊ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的牛肉面很道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做的四川菜非常道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的咖啡味道很道地，像在意大利一样。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做的饺子最道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想吃一碗道地的北京炸酱面。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的日本拉面很道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她煮的茶很道地，和老家一样。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带我去吃了道地的广东早茶。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个面包做得不太道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老街上，你能买到道地的小吃。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "饮食等东西很正宗，和原产地做的一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94087, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确答案。道地读 dào dì（第四声），意思是正宗、纯正。"}, {"text": "倒地", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，倒地意思是跌倒在地上。"}, {"text": "到底", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，到底意思是究竟、终究。"}, {"text": "大地", "is_correct": false, "explanation": "大地读 dà dì，韵母 a 与 dào 的 ao 不同，意思是地面、土地。"}, {"text": "大帝", "is_correct": false, "explanation": "大帝读 dà dì，韵母与 dào 不同，意思是对帝王的尊称，如彼得大帝。"}], "explanations": {"道地": "正确答案。道地读 dào dì（第四声），意思是正宗、纯正。", "倒地": "dǎo（第三声）与 dào（第四声）声调不同，倒地意思是跌倒在地上。", "到底": "dǐ（第三声）与 dì（第四声）声调不同，到底意思是究竟、终究。", "大地": "大地读 dà dì，韵母 a 与 dào 的 ao 不同，意思是地面、土地。", "大帝": "大帝读 dà dì，韵母与 dào 不同，意思是对帝王的尊称，如彼得大帝。"}, "sentence_index": null, "correct_answer": "道地"}, "level_3": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确。道地形容饮食正宗、与原产地做法一致，符合“很”后面的评价。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，牛肉面不能用“聪明”来形容。"}, {"text": "相似", "is_correct": false, "explanation": "语义：“相似”需要说明与何者相似，此句没有比较对象，且与“正宗”之意不符。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”形容人的情绪，不能用来形容食物。"}], "explanations": {"道地": "正确。道地形容饮食正宗、与原产地做法一致，符合“很”后面的评价。", "聪明": "语义：“聪明”形容人的智力，牛肉面不能用“聪明”来形容。", "相似": "语义：“相似”需要说明与何者相似，此句没有比较对象，且与“正宗”之意不符。", "害羞": "语义：“害羞”形容人的情绪，不能用来形容食物。"}, "sentence_index": 0, "correct_answer": "道地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的空气很道地。", "explanation": "这里应该用〈新鲜〉。道地形容饮食等东西正宗、有地方特色，不用来说空气是否新鲜。"}, {"text": "这间教室很道地。", "explanation": "这里应该用〈干净〉。道地用于饮食、手艺等带地方传统的东西，不用来形容教室是否干净。"}, {"text": "这道数学题很道地。", "explanation": "这里应该用〈简单〉。道地不用来评价题目的难易，题目的难易要说“简单”或“难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确。“道地”与后句“和老家一样”相呼应，说明茶的味道正宗。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人说话风趣，不能用来形容茶。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”与后句“和老家一样”矛盾，两者不能同时成立。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能用来形容茶。"}], "explanations": {"道地": "正确。“道地”与后句“和老家一样”相呼应，说明茶的味道正宗。", "幽默": "语义：“幽默”形容人说话风趣，不能用来形容茶。", "陌生": "语义：“陌生”与后句“和老家一样”矛盾，两者不能同时成立。", "瘦": "体貌：“瘦”形容人或动物的身材，不能用来形容茶。"}, "sentence_index": 6, "correct_answer": "道地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很道地。", "explanation": "这里应该用〈宽敞〉。道地用于饮食、语言等正宗、有地方特色的东西，不用来形容房间大小。"}, {"text": "他跑步很道地。", "explanation": "这里应该用〈快〉。道地不用来形容速度，跑得快慢要说“快”或“慢”。"}, {"text": "这个解释很道地。", "explanation": "这里应该用〈清楚〉。道地不用来评价解释是否清楚，说明清楚与否要用“清楚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的豆浆做很道地。", "corrected_sentence": "她的豆浆做得很道地。", "error_description": "“做很道地”漏了“得”，应为“做得很道地”：动词后带形容词作补语时，中间须用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小店的炸酱面做很道地。", "corrected_sentence": "这家小店的炸酱面做得很道地。", "error_description": "“做很道地”漏了“得”，应为“做得很道地”：动词后面用形容词说明结果或程度时，中间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
