INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真正的、纯正的，具有地方特色的。", "primary_collocate": null, "pronunciation": "dào dì", "ipa": "taʊ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他说一口道地的北京话。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的英语说得很道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一家道地的老北京饭馆。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个道地的北京人。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服用的是道地的苗族绣花。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱了一首道地的陕北民歌。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们说道地的中文。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜都是道地的湖南味道。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看一场道地的京剧。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的广东话说得很道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "真正的、纯正的，带有地方特色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, genera