INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确。“道地”修饰中文，表示纯正、地道的中文。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容天气或温度低，不能用来形容语言。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势或坡度，不能用来形容语言。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，不能用来形容中文。"}], "explanations": {"道地": "正确。“道地”修饰中文，表示纯正、地道的中文。", "寒冷": "语义：“寒冷”形容天气或温度低，不能用来形容语言。", "陡峭": "语义：“陡峭”形容地势或坡度，不能用来形容语言。", "高大": "体貌：“高大”形容人或物的体型，不能用来形容中文。"}, "sentence_index": 6, "correct_answer": "道地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个变化很道地。", "explanation": "这里应该用〈明显〉。道地用于正宗、有地方特色的事物，不用来形容变化是否明显。"}, {"text": "这个数字很道地。", "explanation": "这里应该用〈大〉。道地不用来形容数字的大小，数字的大小要说“大”或“小”。"}, {"text": "这份合同很道地。", "explanation": "这里应该用〈严谨〉。道地说的是正宗、有地方特色，不用来评价合同是否严谨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的日语说很道地。", "corrected_sentence": "她的日语说得很道地。", "error_description": "“说很道地”漏了“得”，应为“说得很道地”：动词后带形容词作补语时，须用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的上海话讲很道地。", "corrected_sentence": "他的上海话讲得很道地。", "error_description": "“讲很道地”漏了“得”，应为“讲得很道地”：动词后面用形容词说明程度时，中间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
