INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设立并开始办理，如店铺、课程、账户等。", "primary_collocate": null, "pronunciation": "kāi shè", "ipa": "kʰaɪ˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我去银行开设了一个新账户。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上开设了自己的店铺。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学为新生开设了很多选修课程。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开设账户需要带身份证。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备在上海开设分店。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生开设了一家小诊所。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开设了一个网上账户，用来存钱。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院下学期将开设三门新课程。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开设了一家小饭店，生意很好。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为我开设了一个储蓄账户。", "target_word": "开设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开设了", "label": "体标（了）"}, {"form": "开设过", "label": "体标（过）"}, {"form": "開設", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "开设：设立并开始办理店铺、课程、账户等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd71f46b-59ce-4fa8-abe9-85caaf31d755') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开设", "is_correct": true, "explanation": "正确：开设指设立账户，与“一个新账户”搭配。"}, {"text": "存", "is_correct": false, "explanation": "搭配：存的对象通常是钱款，不能说存一个新账户。"}, {"text": "挖", "is_correct": false, "explanation": "语义：挖是挖掘，与设立账户的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是歌唱，与办理账户无关。"}], "explanations": {"开设": "正确：开设指设立账户，与“一个新账户”搭配。", "存": "搭配：存的对象通常是钱款，不能说存一个新账户。", "挖": "语义：挖是挖掘，与设立账户的意思不符。", "唱": "语义：唱是歌唱，与办理账户无关。"}, "sentence_index": 0, "correct_answer": "开设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司开设了合作关系。", "explanation": "这里应该用〈建立〉。开设用于账户、店铺等具体项目，合作关系要用建立。"}, {"text": "学校开设了一场演讲比赛。", "explanation": "这里应该用〈举办〉。开设用于店铺、班、课程，比赛等活动要用举办。"}, {"text": "工人开设了一座大桥。", "explanation": "这里应该用〈建造〉。开设指办起店铺、课程、账户等，大型建筑要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开设", "is_correct": true, "explanation": "正确：开设指设立账户，与“用来存钱”的语境相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，与“用来存钱”的目的相矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃的对象是食物，“吃了一个网上账户”不成立。"}, {"text": "剪", "is_correct": false, "explanation": "语义：剪是剪断，不表示设立账户。"}], "explanations": {"开设": "正确：开设指设立账户，与“用来存钱”的语境相符。", "扔": "语义：扔是丢弃，与“用来存钱”的目的相矛盾。", "吃": "搭配：吃的对象是食物，“吃了一个网上账户”不成立。", "剪": "语义：剪是剪断，不表示设立账户。"}, "sentence_index": 6, "correct_answer": "开设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府为优秀员工开设了奖状。", "explanation": "这里应该用〈颁发〉。开设用于账户、店铺等，奖状要用颁发。"}, {"text": "他开设了全部责任。", "explanation": "这里应该用〈承担〉。开设指设立机构或项目，责任要用承担。"}, {"text": "政府开设了新的通知。", "explanation": "这里应该用〈发布〉。开设不用于通知，通知要用发布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "银行正在开设了新账户。", "corrected_sentence": "银行正在开设新账户。", "error_description": "错误形式：「正在开设了」。正确形式：「正在开设」。「正在」表示动作进行中，句中不能再用「了」表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家银行很开设网上账户。", "corrected_sentence": "这家银行开设网上账户。", "error_description": "错误形式：「很开设」。正确形式：「开设」。「很」是程度副词，不能修饰「开设」这类动作动词，应去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
