INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "点号是写字时用来让句子停一下的小符号，比如逗号。", "primary_collocate": null, "pronunciation": "diǎn hào", "ipa": "tjɛn²¹⁴ xɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个句子少了一个点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写字时别忘了点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逗号是一个小点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在句子后面加了点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读到点号，我就停一下。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一行没有点号，很难读。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学会了用点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里该用哪个点号？", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你写的点号太大了。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点号让句子读起来更清楚。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词，写字时让句子停顿的小符号，如逗号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点号", "is_correct": true, "explanation": "正确：点号指逗号、句号等表示停顿的小符号，句子少了它。"}, {"text": "段落", "is_correct": false, "explanation": "语义：段落是篇章的结构单位，句子里少的是标点，“少了一个段落”与句中情况不合。"}, {"text": "标题", "is_correct": false, "explanation": "语义：句子本身没有标题，句中缺的不是标题。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：说“句子少了一个”时不搭配“口号”，口号是喊出来的，不是句中成分。"}], "explanations": {"点号": "正确：点号指逗号、句号等表示停顿的小符号，句子少了它。", "段落": "语义：段落是篇章的结构单位，句子里少的是标点，“少了一个段落”与句中情况不合。", "标题": "语义：句子本身没有标题，句中缺的不是标题。", "口号": "搭配：说“句子少了一个”时不搭配“口号”，口号是喊出来的，不是句中成分。"}, "sentence_index": 0, "correct_answer": "点号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "括号是一种点号。", "explanation": "这里应该用〈标号〉。括号属于标号，点号指逗号、句号等表示停顿的标点。"}, {"text": "书名号是一种点号，用来标示书名。", "explanation": "这里应该用〈标号〉。书名号属于标号，不属于点号；点号指写字时让句子停顿的小符号，如逗号。"}, {"text": "引号是一种点号，用来标示引用的话。", "explanation": "这里应该用〈标号〉。引号属于标号，不属于点号；点号指写字时让句子停顿的小符号，如逗号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点号", "is_correct": true, "explanation": "正确：点号是写字时用的小符号，孩子学会的正是这个。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳不是可以拿来用的东西，“学会了用心跳”不成立。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔表示高度，不能被“用”，句中不合。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语，指人，不能被“用”，与句意不合。"}], "explanations": {"点号": "正确：点号是写字时用的小符号，孩子学会的正是这个。", "心跳": "语义：心跳不是可以拿来用的东西，“学会了用心跳”不成立。", "海拔": "语义：海拔表示高度，不能被“用”，句中不合。", "哥们儿": "语域：“哥们儿”是口语，指人，不能被“用”，与句意不合。"}, "sentence_index": 6, "correct_answer": "点号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "破折号是一种点号，用来表示解释或转折。", "explanation": "这里应该用〈标号〉。破折号属于标号，不属于点号；点号指写字时让句子停顿的小符号，如逗号。"}, {"text": "间隔号是一种点号，用来分隔外国人名的音节。", "explanation": "这里应该用〈标号〉。间隔号属于标号，不属于点号；点号指写字时让句子停顿的小符号，如逗号。"}, {"text": "连接号是一种点号，用来连接相关的词语。", "explanation": "这里应该用〈标号〉。连接号属于标号，不属于点号；点号指写字时让句子停顿的小符号，如逗号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
