INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94093, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一度是说过去有过一次，现在不是这样了。", "primary_collocate": null, "pronunciation": "yí dù", "ipa": "i˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这家店一度很有名，现在没人去了。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一度想放弃学中文，后来还是坚持了。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市一度很安静，现在到处都是车。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一度是最好的朋友，现在很少联系。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的病一度很重，现在已经好多了。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河一度干了，今年又有水了。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王一度住在北京，后来搬到了上海。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一度很胖，现在每天跑步，瘦了很多。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个歌手一度非常红，现在没人记得他。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司一度很困难，现在生意越来越好。", "target_word": "一度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词；过去有过一次，现在已不是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3b207d-7c24-48b9-bf1d-e4e2b943cf6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94093, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一度", "is_correct": true, "explanation": "一度（yí dù）：表示过去曾有过一次或一段时间，现在已不是这样。"}, {"text": "遗毒", "is_correct": false, "explanation": "遗毒（yí dú）：dú 为第二声，与 dù（第四声）声调不同，意思是残留的毒害。"}, {"text": "一顿", "is_correct": false, "explanation": "一顿（yí dùn）：dùn 比 dù 多一个韵尾 n，意思是一餐或一次责骂。"}, {"text": "一路", "is_correct": false, "explanation": "一路（yí lù）：lù 与 dù 声母不同（l 对 d），意思是沿途、一直。"}, {"text": "一怒", "is_correct": false, "explanation": "一怒（yí nù）：nù 与 dù 声母不同（n 对 d），意思是突然发怒。"}], "explanations": {"一度": "一度（yí dù）：表示过去曾有过一次或一段时间，现在已不是这样。", "遗毒": "遗毒（yí dú）：dú 为第二声，与 dù（第四声）声调不同，意思是残留的毒害。", "一顿": "一顿（yí dùn）：dùn 比 dù 多一个韵尾 n，意思是一餐或一次责骂。", "一路": "一路（yí lù）：lù 与 dù 声母不同（l 对 d），意思是沿途、一直。", "一怒": "一怒（yí nù）：nù 与 dù 声母不同（n 对 d），意思是突然发怒。"}, "sentence_index": null, "correct_answer": "一度"}, "level_3": {"options": [{"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示始终如此，与“现在没人去了”矛盾。"}, {"text": "一度", "is_correct": true, "explanation": "一度：表示过去有过一段时间的情况，现在已经不是这样，与“现在没人去了”前后呼应。"}, {"text": "老是", "is_correct": false, "explanation": "语域：“老是”口语色彩浓，且表示一直如此，与“现在没人去了”矛盾。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示依旧如此，与“现在没人去了”矛盾。"}], "explanations": {"永远": "语义：“永远”表示始终如此，与“现在没人去了”矛盾。", "一度": "一度：表示过去有过一段时间的情况，现在已经不是这样，与“现在没人去了”前后呼应。", "老是": "语域：“老是”口语色彩浓，且表示一直如此，与“现在没人去了”矛盾。", "仍然": "语义：“仍然”表示依旧如此，与“现在没人去了”矛盾。"}, "sentence_index": 0, "correct_answer": "一度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那条街一度很热闹，现在也是。", "explanation": "这里应该用〈一直〉。一度表示过去有过、现在已不是这样，而后面说“现在也是”，前后矛盾。"}, {"text": "明年我们一度要搬到上海。", "explanation": "一度只指过去曾有过的一段时间，不能用来说明明年这种将来的安排。"}, {"text": "我一度最喜欢喝茶，到现在还是这样。", "explanation": "这里应该用〈一直〉。一度表示过去有过、现在已不是这样，而句子说“到现在还是这样”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94093, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一度", "is_correct": true, "explanation": "一度（yí dù）：表示过去曾有过一段时间，现在已不是这样。"}, {"text": "一步", "is_correct": false, "explanation": "一步（yí bù）：bù 与 dù 声母不同（b 对 d），意思是一个脚步、一个阶段。"}, {"text": "一对", "is_correct": false, "explanation": "一对（yí duì）：duì 与 dù 韵母不同（ui 对 u），意思是一双、一组。"}, {"text": "一堵", "is_correct": false, "explanation": "一堵（yì dǔ）：dǔ 为第三声，与 dù（第四声）声调不同，且“一”变读为 yì；意思是一面（墙）。"}], "explanations": {"一度": "一度（yí dù）：表示过去曾有过一段时间，现在已不是这样。", "一步": "一步（yí bù）：bù 与 dù 声母不同（b 对 d），意思是一个脚步、一个阶段。", "一对": "一对（yí duì）：duì 与 dù 韵母不同（ui 对 u），意思是一双、一组。", "一堵": "一堵（yì dǔ）：dǔ 为第三声，与 dù（第四声）声调不同，且“一”变读为 yì；意思是一面（墙）。"}, "sentence_index": null, "correct_answer": "一度"}, "level_3": {"options": [{"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直住在北京，与“后来搬到了上海”矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示长期如此，与“后来搬到了上海”矛盾。"}, {"text": "一度", "is_correct": true, "explanation": "一度：表示过去曾在北京住过一段时间，后来搬走了，与句中的“后来”相呼应。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中的动作，“住”是持续状态，与“后来搬到了上海”的完成叙述不符。"}], "explanations": {"始终": "语义：“始终”表示一直住在北京，与“后来搬到了上海”矛盾。", "总是": "语义：“总是”表示长期如此，与“后来搬到了上海”矛盾。", "一度": "一度：表示过去曾在北京住过一段时间，后来搬走了，与句中的“后来”相呼应。", "正在": "体貌：“正在”表示进行中的动作，“住”是持续状态，与“后来搬到了上海”的完成叙述不符。"}, "sentence_index": 6, "correct_answer": "一度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一度很开朗，现在也是。", "explanation": "这里应该用〈总是〉。一度表示过去有过、现在已不是这样，与后面的“现在也是”矛盾。"}, {"text": "我每天一度去跑步。", "explanation": "一度只指过去曾有过的一段时间，不能用来描述每天重复的习惯。"}, {"text": "他的脾气一度很好，从来没有变过。", "explanation": "这里应该用〈一向〉。一度表示过去有过、现在已不是这样，而句子说“从来没有变过”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小镇一度的很热闹，现在冷清了。", "corrected_sentence": "这座小镇一度很热闹，现在冷清了。", "error_description": "错误：“一度”是副词，后面直接接“很热闹”，这里多加了“的”，说成“一度的很热闹”。正确：应说“一度很热闹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老师一度的很严格，现在变温和了。", "corrected_sentence": "那位老师一度很严格，现在变温和了。", "error_description": "错误：“一度”是副词，后面直接接“很严格”，这里多加了“的”，说成“一度的很严格”。正确：应说“一度很严格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
