INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不合作是不愿意跟别人一起做事。", "primary_collocate": null, "pronunciation": "bù hé zuò", "ipa": "pu˥˩ xɤ˧˥ tswo˥˩", "syllable_count": 3, "sentences": [{"text": "他在小组里不合作，大家很生气。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个孩子总是不合作，不愿意和同学玩。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人不合作，工作做不好。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么不合作？大家都在等你。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不合作，不肯和我一起收拾房间。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直不合作，所以我们很难做完。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的同学不合作，小组作业很慢。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不合作，是因为想法不一样。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到大家都不合作，老师很着急。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们组里有人不合作，所以作业一直没做完。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合作态度", "label": "复合"}, {"form": "不合作运动", "label": "复合"}], "register": "中性", "sense_fingerprint": "不合作|动词|不愿意跟别人一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不合作", "is_correct": true, "explanation": "不合作指不愿意跟别人一起做事，与“大家很生气”的结果相符。"}, {"text": "合作", "is_correct": false, "explanation": "语义：“合作”是一起做事，与“大家很生气”的结果不协调。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”表示加入，与“大家很生气”的语境不符，句子语义说不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”需要带宾语，如“欢迎大家”，这里没有宾语，且与“大家很生气”相冲突。"}], "explanations": {"不合作": "不合作指不愿意跟别人一起做事，与“大家很生气”的结果相符。", "合作": "语义：“合作”是一起做事，与“大家很生气”的结果不协调。", "参加": "语义：“参加”表示加入，与“大家很生气”的语境不符，句子语义说不通。", "欢迎": "配价：“欢迎”需要带宾语，如“欢迎大家”，这里没有宾语，且与“大家很生气”相冲突。"}, "sentence_index": 0, "correct_answer": "不合作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和同桌不合作完成了实验，老师很满意。", "explanation": "这里应该用〈合作〉。“不合作”是不愿意一起做事，与“完成了实验、老师很满意”的结果相矛盾。"}, {"text": "医生希望病人不合作，这样治疗才能顺利。", "explanation": "这里应该用〈配合〉。医生希望的是病人配合，“不合作”表示不愿配合，方向用反了。"}, {"text": "同学们都不合作打扫教室，所以很快就干干净净的。", "explanation": "这里应该用〈配合〉。“不合作”表示不愿意一起做，与“很快就干干净净”的结果矛盾，应说“配合打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不合作", "is_correct": true, "explanation": "不合作指不愿意一起做事，导致作业进度慢，与句意相符。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”需要宾语，如“完成作业”，这里没有宾语，句子不通。"}, {"text": "指导", "is_correct": false, "explanation": "配价：“指导”需要宾语，如“指导同学”，这里没有宾语，句子不通。"}, {"text": "帮忙", "is_correct": false, "explanation": "语义：有人“帮忙”应使作业变快，与“小组作业很慢”的结果相矛盾。"}], "explanations": {"不合作": "不合作指不愿意一起做事，导致作业进度慢，与句意相符。", "完成": "配价：“完成”需要宾语，如“完成作业”，这里没有宾语，句子不通。", "指导": "配价：“指导”需要宾语，如“指导同学”，这里没有宾语，句子不通。", "帮忙": "语义：有人“帮忙”应使作业变快，与“小组作业很慢”的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "不合作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都不合作这个计划，活动很顺利。", "explanation": "这里应该用〈支持〉。“不合作”表示不愿意一起做，与“活动很顺利”的结果矛盾。"}, {"text": "同学们都不合作讨论，气氛很热烈。", "explanation": "这里应该用〈参与〉。“不合作”表示不愿意一起做，与“气氛很热烈”的结果矛盾，应说“参与讨论”。"}, {"text": "同学们踊跃不合作，课堂很热闹。", "explanation": "这里应该用〈发言〉。“踊跃”表示积极主动，与“不合作”意思相反，应说“踊跃发言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人被这样不合作，我们都很为难。", "corrected_sentence": "这个人这样不合作，我们都很为难。", "error_description": "被字句错误：“不合作”是不及物动词，不能放在“被”字句里，应说“这个人这样不合作”，不说“这个人被这样不合作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把我们不合作，所以作业一直没做完。", "corrected_sentence": "他跟我们不合作，所以作业一直没做完。", "error_description": "搭配错误：“不合作”的对象要用“跟/和”引出，不能用“把”。应说“他跟我们不合作”，不说“他把我们不合作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
