INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不肯与他人配合或共同完成某事。", "primary_collocate": null, "pronunciation": "bù hé zuò", "ipa": "pu˥˩ xɤ˧˥ tswo˥˩", "syllable_count": 3, "sentences": [{"text": "同事不合作，这件事很难完成。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不合作，我们没办法开始。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对这个计划不合作，也不说原因。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问了他很多次，他都不合作。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李不合作，项目停了好几天。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人不合作，医生很难检查。", "target_word": "不合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们公司一直不合作，我们只好自己做。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想把事情做好，只有他不合作。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不合作，妈妈给他穿不上衣服。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方不合作，谈了半天也没有结果。", "target_word": "不合作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合作态度", "label": "复合"}, {"form": "不合作运动", "label": "复合"}], "register": "中性", "sense_fingerprint": "不合作|动词|不肯与他人配合或共同完成某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不合作", "is_correct": true, "explanation": "不合作指不愿意与别人配合，导致事情很难完成，与句意相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆祝成功，与“这件事很难完成”的语境不协调。"}, {"text": "忽视", "is_correct": false, "explanation": "配价：“忽视”需要宾语，如“忽视问题”，这里没有宾语，句子不通。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”表示加入，与“这件事很难完成”的结果相矛盾。"}], "explanations": {"不合作": "不合作指不愿意与别人配合，导致事情很难完成，与句意相符。", "祝贺": "语义：“祝贺”表示庆祝成功，与“这件事很难完成”的语境不协调。", "忽视": "配价：“忽视”需要宾语，如“忽视问题”，这里没有宾语，句子不通。", "参加": "语义：“参加”表示加入，与“这件事很难完成”的结果相矛盾。"}, "sentence_index": 0, "correct_answer": "不合作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对老师的提问做出了不合作。", "explanation": "这里应该用〈回应〉。“做出”后接的是回应或动作，“不合作”是动词，不能说“做出不合作”。"}, {"text": "他一直不合作父母的照顾，大家都很羡慕他。", "explanation": "这里应该用〈感谢〉。“不合作”表示不肯配合，与“感谢父母的照顾”的态度相反。"}, {"text": "我们都不合作新同学的加入。", "explanation": "这里应该用〈欢迎〉。“不合作”表示不肯配合，与“欢迎”的态度相反，不能用来表达对新同学加入的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不合作", "is_correct": true, "explanation": "不合作指不愿意合作，我们只好自己做，与句意相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，公司不会“下雨”，与句意不符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：公司不能“结婚”，与句子的主语不相容。"}, {"text": "参与", "is_correct": false, "explanation": "语义：公司“参与”了，我们就不必“只好自己做”，与后半句的结果相矛盾。"}], "explanations": {"不合作": "不合作指不愿意合作，我们只好自己做，与句意相符。", "下雨": "语义：“下雨”是天气现象，公司不会“下雨”，与句意不符。", "结婚": "语义：公司不能“结婚”，与句子的主语不相容。", "参与": "语义：公司“参与”了，我们就不必“只好自己做”，与后半句的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "不合作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双方终于不合作，合同也签了下来。", "explanation": "这里应该用〈妥协〉。“不合作”表示拒绝配合，与“合同签了下来”的结果矛盾。"}, {"text": "两个人在项目里不合作得很好，效率很高。", "explanation": "这里应该用〈配合〉。“不合作”表示不愿意一起做事，与“合作得很好、效率很高”矛盾。"}, {"text": "我们很不合作大家的帮助。", "explanation": "这里应该用〈感谢〉。“不合作”表示不肯配合，与“感谢大家的帮助”的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又被不合作了，大家都很生气。", "corrected_sentence": "他又不合作了，大家都很生气。", "error_description": "被字句错误：“不合作”是不及物动词，不能用于“被”字句，应说“他又不合作了”，不说“他又被不合作了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对方一直把我们不合作，谈判很难进行。", "corrected_sentence": "对方一直跟我们不合作，谈判很难进行。", "error_description": "搭配错误：“不合作”的对象要用“跟/和”引出，不能用“把”。应说“对方一直跟我们不合作”，不说“对方一直把我们不合作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
