INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94099, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94099, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交往是跟别人来来往往，在一起玩，成为朋友。", "primary_collocate": null, "pronunciation": "jiāo wǎng", "ipa": "tɕjau˥ waŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他很会和新同学交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他从小学起就常常交往，是好朋友。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不让我和坏孩子交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性格开朗，容易和别人交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚搬来的时候，我不太敢和邻居交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和班里的同学都交往得很好。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你应该多和不同的人交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们交往了很久，才成为好朋友。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不爱说话，很少跟人交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和外国人交往，你的汉语会进步得更快。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交往了", "label": "完成体"}, {"form": "交往过", "label": "经历体"}, {"form": "交往着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "与人来往、相处并成为朋友（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲课", "is_correct": false, "explanation": "搭配：“讲课”是老师对学生的教学活动，不说和同学讲课。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状况，不表示与人来往，句意不通。"}, {"text": "交往", "is_correct": true, "explanation": "正确：交往指与人来往、相处，符合句意。"}, {"text": "打针", "is_correct": false, "explanation": "语义：“打针”是就医行为，不能用来说与同学相处。"}], "explanations": {"讲课": "搭配：“讲课”是老师对学生的教学活动，不说和同学讲课。", "生病": "语义：“生病”是身体状况，不表示与人来往，句意不通。", "交往": "正确：交往指与人来往、相处，符合句意。", "打针": "语义：“打针”是就医行为，不能用来说与同学相处。"}, "sentence_index": 0, "correct_answer": "交往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国在边境交往，已经打了一个月。", "explanation": "这里应该用〈交战〉。交战指双方武装打仗，“交往”指友好来往，两国在边境打仗不能用交往。"}, {"text": "两根电线在这里交往，冒出了火花。", "explanation": "这里应该用〈交叉〉。交叉指线路相互穿过；电线相接应说交叉，“交往”指人与人之间的来往，不能用于电线。"}, {"text": "两个孩子因为一个玩具在街上交往，差点打起来。", "explanation": "这里应该用〈交手〉。交手指动手打斗或较量；“交往”指友好来往，不能用于打架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：“考试”是学习活动，与“多和不同的人”的建议不符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，人不能“和人下雨”。"}, {"text": "交往", "is_correct": true, "explanation": "正确：交往指与人来往，符合句意。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，不能表示与人相处。"}], "explanations": {"考试": "语义：“考试”是学习活动，与“多和不同的人”的建议不符。", "下雨": "语义：“下雨”是天气现象，人不能“和人下雨”。", "交往": "正确：交往指与人来往，符合句意。", "发烧": "语义：“发烧”是身体状况，不能表示与人相处。"}, "sentence_index": 6, "correct_answer": "交往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们考完后陆续交往。", "explanation": "这里应该用〈交卷〉。交卷指把试卷交给老师，“交往”指人际来往，考试后不能用交往。"}, {"text": "两队在决赛中交往。", "explanation": "这里应该用〈交锋〉。交锋指双方对抗比赛，“交往”指友好来往，比赛对抗不能用交往。"}, {"text": "两种颜色在画上交往。", "explanation": "这里应该用〈交织〉。交织指线条或色彩相互错杂，“交往”指人与人之间的来往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前交往了过，现在不太联系了。", "corrected_sentence": "我们以前交往过，现在不太联系了。", "error_description": "体标错误：“了”与“过”不能同时用在同一个动词后，表示经历只用“过”，应说“交往过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把外国朋友交往两年了。", "corrected_sentence": "他和外国朋友交往两年了。", "error_description": "介词错误：“交往”的对象要用介词“和”引出，应说“和外国朋友交往”；“把”字句不能这样用于“交往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人与人之间互相往来、接触。", "primary_collocate": null, "pronunciation": "jiāo wǎng", "ipa": "tɕjau˥ waŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "朋友之间的交往要真诚。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多一些交往，就会多一些了解。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的交往一直很愉快。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和邻居的交往很少。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人与人的交往需要真诚和耐心。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人最怕孤单，希望多一点交往。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间的交往越来越多。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行以后，我们的交往多了起来。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，同学之间的交往也是一门学问。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作以后，我和同事的交往比较少。", "target_word": "交往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人际交往", "label": "复合词"}, {"form": "社会交往", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人与人之间的往来接触（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通", "is_correct": false, "explanation": "语义：“交通”指道路运输，与朋友之间的真诚无关。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：“真诚”修饰人与人之间的关系，不用来形容饮食。"}, {"text": "交往", "is_correct": true, "explanation": "正确：交往指人与人之间的往来，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人际关系，不能要求真诚。"}], "explanations": {"交通": "语义：“交通”指道路运输，与朋友之间的真诚无关。", "饮食": "搭配：“真诚”修饰人与人之间的关系，不用来形容饮食。", "交往": "正确：交往指人与人之间的往来，符合句意。", "天气": "语义：“天气”不是人际关系，不能要求真诚。"}, "sentence_index": 0, "correct_answer": "交往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的交往很方便。", "explanation": "这里应该用〈交通〉。交通指车辆和道路的往来，形容道路方便应说交通；交往指人与人之间的往来，不能用于道路。"}, {"text": "白天与黑夜的交往很有规律。", "explanation": "这里应该用〈交替〉。交替指事物轮流更换，白天与黑夜的更替应说交替；交往指人际来往。"}, {"text": "两条铁路的交往很多。", "explanation": "这里应该用〈交叉〉。交叉指线路相互穿过，两条铁路相接应说交叉；交往指人际来往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“作业”是学生的课后任务，不用于说两国之间的关系。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”不是人际往来，两国之间不能说病毒越来越多。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是物品，不属于两国之间的关系。"}, {"text": "交往", "is_correct": true, "explanation": "正确：交往指两国之间的往来，符合句意。"}], "explanations": {"作业": "搭配：“作业”是学生的课后任务，不用于说两国之间的关系。", "病毒": "语义：“病毒”不是人际往来，两国之间不能说病毒越来越多。", "鞋子": "语义：“鞋子”是物品，不属于两国之间的关系。", "交往": "正确：交往指两国之间的往来，符合句意。"}, "sentence_index": 6, "correct_answer": "交往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂按时交往，客户很满意。", "explanation": "这里应该用〈交货〉。交货指把货物按时送到客户手中；“交往”指人与人之间的往来，不能用于交货。"}, {"text": "两条河在这里交往，形成一片湖。", "explanation": "这里应该用〈交汇〉。交汇指河流等汇合在一起；“交往”指人际来往，不能用于河流相会。"}, {"text": "两个季节在这里交往，天气变化很大。", "explanation": "这里应该用〈交替〉。交替指事物轮流更换，季节更换应说交替；“交往”指人与人之间的往来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们之间有过一座愉快的交往。", "corrected_sentence": "他们之间有过一段愉快的交往。", "error_description": "量词错误：“座”用于山、桥、房屋等大型物体，修饰“交往”应用“段”，说“一段愉快的交往”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们之间地交往很愉快。", "corrected_sentence": "我们之间的交往很愉快。", "error_description": "结构助词错误：修饰名词“交往”应用“的”，“地”用于修饰动词；应说“我们之间的交往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
