INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修正是把不对的地方改成对的。", "primary_collocate": null, "pronunciation": "xiū zhèng", "ipa": "ɕi̯oʊ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他把试卷上的错字修正了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现问题后，我们马上修正。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑修正了文章里的错字。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个说明有错，请你修正。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她修正了自己的发音。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师修正了图纸上的数字。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们自己修正答案。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修正过这篇文章三次。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者把新闻里的错误修正了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误我已经修正好了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修正了", "label": "体标"}, {"form": "修正过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把不对的地方改成对的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修正", "is_correct": true, "explanation": "正确。“修正”表示改正错字，与“错字”搭配。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：“朗读”指大声读出文字，不能用来表示改正错字。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物品，不能用来表示改正错字。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，不能说收割错字。"}], "explanations": {"修正": "正确。“修正”表示改正错字，与“错字”搭配。", "朗读": "语义：“朗读”指大声读出文字，不能用来表示改正错字。", "装饰": "语义：“装饰”指美化物品，不能用来表示改正错字。", "收割": "搭配：“收割”用于庄稼，不能说收割错字。"}, "sentence_index": 0, "correct_answer": "修正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人修正了坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。修正指改正错误或偏差，不用于修复坏掉的机器。"}, {"text": "师傅修正了开裂的墙壁。", "explanation": "这里应该用〈修补〉。修正指改正错误或偏差，不用于修补破损的墙面。"}, {"text": "医生修正了他的感冒。", "explanation": "这里应该用〈治疗〉。修正指改正错误，不用于治疗疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
