INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改正错误或偏差，使之正确、合适。", "primary_collocate": null, "pronunciation": "xiū zhèng", "ipa": "ɕi̯oʊ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师修正了作文里的错误。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要修正今年的计划。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你修正一下这张地图上的错误。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家修正了原来的看法。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要及时修正自己的方向。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现数字错了，马上修正了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生修正了治疗方案。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理修正了报告里的数据。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在飞行中修正了航线。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府已经修正了这条规定。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修正了", "label": "体标"}, {"form": "修正过", "label": "体标"}], "register": "书面", "sense_fingerprint": "改正错误或偏差，使之正确合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修正", "is_correct": true, "explanation": "正确。“修正”表示改正错误，与“作文里的错误”搭配。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，不能用来表示改正错误。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发，不能说修剪错误。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”的对象是人或美好的事物，不能用来赞美错误。"}], "explanations": {"修正": "正确。“修正”表示改正错误，与“作文里的错误”搭配。", "欣赏": "语义：“欣赏”指赏识美好的事物，不能用来表示改正错误。", "修剪": "搭配：“修剪”用于枝叶、头发，不能说修剪错误。", "赞美": "语义：“赞美”的对象是人或美好的事物，不能用来赞美错误。"}, "sentence_index": 0, "correct_answer": "修正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人修正了坏掉的自行车。", "explanation": "这里应该用〈修理〉。修正指改正错误或偏差，不用于修复坏掉的机器。"}, {"text": "我们修正了工作环境。", "explanation": "这里应该用〈改善〉。修正用于错误、计划、看法等，不用于改进环境状况。"}, {"text": "他修正了漏雨的屋顶。", "explanation": "这里应该用〈修补〉。修正指纠正错误或偏差，不用于修补破损的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
