INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94105, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优是很好，比别的都好。", "primary_collocate": null, "pronunciation": "yōu", "ipa": "joʊ̯˥", "syllable_count": 1, "sentences": [{"text": "这两箱水果，一箱质量优，一箱质量劣，你要认真挑。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种产品，一个优，一个劣，一看就知道。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套方案各项指标都最优，我们选它。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产品质量很优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过反复测试，这个算法的速度最优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样的价钱，这个牌子的质量更优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批茶叶品质很优，价格也不贵。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他各方面条件都很优，所以被选中了。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划成本低、效果好，是最优的一个。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个方案比较起来，第二个更优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "優", "label": "繁体"}], "register": "中性", "sense_fingerprint": "质量、条件很好，比别的好（与劣相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94105, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。优读 yōu（第一声），指质量、条件很好。"}, {"text": "幼", "is_correct": false, "explanation": "「yòu（第四声）与 yōu（第一声）声调不同，意思是年纪小」。"}, {"text": "由", "is_correct": false, "explanation": "「yóu（第二声）与 yōu（第一声）声调不同，意思是由于、经过」。"}, {"text": "有", "is_correct": false, "explanation": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是有」。"}], "explanations": {"优": "正确。优读 yōu（第一声），指质量、条件很好。", "幼": "「yòu（第四声）与 yōu（第一声）声调不同，意思是年纪小」。", "由": "「yóu（第二声）与 yōu（第一声）声调不同，意思是由于、经过」。", "有": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是有」。"}, "sentence_index": null, "correct_answer": "优"}, "level_3": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。「一箱质量优，一箱质量劣」对比质量的好坏，「优」指质量好，与「劣」相对。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」指味道，与「优劣」所说的质量好坏不是同一类。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」指质地，不能与「劣」构成质量好坏的对比。"}, {"text": "香", "is_correct": false, "explanation": "语义：「香」指气味，与「优劣」不构成对比。"}], "explanations": {"优": "正确。「一箱质量优，一箱质量劣」对比质量的好坏，「优」指质量好，与「劣」相对。", "甜": "语义：「甜」指味道，与「优劣」所说的质量好坏不是同一类。", "硬": "搭配：「硬」指质地，不能与「劣」构成质量好坏的对比。", "香": "语义：「香」指气味，与「优劣」不构成对比。"}, "sentence_index": 0, "correct_answer": "优"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学期末考试得了优。", "explanation": "这里的「优」是考核等级的义项，与形容质量好、比别的都好的义项不同。"}, {"text": "这次抽检，这家工厂的产品得了优。", "explanation": "这里的「优」是考核等级的义项，与形容质量好、比别的都好的义项不同；此句用的是等级义。"}, {"text": "这家工厂的产品考核结果是优。", "explanation": "这里的「优」指考核等级，是另一义项，与「很好、比别的都好」不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94105, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。优读 yōu（第一声），指质量、条件很好。"}, {"text": "游", "is_correct": false, "explanation": "「yóu（第二声）与 yōu（第一声）声调不同，意思是游泳」。"}, {"text": "右", "is_correct": false, "explanation": "「yòu（第四声）与 yōu（第一声）声调不同，意思是右边」。"}, {"text": "友", "is_correct": false, "explanation": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是朋友」。"}], "explanations": {"优": "正确。优读 yōu（第一声），指质量、条件很好。", "游": "「yóu（第二声）与 yōu（第一声）声调不同，意思是游泳」。", "右": "「yòu（第四声）与 yōu（第一声）声调不同，意思是右边」。", "友": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是朋友」。"}, "sentence_index": null, "correct_answer": "优"}, "level_3": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。「品质很优」说明茶叶质量好，与后句「价格也不贵」相呼应。"}, {"text": "苦", "is_correct": false, "explanation": "语义：「苦」指味道，不能用来评价「品质很…」。"}, {"text": "辣", "is_correct": false, "explanation": "语义：「辣」指味道刺激，与品质无关。"}, {"text": "烫", "is_correct": false, "explanation": "语义：「烫」指温度，与「品质很…」不搭。"}], "explanations": {"优": "正确。「品质很优」说明茶叶质量好，与后句「价格也不贵」相呼应。", "苦": "语义：「苦」指味道，不能用来评价「品质很…」。", "辣": "语义：「辣」指味道刺激，与品质无关。", "烫": "语义：「烫」指温度，与「品质很…」不搭。"}, "sentence_index": 6, "correct_answer": "优"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个方案都评审过了，第二个的评级是优。", "explanation": "这里的「优」是评级等级，与「比较起来更好」的质量义不同。"}, {"text": "老师给第二个方案打了优，第一个打了良。", "explanation": "这里的「优」是评分等级，与比较质量好坏的义项不同。"}, {"text": "两个方案比较起来，第二个的成绩是优。", "explanation": "这里的「优」是成绩等级，与比较质量好坏的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂的产品质量确实优很。", "corrected_sentence": "这家工厂的产品质量确实很优。", "error_description": "语序错误。程度副词「很」应放在形容词「优」前作状语，「优很」是错误语序，应为「很优」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两台机器比较起来，新的那台比旧的那台很优。", "corrected_sentence": "这两台机器比较起来，新的那台比旧的那台更优。", "error_description": "程度副词错误。「比」字句中形容词「优」前不能用「很」，应用「更」，即「比旧的那台更优」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
