INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94106, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优秀，良好，胜过一般水平。", "primary_collocate": null, "pronunciation": "yōu", "ipa": "joʊ̯˥", "syllable_count": 1, "sentences": [{"text": "这次考试，我的作文得了优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体育成绩是优，数学是良。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我的口语打了优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这学期的成绩单上，我的英语得了优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王各门功课都是优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的评分是优，大家都很高兴。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语考试成绩为优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成绩单上写着一个大大的优。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她数学考了优，开心极了。", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课的最后成绩是优还是良？", "target_word": "优", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "優", "label": "繁体"}], "register": "中性", "sense_fingerprint": "成绩等级中的优，最高等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。优读 yōu（第一声），指成绩等级中的最高等级。"}, {"text": "有", "is_correct": false, "explanation": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是有」。"}, {"text": "右", "is_correct": false, "explanation": "「yòu（第四声）与 yōu（第一声）声调不同，意思是右边」。"}, {"text": "油", "is_correct": false, "explanation": "「yóu（第二声）与 yōu（第一声）声调不同，意思是油」。"}, {"text": "友", "is_correct": false, "explanation": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是朋友」。"}], "explanations": {"优": "正确。优读 yōu（第一声），指成绩等级中的最高等级。", "有": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是有」。", "右": "「yòu（第四声）与 yōu（第一声）声调不同，意思是右边」。", "油": "「yóu（第二声）与 yōu（第一声）声调不同，意思是油」。", "友": "「yǒu（第三声）与 yōu（第一声）声调不同，意思是朋友」。"}, "sentence_index": null, "correct_answer": "优"}, "level_3": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。「得了优」指成绩等级为优，与「考试」「作文」的语境相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「得了」后接成绩等级，形容词「高」不能作成绩等级。"}, {"text": "满", "is_correct": false, "explanation": "搭配：「满」通常说「满分」，「得了满」不能用来表示成绩。"}, {"text": "厚", "is_correct": false, "explanation": "语义：「厚」指物体的厚度，与作文成绩无关。"}], "explanations": {"优": "正确。「得了优」指成绩等级为优，与「考试」「作文」的语境相符。", "高": "搭配：「得了」后接成绩等级，形容词「高」不能作成绩等级。", "满": "搭配：「满」通常说「满分」，「得了满」不能用来表示成绩。", "厚": "语义：「厚」指物体的厚度，与作文成绩无关。"}, "sentence_index": 0, "correct_answer": "优"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几种材料里，这一种的质量最优。", "explanation": "这里的「优」表示质量好、比别的都好，是另一义项，与成绩等级的「优」无关。"}, {"text": "这个方案优于那个方案，大家都同意。", "explanation": "这里的「优」作动词，表示胜过、比……好（优于），是另一义项，与成绩等级的「优」无关。"}, {"text": "这台机器的性能很优，大家都很满意。", "explanation": "这里的「优」表示性能很好、比别的都好，是另一义项，与成绩等级的「优」无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。优读 yōu（第一声），指成绩等级中的最高等级。"}, {"text": "游", "is_correct": false, "explanation": "「yóu（第二声）与 yōu（第一声）声调不同，意思是游泳」。"}, {"text": "又", "is_correct": false, "explanation": "「yòu（第四声）与 yōu（第一声）声调不同，意思是再、又」。"}, {"text": "幼", "is_correct": false, "explanation": "「yòu（第四声）与 yōu（第一声）声调不同，意思是年纪小」。"}, {"text": "由", "is_correct": false, "explanation": "「yóu（第二声）与 yōu（第一声）声调不同，意思是由于、经过」。"}], "explanations": {"优": "正确。优读 yōu（第一声），指成绩等级中的最高等级。", "游": "「yóu（第二声）与 yōu（第一声）声调不同，意思是游泳」。", "又": "「yòu（第四声）与 yōu（第一声）声调不同，意思是再、又」。", "幼": "「yòu（第四声）与 yōu（第一声）声调不同，意思是年纪小」。", "由": "「yóu（第二声）与 yōu（第一声）声调不同，意思是由于、经过」。"}, "sentence_index": null, "correct_answer": "优"}, "level_3": {"options": [{"text": "优", "is_correct": true, "explanation": "正确。「为优」指成绩等级是优，与「汉语考试成绩」的语境相符。"}, {"text": "冷", "is_correct": false, "explanation": "语义：「冷」指温度，不能用来评价成绩。"}, {"text": "短", "is_correct": false, "explanation": "语义：「短」指长度，与成绩等级无关。"}, {"text": "老", "is_correct": false, "explanation": "搭配：「老」指年龄或陈旧，不能作成绩的评价。"}], "explanations": {"优": "正确。「为优」指成绩等级是优，与「汉语考试成绩」的语境相符。", "冷": "语义：「冷」指温度，不能用来评价成绩。", "短": "语义：「短」指长度，与成绩等级无关。", "老": "搭配：「老」指年龄或陈旧，不能作成绩的评价。"}, "sentence_index": 6, "correct_answer": "优"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次选拔，他的综合条件最优，被选中了。", "explanation": "这里的「优」表示条件很好、比别的都好，是另一义项，与成绩等级的「优」无关。"}, {"text": "他的综合能力优于同学，老师很满意。", "explanation": "这里的「优」作动词，表示胜过，是另一义项，与成绩等级的「优」无关。"}, {"text": "这家商店的服务质量很优，顾客都满意。", "explanation": "这里的「优」表示质量很好，是另一义项，与成绩等级的「优」无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的数学考试得了一只优，她很高兴。", "corrected_sentence": "她的数学考试得了一个优，她很高兴。", "error_description": "量词错误。「优」是成绩等级，前面应用量词「个」，不能用「只」。「只」用于动物或成对物品中的一件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的汉语成绩很优。", "corrected_sentence": "我的汉语成绩是优。", "error_description": "词语选择错误。「优」作成绩等级时，应用「是」连接，不能用程度副词「很」修饰。正确说法是「成绩是优」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进站", "is_correct": true, "explanation": "进站与出站相对：一个是进入车站，一个是离开车站，构成反义。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“出站”没有反义关系，不是它任何义项的反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“出站”没有反义关系，二者语义无对立。"}, {"text": "登机", "is_correct": false, "explanation": "登机指上飞机，与“出站”没有反义关系。"}], "correct_answer": "进站", "explanations": {"进站": "进站与出站相对：一个是进入车站，一个是离开车站，构成反义。", "吃饭": "与“出站”没有反义关系，不是它任何义项的反义词。", "睡觉": "与“出站”没有反义关系，二者语义无对立。", "登机": "登机指上飞机，与“出站”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
