INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开车站，或列车驶出车站。", "primary_collocate": null, "pronunciation": "chū zhàn", "ipa": "ʈʂʰu˥ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "火车慢慢出站了。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "列车出站后，速度越来越快。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这趟高铁刚出站，我们没赶上。", "target_word": "出站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁刚出站，天就黑了。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乘客们从北门出站，坐上了出租车。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出站时，手机没电了。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快车先出站，慢车还在等着。", "target_word": "出站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车还没出站，他赶紧跑了上去。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一出站，就看见了接我的人。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人拿着票，跟大家一起出站。", "target_word": "出站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了站", "label": "体标"}, {"form": "出站口", "label": "复合"}], "register": "中性", "sense_fingerprint": "人离开车站或列车驶出车站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd71f46b-59ce-4fa8-abe9-85caaf31d755') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出站", "is_correct": true, "explanation": "出站指列车驶出车站，与“火车慢慢”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：火车不会散步，与句子的主语不搭。"}, {"text": "起床", "is_correct": false, "explanation": "语义：火车不会起床，动作的主体与句子不合。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物的生长，火车不会发芽，句子不成立。"}], "explanations": {"出站": "出站指列车驶出车站，与“火车慢慢”相符。", "散步": "语义：火车不会散步，与句子的主语不搭。", "起床": "语义：火车不会起床，动作的主体与句子不合。", "发芽": "语义：发芽是植物的生长，火车不会发芽，句子不成立。"}, "sentence_index": 0, "correct_answer": "出站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年出站留学了。", "explanation": "这里应该用〈出国〉。出站只指离开车站，不指出国留学。"}, {"text": "他康复以后就出站了。", "explanation": "这里应该用〈出院〉。出站只指离开车站，不能用于病人离开医院。"}, {"text": "演员在台上讲完话，就出站了。", "explanation": "这里应该用〈出场〉。出站只指离开车站，不能指演员登台或退场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出站", "is_correct": true, "explanation": "出站指列车驶出车站，与“快车先”“慢车还在等着”相符。"}, {"text": "上车", "is_correct": false, "explanation": "配价：“上车”的主体须是乘客，快车不能“上车”。"}, {"text": "打牌", "is_correct": false, "explanation": "语义：快车不会打牌，与句中列车的语境不合。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：快车不会挂号，句子不成立。"}], "explanations": {"出站": "出站指列车驶出车站，与“快车先”“慢车还在等着”相符。", "上车": "配价：“上车”的主体须是乘客，快车不能“上车”。", "打牌": "语义：快车不会打牌，与句中列车的语境不合。", "挂号": "语义：快车不会挂号，句子不成立。"}, "sentence_index": 6, "correct_answer": "出站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书明年出站。", "explanation": "这里应该用〈出版〉。出站只指人或列车离开车站，不能用于书籍。"}, {"text": "他的手指被刀划伤，出站了。", "explanation": "这里应该用〈出血〉。出站不能用来描述伤口流出血液。"}, {"text": "早上太阳从东边出站了。", "explanation": "这里应该用〈升起〉。出站只指人或列车离开车站，不能用于太阳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "列车出站着，车厢里的广播就响了起来。", "corrected_sentence": "列车出站了，车厢里的广播就响了起来。", "error_description": "错误形式：「出站着」。正确形式：「出站了」。「着」表示持续或状态，与一次性的离站动作不合，完成的离站要用「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一出站了，就看见了朋友。", "corrected_sentence": "他一出站，就看见了朋友。", "error_description": "错误形式：「一出站了」。正确形式：「一出站」。「一……就……」中「一」后的动词不能加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
