INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94109, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "切是用刀把东西分成几块。", "primary_collocate": null, "pronunciation": "qiē", "ipa": "/tɕʰjɛ˥/", "syllable_count": 1, "sentences": [{"text": "请把苹果切成四块。", "target_word": "切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在厨房切菜。", "target_word": "切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用刀切了一块肉。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会切洋葱。", "target_word": "切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这把刀很快，切面包很容易。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能帮我切一下西瓜吗？", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕切好以后，我们开始吃。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸切着肉，我在旁边洗碗。", "target_word": "切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他切过很多次土豆，切得很细。", "target_word": "切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把面包切开，再放黄油。", "target_word": "切", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "切了", "label": "体标（了）"}, {"form": "切过", "label": "体标（过）"}, {"form": "切着", "label": "体标（着）"}, {"form": "切一切", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用刀把食物等东西分成几块，如切菜、切肉、切面包", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "切", "is_correct": true, "explanation": "切（qiē，第一声）是用刀把东西分成几块，是本题的词。"}, {"text": "且", "is_correct": false, "explanation": "且（qiě，第三声）与切（qiē，第一声）声调不同，意思是“而且、并且”。"}, {"text": "茄", "is_correct": false, "explanation": "茄（qié，第二声）与切（qiē，第一声）声调不同，意思是“茄子”。"}, {"text": "掐", "is_correct": false, "explanation": "掐（qiā）的韵母是 a，与切的 ie 不同，意思是“用手指按压”。"}], "explanations": {"切": "切（qiē，第一声）是用刀把东西分成几块，是本题的词。", "且": "且（qiě，第三声）与切（qiē，第一声）声调不同，意思是“而且、并且”。", "茄": "茄（qié，第二声）与切（qiē，第一声）声调不同，意思是“茄子”。", "掐": "掐（qiā）的韵母是 a，与切的 ie 不同，意思是“用手指按压”。"}, "sentence_index": null, "correct_answer": "切"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，把苹果洗成四块与句意不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“成四块”搭配，表示切分的结果。"}, {"text": "搅", "is_correct": false, "explanation": "语义：“搅”是搅拌，不能把苹果搅成四块。"}, {"text": "切", "is_correct": true, "explanation": "切：用刀把苹果分成四块，与句意相合。"}], "explanations": {"洗": "语义：“洗”是清洗，把苹果洗成四块与句意不符。", "吃": "搭配：“吃”不能与“成四块”搭配，表示切分的结果。", "搅": "语义：“搅”是搅拌，不能把苹果搅成四块。", "切": "切：用刀把苹果分成四块，与句意相合。"}, "sentence_index": 0, "correct_answer": "切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去地里切麦子，忙了一整天。", "explanation": "这里应该用〈割〉。割用于收割、割断草木庄稼，如割麦子、割草；切是把食物等东西分成块，不说“切麦子”。"}, {"text": "他用斧子切了一下午树，累得满头大汗。", "explanation": "这里应该用〈砍〉。砍指用斧子等把树木、柴禾砍断；切是把东西分成几块，不说“切树”。"}, {"text": "他用小刀切铅笔，切得很尖。", "explanation": "这里应该用〈削〉。削指用刀去掉物体表面，如削铅笔、削皮；切是把整体分开，不说“切铅笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94109, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "切", "is_correct": true, "explanation": "切（qiē，第一声）是用刀把东西分成几块，是本题的词。"}, {"text": "窃", "is_correct": false, "explanation": "窃（qiè，第四声）与切（qiē，第一声）声调不同，意思是“偷、盗”。"}, {"text": "怯", "is_correct": false, "explanation": "怯（qiè，第四声）与切（qiē，第一声）声调不同，意思是“胆怯”。"}, {"text": "些", "is_correct": false, "explanation": "些（xiē，第一声）与切（qiē，第一声）声母不同（x 与 q），意思是“一点、若干”。"}, {"text": "七", "is_correct": false, "explanation": "七（qī，第一声）与切（qiē）韵母不同（i 与 ie），意思是数字“七”。"}], "explanations": {"切": "切（qiē，第一声）是用刀把东西分成几块，是本题的词。", "窃": "窃（qiè，第四声）与切（qiē，第一声）声调不同，意思是“偷、盗”。", "怯": "怯（qiè，第四声）与切（qiē，第一声）声调不同，意思是“胆怯”。", "些": "些（xiē，第一声）与切（qiē，第一声）声母不同（x 与 q），意思是“一点、若干”。", "七": "七（qī，第一声）与切（qiē）韵母不同（i 与 ie），意思是数字“七”。"}, "sentence_index": null, "correct_answer": "切"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，蛋糕扔好以后不符合后半句“我们开始吃”。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”不能与结果补语“好”搭配，表示做完某件事。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压，蛋糕踩好与“开始吃”的语境不符。"}, {"text": "切", "is_correct": true, "explanation": "切：把蛋糕切好，才能开始吃，与句意相合。"}], "explanations": {"扔": "语义：“扔”是丢掉，蛋糕扔好以后不符合后半句“我们开始吃”。", "摔": "搭配：“摔”不能与结果补语“好”搭配，表示做完某件事。", "踩": "语义：“踩”是用脚压，蛋糕踩好与“开始吃”的语境不符。", "切": "切：把蛋糕切好，才能开始吃，与句意相合。"}, "sentence_index": 6, "correct_answer": "切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上切胡子，切得很干净。", "explanation": "这里应该用〈刮〉。刮指用刀片去掉表面的毛发等，如刮胡子；切是把东西分成几块，不说“切胡子”。"}, {"text": "他在院子里切了一个深坑，切了一下午。", "explanation": "这里应该用〈挖〉。挖指用工具掘出凹洞，如挖坑；切是把物体分成几块，不能用来掘坑。"}, {"text": "他用力切毛巾，切得手都红了。", "explanation": "这里应该用〈拧〉。拧指用手转动使毛巾等扭转或挤去水分，如拧毛巾；切不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把土豆切到了细丝。", "corrected_sentence": "妈妈把土豆切成了细丝。", "error_description": "补语错误：“切到”应改为“切成”。“切成”表示把东西切成某种形状，“切到”表示刀碰到或切中（如切到手），不能用于切成细丝。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饼干切了好以后，我们装盒。", "corrected_sentence": "饼干切好以后，我们装盒。", "error_description": "“了”位置错误：“切了好”不成立，结果补语“好”应紧跟动词，应说“切好以后”，“了”不能插在“切”和“好”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
