INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀等锐利的工具把物体分成几部分。", "primary_collocate": null, "pronunciation": "qiē", "ipa": "/tɕʰjɛ˥/", "syllable_count": 1, "sentences": [{"text": "他拿刀切开了西瓜。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶正在切青菜。", "target_word": "切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把这块肉切成片。", "target_word": "切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把香肠切成了薄片。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把面包切成两半。", "target_word": "切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师切菜切得又快又好。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想用小刀切水果。", "target_word": "切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她切了一盘苹果给客人。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先切葱，我来洗菜。", "target_word": "切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块蛋糕太大，我们切一半吧。", "target_word": "切", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "切了", "label": "体标（了）"}, {"form": "切过", "label": "体标（过）"}, {"form": "切着", "label": "体标（着）"}, {"form": "切一切", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用刀等锐利的工具把物体分成几部分，如切开、切成片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "切", "is_correct": true, "explanation": "切（qiē，第一声）是用锐利工具把物体分开，是本题的词。"}, {"text": "茄", "is_correct": false, "explanation": "茄（qié，第二声）与切（qiē，第一声）声调不同，意思是“茄子”。"}, {"text": "掐", "is_correct": false, "explanation": "掐（qiā）的韵母是 a，与切的 ie 不同，意思是“用手指按压”。"}, {"text": "窃", "is_correct": false, "explanation": "窃（qiè，第四声）与切（qiē，第一声）声调不同，意思是“偷”。"}], "explanations": {"切": "切（qiē，第一声）是用锐利工具把物体分开，是本题的词。", "茄": "茄（qié，第二声）与切（qiē，第一声）声调不同，意思是“茄子”。", "掐": "掐（qiā）的韵母是 a，与切的 ie 不同，意思是“用手指按压”。", "窃": "窃（qiè，第四声）与切（qiē，第一声）声调不同，意思是“偷”。"}, "sentence_index": null, "correct_answer": "切"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：句中有“拿刀”，“洗”是清洗，不能洗开西瓜。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与结果补语“开”搭配，表示切开西瓜。"}, {"text": "摔", "is_correct": false, "explanation": "语义：句中有“拿刀”，“摔”不是用刀的动作，不能表示切开。"}, {"text": "切", "is_correct": true, "explanation": "切：用刀把西瓜切开，与“拿刀”的语境相合。"}], "explanations": {"洗": "语义：句中有“拿刀”，“洗”是清洗，不能洗开西瓜。", "吃": "搭配：“吃”不能与结果补语“开”搭配，表示切开西瓜。", "摔": "语义：句中有“拿刀”，“摔”不是用刀的动作，不能表示切开。", "切": "切：用刀把西瓜切开，与“拿刀”的语境相合。"}, "sentence_index": 0, "correct_answer": "切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地里切草，一直干到天黑。", "explanation": "这里应该用〈割〉。割用于割草、割麦子，表示把草木庄稼割断；切草不是正确说法。"}, {"text": "他用刮刀切墙皮，切了一上午。", "explanation": "这里应该用〈刮〉。刮指用刀具去掉表面的东西，如刮墙皮、刮胡子；切是把物体分成几块，不说“切墙皮”。"}, {"text": "他用小刀切铅笔，切得很尖。", "explanation": "这里应该用〈削〉。削指用刀去掉物体表面，如削铅笔、削皮；切是把整体分开，不说“切铅笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94110, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "切", "is_correct": true, "explanation": "切（qiē，第一声）是用锐利工具把物体分开，是本题的词。"}, {"text": "且", "is_correct": false, "explanation": "且（qiě，第三声）与切（qiē，第一声）声调不同，意思是“而且、并且”。"}, {"text": "些", "is_correct": false, "explanation": "些（xiē，第一声）与切（qiē，第一声）声母不同（x 与 q），意思是“一点、若干”。"}, {"text": "七", "is_correct": false, "explanation": "七（qī，第一声）与切（qiē）韵母不同（i 与 ie），意思是数字“七”。"}, {"text": "怯", "is_correct": false, "explanation": "怯（qiè，第四声）与切（qiē，第一声）声调不同，意思是“胆怯”。"}], "explanations": {"切": "切（qiē，第一声）是用锐利工具把物体分开，是本题的词。", "且": "且（qiě，第三声）与切（qiē，第一声）声调不同，意思是“而且、并且”。", "些": "些（xiē，第一声）与切（qiē，第一声）声母不同（x 与 q），意思是“一点、若干”。", "七": "七（qī，第一声）与切（qiē）韵母不同（i 与 ie），意思是数字“七”。", "怯": "怯（qiè，第四声）与切（qiē，第一声）声调不同，意思是“胆怯”。"}, "sentence_index": null, "correct_answer": "切"}, "level_3": {"options": [{"text": "搅", "is_correct": false, "explanation": "语义：“搅”指搅拌，与用小刀把水果分开的意思不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”指擦拭表面，不能与“用小刀……水果”搭配表示切分。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，不能用小刀扔水果来分开。"}, {"text": "切", "is_correct": true, "explanation": "切：用小刀把水果分成块，与句意相合。"}], "explanations": {"搅": "语义：“搅”指搅拌，与用小刀把水果分开的意思不符。", "擦": "搭配：“擦”指擦拭表面，不能与“用小刀……水果”搭配表示切分。", "扔": "语义：“扔”是丢掉，不能用小刀扔水果来分开。", "切": "切：用小刀把水果分成块，与句意相合。"}, "sentence_index": 6, "correct_answer": "切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在花园里切出一个深坑，切了一下午。", "explanation": "这里应该用〈挖〉。挖指用工具掘出凹洞，如挖坑；切是把物体分成几块，不能用来掘坑。"}, {"text": "他用力切床单，切得满头大汗。", "explanation": "这里应该用〈拧〉。拧指用手转动使床单等扭转或挤去水分，如拧床单；切不能这样用。"}, {"text": "他用斧子切树，切了一下午。", "explanation": "这里应该用〈砍〉。砍指用斧子等把树木砍断；切是把东西分成几块，不说“切树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把蛋糕切做了三份。", "corrected_sentence": "妈妈把蛋糕切成了三份。", "error_description": "补语错误：“切做”应改为“切成”。“切成”表示把物体分成若干部分，“切做”不能作结果补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把萝卜切很细。", "corrected_sentence": "她把萝卜切得很细。", "error_description": "程度补语错误：“切很细”应改为“切得很细”，程度补语须用“得”连接动词和形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后果", "is_correct": true, "explanation": "“后果”与“前因”相对，指事情发生之后产生的结果。"}, {"text": "方法", "is_correct": false, "explanation": "“方法”指解决问题的途径，与“前因”没有反义关系。"}, {"text": "地点", "is_correct": false, "explanation": "“地点”指位置场所，与“前因”没有反义关系。"}, {"text": "工具", "is_correct": false, "explanation": "“工具”指用来做事的器具，与“前因”没有反义关系。"}], "correct_answer": "后果", "explanations": {"后果": "“后果”与“前因”相对，指事情发生之后产生的结果。", "方法": "“方法”指解决问题的途径，与“前因”没有反义关系。", "地点": "“地点”指位置场所，与“前因”没有反义关系。", "工具": "“工具”指用来做事的器具，与“前因”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后果", "is_correct": true, "explanation": "“后果”与“前因”相对，指事情发生之后产生的结果。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”指时刻或时长，与“前因”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”指一定时期内的冷热阴晴，与“前因”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”指家具，与“前因”没有反义关系。"}], "correct_answer": "后果", "explanations": {"后果": "“后果”与“前因”相对，指事情发生之后产生的结果。", "时间": "“时间”指时刻或时长，与“前因”没有反义关系。", "天气": "“天气”指一定时期内的冷热阴晴，与“前因”没有反义关系。", "桌子": "“桌子”指家具，与“前因”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前因是一件事发生以前的原因。", "primary_collocate": null, "pronunciation": "qián yīn", "ipa": "tɕʰjɛn˧˥ in˥", "syllable_count": 2, "sentences": [{"text": "这件事的前因，老师不太清楚。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先说说事情的前因，我再帮你想办法。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这件事的前因都告诉了警察。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要明白现在的问题，先要了解它的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场争吵的前因其实很简单。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只听到结果，不知道前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她问了很久，才知道事情的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书先写了故事的前因，再写结果。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每件事都有前因，也有后果。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在调查火灾的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一件事发生以前的原因，常与后果相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前因", "is_correct": true, "explanation": "“前因”指事情发生前的原因，与“老师不太清楚”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，不能指事情的起因。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用于事情。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不能指事情的起因。"}], "explanations": {"前因": "“前因”指事情发生前的原因，与“老师不太清楚”相符。", "价格": "语义：“价格”指商品的钱数，不能指事情的起因。", "身高": "体貌：“身高”指人的身体高矮，不能用于事情。", "颜色": "语义：“颜色”指事物的色彩，不能指事情的起因。"}, "sentence_index": 0, "correct_answer": "前因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部小说的前因是一个悲伤的结局。", "explanation": "这里应该用〈结局〉。前因指事情发生以前的原因，说故事最后的结果要用“结局”。"}, {"text": "这次事故造成的前因很严重。", "explanation": "这里应该用〈后果〉。“造成”后面接结果，“前因”指事情发生前的原因，两者方向相反。"}, {"text": "他买这台电脑的前因很便宜。", "explanation": "这里应该用〈价格〉。前因指事情发生前的原因，说东西便宜与否要用“价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前因", "is_correct": true, "explanation": "“前因”指事情的起因，与“问了很久才知道”的语境相符。"}, {"text": "报酬", "is_correct": false, "explanation": "语义：“报酬”指劳动所得，不是事情的缘由。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”用于物体，不说事情的重量。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体的大小，不用于事情。"}], "explanations": {"前因": "“前因”指事情的起因，与“问了很久才知道”的语境相符。", "报酬": "语义：“报酬”指劳动所得，不是事情的缘由。", "重量": "搭配：“重量”用于物体，不说事情的重量。", "体积": "搭配：“体积”指物体的大小，不用于事情。"}, "sentence_index": 6, "correct_answer": "前因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的前因老师住在北京。", "explanation": "这里应该用〈以前的〉。“前因”指事情的原因，不能用来修饰人。"}, {"text": "这种药的前因很好。", "explanation": "这里应该用〈效果〉。“前因”不能用来评价药的作用，描述药效要用“效果”。"}, {"text": "他的前因非常明确：考上大学。", "explanation": "这里应该用〈目标〉。“前因”指事情发生前的原因，说人的追求和计划要用“目标”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没有弄清楚这次争吵的一只前因。", "corrected_sentence": "我还没有弄清楚这次争吵的前因。", "error_description": "“前因”是抽象名词，不能用“只”计量（“只”用于动物等），应去掉“一只”，说“这次争吵的前因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他查了很久，才弄清楚这件事的一张前因。", "corrected_sentence": "他查了很久，才弄清楚这件事的前因。", "error_description": "“前因”是抽象名词，不能用“张”计量（“张”多用于纸张、桌子等），应去掉“一张”，说“这件事的前因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94112, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后果", "is_correct": true, "explanation": "“后果”与“前因”相对，指事情发生之后产生的结果。"}, {"text": "地图", "is_correct": false, "explanation": "“地图”指表示地理位置的图，与“前因”没有反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "“音乐”指有节奏和旋律的声音艺术，与“前因”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "“花园”指种花草的园子，与“前因”没有反义关系。"}], "correct_answer": "后果", "explanations": {"后果": "“后果”与“前因”相对，指事情发生之后产生的结果。", "地图": "“地图”指表示地理位置的图，与“前因”没有反义关系。", "音乐": "“音乐”指有节奏和旋律的声音艺术，与“前因”没有反义关系。", "花园": "“花园”指种花草的园子，与“前因”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
