INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生之前的起因或缘由。", "primary_collocate": null, "pronunciation": "qián yīn", "ipa": "tɕʰjɛn˧˥ in˥", "syllable_count": 2, "sentences": [{"text": "那次误会的前因是一封信。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你讲讲他比赛迟到的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起事故的前因还没有查清楚。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意提起那件旧事的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友吵架的前因，是一句玩笑话。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问了病人生病的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要解决问题，就得先找出它的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想知道孩子哭的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影开头就讲了这场战争的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲起了这个村子搬家的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事情发生之前的起因或缘由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前因", "is_correct": true, "explanation": "“前因”指事情发生前的起因或缘由，与“那次误会”的语境相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指劳动报酬，与“误会”无关，句子说它是一封信。"}, {"text": "厚度", "is_correct": false, "explanation": "搭配：“厚度”用于物体的厚薄，不说误会的厚度。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或物存在的时间，误会没有年龄，与句中“一封信”不符。"}], "explanations": {"前因": "“前因”指事情发生前的起因或缘由，与“那次误会”的语境相符。", "工资": "语义：“工资”指劳动报酬，与“误会”无关，句子说它是一封信。", "厚度": "搭配：“厚度”用于物体的厚薄，不说误会的厚度。", "年龄": "语义：“年龄”指人或物存在的时间，误会没有年龄，与句中“一封信”不符。"}, "sentence_index": 0, "correct_answer": "前因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在等待比赛的前因。", "explanation": "这里应该用〈结果〉。等待的是事情发生之后的结果，“前因”指发生之前的起因。"}, {"text": "他承担了这次事故的前因。", "explanation": "这里应该用〈后果〉。承担的是事情造成的后果，“前因”不能用于“承担”。"}, {"text": "他很快摆脱了这场争吵的前因。", "explanation": "这里应该用〈后果〉。摆脱的是事情造成的后果，“前因”指发生之前的原因，不能被摆脱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前因", "is_correct": true, "explanation": "“前因”指事情的起因，与“找出它的”后接的对象相符。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”表示快乐的情绪，与“解决问题”的语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的高矮，不能用于问题。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”用于物体，不说问题的重量。"}], "explanations": {"前因": "“前因”指事情的起因，与“找出它的”后接的对象相符。", "欢乐": "语义：“欢乐”表示快乐的情绪，与“解决问题”的语境不符。", "身高": "体貌：“身高”描述人的高矮，不能用于问题。", "重量": "搭配：“重量”用于物体，不说问题的重量。"}, "sentence_index": 6, "correct_answer": "前因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的前因，我们从小一起长大。", "explanation": "这里应该用〈朋友〉。“前因”指事情的起因，不能用来指人；从小一起长大的人应说“朋友”。"}, {"text": "这次手术的前因很好。", "explanation": "这里应该用〈效果〉。“前因”不能用来评价手术的作用，描述效果要用“效果”。"}, {"text": "老人许下了搬家的前因。", "explanation": "这里应该用〈愿望〉。“许下”后接愿望或诺言，“前因”指事情的起因，不能被许下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次争吵的一块前因，我一直没有弄清楚。", "corrected_sentence": "那次争吵的前因，我一直没有弄清楚。", "error_description": "“前因”是抽象名词，不用“块”计量（“块”指成块的东西），去掉“一块”即为“那次争吵的前因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那件旧事的一封前因我记得很清楚。", "corrected_sentence": "那件旧事的前因我记得很清楚。", "error_description": "“前因”是抽象名词，不能用“封”计量（“封”用于信件等），应去掉“一封”，说“那件旧事的前因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
