INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "半年是六个月，就是一年的一半。", "primary_collocate": null, "pronunciation": "bàn nián", "ipa": "pan˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "一年有十二个月，半年是六个月。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作合同只有半年。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打算半年后回国。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋我穿了半年就坏了。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，半年内可以学会这些字。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出差半年，下个月回来。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机用了半年，电池还很好。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们半年见一次面。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半年过去了，他的汉语进步很大。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她存了半年的钱，买了新电脑。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上半年", "label": "复合"}, {"form": "下半年", "label": "复合"}], "register": "中性", "sense_fingerprint": "半年：六个月，一年的一半", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "半年", "is_correct": true, "explanation": "正确：「半年」即六个月，与后句「六个月」所指一致。"}, {"text": "一年", "is_correct": false, "explanation": "语义：前句「一年有十二个月」已说明一年不是六个月，与后句矛盾。"}, {"text": "半个月", "is_correct": false, "explanation": "语义：「半个月」远不足六个月，与后句矛盾。"}, {"text": "一季", "is_correct": false, "explanation": "语义：「一季」是三个月，不是六个月，与后句矛盾。"}], "explanations": {"半年": "正确：「半年」即六个月，与后句「六个月」所指一致。", "一年": "语义：前句「一年有十二个月」已说明一年不是六个月，与后句矛盾。", "半个月": "语义：「半个月」远不足六个月，与后句矛盾。", "一季": "语义：「一季」是三个月，不是六个月，与后句矛盾。"}, "sentence_index": 0, "correct_answer": "半年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋我昨天刚买，穿了半年就坏了。", "explanation": "这里应该用〈半天〉之类的短时段。〈半年〉是六个月，与〈昨天刚买〉的时间矛盾。"}, {"text": "我计划半年前回国。", "explanation": "这里与「计划」矛盾：「半年前」是过去的时间点，不能用于将来的计划，应改为〈半年后〉。"}, {"text": "这双鞋我穿了半年，当天就坏了。", "explanation": "这里应该用〈当天〉。〈半年〉是六个月，与〈当天〉的时间矛盾，两者不能同时说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半年", "is_correct": true, "explanation": "正确：「半年」表示使用的时长，与「用了」搭配，语义完整。"}, {"text": "半秒钟", "is_correct": false, "explanation": "语义：用了半秒钟，电池不可能还很好，与常识不符。"}, {"text": "半晌", "is_correct": false, "explanation": "语义：「半晌」指一小会儿，时间太短，说不出「电池还很好」。"}, {"text": "半生", "is_correct": false, "explanation": "语义：「半生」指人生的一半，不是手机的使用时长。"}], "explanations": {"半年": "正确：「半年」表示使用的时长，与「用了」搭配，语义完整。", "半秒钟": "语义：用了半秒钟，电池不可能还很好，与常识不符。", "半晌": "语义：「半晌」指一小会儿，时间太短，说不出「电池还很好」。", "半生": "语义：「半生」指人生的一半，不是手机的使用时长。"}, "sentence_index": 6, "correct_answer": "半年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她存了半年的钱，从一月一号存到一月十号。", "explanation": "这里〈半年〉是六个月，与〈从一月一号到一月十号〉只有十天矛盾，应该说〈存了十天的钱〉。"}, {"text": "她一秒钟存了半年的钱，买了新电脑。", "explanation": "这里〈半年〉与〈一秒钟〉的时长矛盾，应该用〈几天〉之类的短时段。"}, {"text": "她今天存了半年的钱，买了新电脑。", "explanation": "这里〈今天〉是一天，与〈半年〉的长时段矛盾，应该说〈存了一天的钱〉之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学了一个半年多的汉语。", "corrected_sentence": "我们学了半年多的汉语。", "error_description": "错误在「半年」前加了「一个」。「半年」是时段，不能用「一个」计数；应该说「半年多」或「一年半」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑用得半年，还很好。", "corrected_sentence": "这台电脑用了半年，还很好。", "error_description": "错误在「用」后面用了「得」。「得」要接补语，「用得半年」不成话；应改为「用了半年」，表示已经用过的一段时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
