INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "半个年度，即六个月的时间。", "primary_collocate": null, "pronunciation": "bàn nián", "ipa": "pan˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我在北京住了半年。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门课一共学了半年，从三月到八月。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半年前，他搬到了上海。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子才出生半年，还不会走路。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经半年没见到爷爷了。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司成立半年就赚了钱。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学了半年画画，画得很好。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了半年，那只小狗长大了。", "target_word": "半年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半年的时间不长，也不短。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每半年去一次医院检查身体。", "target_word": "半年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上半年", "label": "复合"}, {"form": "下半年", "label": "复合"}], "register": "中性", "sense_fingerprint": "半年：半个年度，六个月的时间长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "半年", "is_correct": true, "explanation": "正确：「半年」即六个月，作「住了」的时量补语，语义和搭配都合适。"}, {"text": "半秒钟", "is_correct": false, "explanation": "语义：在北京住了半秒钟不可能，时间太短，与居住的语境不符。"}, {"text": "半夜", "is_correct": false, "explanation": "搭配：「住了半夜」只指一夜中的一段，不能表示较长时间的居住。"}, {"text": "半晌", "is_correct": false, "explanation": "语义：「半晌」指一小会儿，时间太短，不能表示在北京居住的时长。"}], "explanations": {"半年": "正确：「半年」即六个月，作「住了」的时量补语，语义和搭配都合适。", "半秒钟": "语义：在北京住了半秒钟不可能，时间太短，与居住的语境不符。", "半夜": "搭配：「住了半夜」只指一夜中的一段，不能表示较长时间的居住。", "半晌": "语义：「半晌」指一小会儿，时间太短，不能表示在北京居住的时长。"}, "sentence_index": 0, "correct_answer": "半年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他半年搬到了上海。", "explanation": "这里应该用〈半年前〉，表示过去的某个时间点。〈半年〉只表示一段时长，不能直接说「半年搬到」。"}, {"text": "我们学了半年，从早上到中午。", "explanation": "这里应该用〈半天〉。〈半年〉是六个月，与「从早上到中午」的短时段矛盾。"}, {"text": "我打算半年前回国。", "explanation": "这里与「打算」矛盾：「半年前」指过去的时间点，不能用于将来的打算，应改为〈半年后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半年", "is_correct": true, "explanation": "正确：「半年」表示学画的时长，与「学了」搭配，语义完整。"}, {"text": "半分钟", "is_correct": false, "explanation": "语义：学半分钟无法画得很好，与后句「画得很好」矛盾。"}, {"text": "半小时", "is_correct": false, "explanation": "语义：只学半小时不可能画得很好，与后句矛盾。"}, {"text": "半刻钟", "is_correct": false, "explanation": "语义：「半刻钟」时间极短，学这么久不可能画得很好。"}], "explanations": {"半年": "正确：「半年」表示学画的时长，与「学了」搭配，语义完整。", "半分钟": "语义：学半分钟无法画得很好，与后句「画得很好」矛盾。", "半小时": "语义：只学半小时不可能画得很好，与后句矛盾。", "半刻钟": "语义：「半刻钟」时间极短，学这么久不可能画得很好。"}, "sentence_index": 6, "correct_answer": "半年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每半年去一次医院，所以每个星期都要去。", "explanation": "这里〈每半年〉是六个月一次，与〈每个星期都要去〉矛盾，应改为〈每星期〉。"}, {"text": "他每半年去一次医院，一年要去十次。", "explanation": "这里〈每半年一次〉一年只有两次，与〈一年十次〉矛盾。"}, {"text": "他今天每半年去一次医院检查身体。", "explanation": "这里〈今天〉是具体的一天，与〈每半年〉的周期矛盾；〈半年〉用错了，应该用〈每天〉之类的周期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在北京住了一个半年多。", "corrected_sentence": "我在北京住了半年多。", "error_description": "错误在「半年」前加了「一个」。「半年」是时段，不能用「一个」计数；应该说「半年多」或「一年半」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学得半年钢琴，弹得很好。", "corrected_sentence": "他学了半年钢琴，弹得很好。", "error_description": "错误在「学」后面用了「得」。「得」后要接补语，「学得半年」不成话；应改为「学了半年」，表示已经完成的一段时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
