INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能够分开、可以被分成几部分的。", "primary_collocate": null, "pronunciation": "kě fēn", "ipa": "kʰɤ˨˩˦ fən˥", "syllable_count": 2, "sentences": [{"text": "这个任务是可分的，可以分成三步做。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱是可分的，可以分给几个人。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇课文是可分的，一共分成四段。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕是可分的，八个人都能吃到。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件工作是可分的，我们三人各做一部分。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是可分的，能分成上下两部分。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地是可分的，可以分给两个孩子。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书是可分的，不用一次买全。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的假期是可分的，可以分两次休。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间是可分的，中间能加一道墙。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可分的", "label": "定语形式"}, {"form": "不可分", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "可分：整体可以被分成几部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94c76b39-0b43-41b7-acc8-e7c4649e2034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可分", "is_correct": true, "explanation": "可分是整体可以被分成几部分，与“可以分成三步做”相符。"}, {"text": "统一", "is_correct": false, "explanation": "语义：“统一”指整体不分，与“分成三步做”矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种、不能细分，与“分成三步”矛盾。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物质，不能用来形容任务。"}], "explanations": {"可分": "可分是整体可以被分成几部分，与“可以分成三步做”相符。", "统一": "语义：“统一”指整体不分，与“分成三步做”矛盾。", "单一": "语义：“单一”指只有一种、不能细分，与“分成三步”矛盾。", "坚硬": "搭配：“坚硬”形容物质，不能用来形容任务。"}, "sentence_index": 0, "correct_answer": "可分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种颜色是可分的，一眼就能看清。", "explanation": "这里应该用〈可分辨〉。可分指整体能被分成几部分；辨认颜色要用〈可分辨〉。"}, {"text": "这件衣服是可分的，可以分三个月付钱。", "explanation": "这里应该用〈可分期〉。可分指整体能被分成几部分；分期付款要用〈可分期〉。"}, {"text": "这两位作者的笔迹是可分的，一看就认得出是谁写的。", "explanation": "这里应该用〈可辨认〉。可分指整体能被分成几部分；认出笔迹是谁的要用〈可辨认〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可分", "is_correct": true, "explanation": "可分是整体可以被分成几部分，与“可以分给两个孩子”相符。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能用来形容土地。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容山、楼等高而直立，用于平整的土地不通。"}, {"text": "密闭", "is_correct": false, "explanation": "语义：“密闭”指封闭不通，与“分给两个孩子”矛盾。"}], "explanations": {"可分": "可分是整体可以被分成几部分，与“可以分给两个孩子”相符。", "清澈": "搭配：“清澈”形容水或眼神，不能用来形容土地。", "高耸": "搭配：“高耸”形容山、楼等高而直立，用于平整的土地不通。", "密闭": "语义：“密闭”指封闭不通，与“分给两个孩子”矛盾。"}, "sentence_index": 6, "correct_answer": "可分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两张照片是可分的，一眼就能看出谁是谁。", "explanation": "这里应该用〈可辨别〉。可分指整体能被分成几部分；看出照片里谁是谁要用〈可辨别〉。"}, {"text": "这个路牌是可分的，远远就能认出来。", "explanation": "这里应该用〈可识别〉。可分指整体能被分成几部分；远处认出路牌要用〈可识别〉。"}, {"text": "这种味道是可分的，一闻就能分辨。", "explanation": "这里应该用〈可分辨〉。可分指整体能被分成几部分；辨别气味要用〈可分辨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份方案是可分地，可以分阶段实施。", "corrected_sentence": "这份方案是可分的，可以分阶段实施。", "error_description": "错误形式是“可分地”，正确形式是“可分的”。“可分”作谓语形容词时后面应用“的”，“地”只修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子是可分地，中间能隔开。", "corrected_sentence": "这间屋子是可分的，中间能隔开。", "error_description": "错误形式是“可分地”，正确形式是“可分的”。“可分”作谓语形容词时后面应用“的”；“地”只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
