INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同年是同一年。", "primary_collocate": null, "pronunciation": "tóng nián", "ipa": "tʰʊŋ˧˥ niɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他去年毕业，同年结婚。", "target_word": "同年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他三月搬家，同年九月结婚。", "target_word": "同年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他前年大学毕业，同年找到了工作。", "target_word": "同年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店三年前开业，同年就有了名气。", "target_word": "同年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥去年开始修，同年年底就修好了。", "target_word": "同年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟前年上大学，同年我也搬到了新家。", "target_word": "同年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他那年考上了大学，同年父母也搬来了北京。", "target_word": "同年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司五年前成立，同年就在上海开了第一家店。", "target_word": "同年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她前年在北京学中文，同年又去了日本。", "target_word": "同年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校十年前建成，同年秋天迎来了第一批学生。", "target_word": "同年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：同一年，指前文所说的那一年（同年结婚、同年开业）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同岁", "is_correct": false, "explanation": "语义：“同岁”指年龄相同，是谓语性词，不能放在动词前表示时间，“同岁结婚”说不通。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指人的岁数，不是时间状语，“年纪结婚”不成句。"}, {"text": "年级", "is_correct": false, "explanation": "语义：“年级”指学校的级别，不表示时间，“年级结婚”不成句。"}, {"text": "同年", "is_correct": true, "explanation": "“同年”指与前文所说的同一年，正好承接“去年毕业”。"}], "explanations": {"同岁": "语义：“同岁”指年龄相同，是谓语性词，不能放在动词前表示时间，“同岁结婚”说不通。", "年纪": "语义：“年纪”指人的岁数，不是时间状语，“年纪结婚”不成句。", "年级": "语义：“年级”指学校的级别，不表示时间，“年级结婚”不成句。", "同年": "“同年”指与前文所说的同一年，正好承接“去年毕业”。"}, "sentence_index": 0, "correct_answer": "同年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年毕业，同年后天结婚了。", "explanation": "这里的“同年”指前文所说的同一年，不能与“后天”这样指向近期未来的时间并用，时间相互矛盾，这种说法不成立。"}, {"text": "他去年毕业，同年三年后结婚。", "explanation": "这里的“同年”指前文所说的同一年，不能与“三年后”这样指向另一时间的词并用，时间相互矛盾；表示之后的时间应说〈后来〉，而不是〈同年〉。"}, {"text": "他去年毕业，同年明天结婚了。", "explanation": "这里的“同年”指前文所说的同一年，不能与“明天”这样指向未来的时间并用，时间相互矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人的岁数，不是时间状语，“年龄父母也搬来了北京”不成句。"}, {"text": "周年", "is_correct": false, "explanation": "语义：“周年”指满一年的纪念，要和数字连用，不能单独承接“那年”作时间状语。"}, {"text": "年糕", "is_correct": false, "explanation": "语义：“年糕”是一种食物，不表示时间，放在这里句子不通。"}, {"text": "同年", "is_correct": true, "explanation": "“同年”指与前文所说的同一年，承接“那年考上了大学”。"}], "explanations": {"年龄": "语义：“年龄”指人的岁数，不是时间状语，“年龄父母也搬来了北京”不成句。", "周年": "语义：“周年”指满一年的纪念，要和数字连用，不能单独承接“那年”作时间状语。", "年糕": "语义：“年糕”是一种食物，不表示时间，放在这里句子不通。", "同年": "“同年”指与前文所说的同一年，承接“那年考上了大学”。"}, "sentence_index": 6, "correct_answer": "同年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校十年前建成，同年十年后又扩建了一次。", "explanation": "这里的“同年”指前文所说的同一年，不能与“十年后”这样指向另一时间的词并用，时间相互矛盾；表示之后的时间应说〈后来〉。"}, {"text": "学校十年前建成，同年下周迎来了第一批学生。", "explanation": "这里的“同年”指前文所说的同一年，不能与“下周”这样指向近期未来的时间并用，时间相互矛盾。"}, {"text": "学校十年前建成，同年后年迎来了第一批学生。", "explanation": "这里的“同年”指前文所说的同一年，不能与“后年”这样指向其他年份的时间并用，时间相互矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他前年考上大学，同年的搬到了北京。", "corrected_sentence": "他前年考上大学，同年搬到了北京。", "error_description": "错误：“同年”作时间状语，后面不能加“的”。“同年的搬到”结构不通，应直接说“同年搬到了北京”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她去年生了孩子，很同年换了工作。", "corrected_sentence": "她去年生了孩子，同年换了工作。", "error_description": "错误：“同年”是指前文所说同一年的时间词，不能被“很”修饰。“很同年”不成立，应去掉“很”，即“同年换了工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94123, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软弱", "is_correct": true, "explanation": "反义：“软弱”与“坚强”相对，指意志不足、不能抵抗困难。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌美好，与“坚强”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑反应快，与“坚强”没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地温和、待人友好，与“坚强”没有反义关系。"}], "correct_answer": "软弱", "explanations": {"软弱": "反义：“软弱”与“坚强”相对，指意志不足、不能抵抗困难。", "漂亮": "“漂亮”形容外貌美好，与“坚强”没有反义关系。", "聪明": "“聪明”指头脑反应快，与“坚强”没有反义关系。", "善良": "“善良”指心地温和、待人友好，与“坚强”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
