INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94123, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坚强是遇到难事不害怕，也不放弃。", "primary_collocate": null, "pronunciation": "jiān qiáng", "ipa": "tɕjɛn˥ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她很坚强，再难也不哭。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生病了，但她一直很坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遇到困难时，总是很坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要坚强一点，慢慢会好的。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩虽然很小，却很坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸走后，他变得很坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摔倒了，他自己站起来，真坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试失利后，他很坚强，马上开始复习。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，他没哭，表现得很坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活很难，但她从不放弃，真坚强。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更坚强", "label": "比较"}, {"form": "坚强不屈", "label": "成语"}, {"form": "堅強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到难事不怕、不放弃的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚强", "is_correct": true, "explanation": "“坚强”指遇到难事不害怕、不放弃，与“再难也不哭”相合。"}, {"text": "软弱", "is_correct": false, "explanation": "语义：“软弱”与“再难也不哭”的坚韧态度相反，句子不通。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”指胆小、不敢面对，与“再难也不哭”的态度相反。"}, {"text": "清秀", "is_correct": false, "explanation": "语义：“清秀”形容相貌，不能说明她面对困难不哭的态度。"}], "explanations": {"坚强": "“坚强”指遇到难事不害怕、不放弃，与“再难也不哭”相合。", "软弱": "语义：“软弱”与“再难也不哭”的坚韧态度相反，句子不通。", "懦弱": "语义：“懦弱”指胆小、不敢面对，与“再难也不哭”的态度相反。", "清秀": "语义：“清秀”形容相貌，不能说明她面对困难不哭的态度。"}, "sentence_index": 0, "correct_answer": "坚强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很坚强，用锤子砸了几次都没碎。", "explanation": "这里应该用〈坚硬〉。坚强形容人的意志，石头等物体的硬度要说坚硬。"}, {"text": "他的声音很坚强，全班都听得见。", "explanation": "这里应该用〈洪亮〉。坚强形容意志，声音大而清楚要说洪亮。"}, {"text": "他坚强地去超市买了一瓶酱油。", "explanation": "这里没有困难需要克服，坚强无从说起，应改为“他去超市买了一瓶酱油”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚强", "is_correct": true, "explanation": "“坚强”与“自己站起来”的表现相合，符合句意。"}, {"text": "柔弱", "is_correct": false, "explanation": "语义：“柔弱”与“自己站起来”的表现相反，句子自相矛盾。"}, {"text": "怯懦", "is_correct": false, "explanation": "语义：“怯懦”指胆小、不敢行动，与“自己站起来”相反。"}, {"text": "娇嫩", "is_correct": false, "explanation": "搭配：“娇嫩”多形容皮肤、花草，不能用来评价人的意志。"}], "explanations": {"坚强": "“坚强”与“自己站起来”的表现相合，符合句意。", "柔弱": "语义：“柔弱”与“自己站起来”的表现相反，句子自相矛盾。", "怯懦": "语义：“怯懦”指胆小、不敢行动，与“自己站起来”相反。", "娇嫩": "搭配：“娇嫩”多形容皮肤、花草，不能用来评价人的意志。"}, "sentence_index": 6, "correct_answer": "坚强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她长得很坚强，个子高高的，肩膀也宽。", "explanation": "这里应该用〈健壮〉。坚强形容意志，描写人的体格要说健壮。"}, {"text": "这根绳子很坚强，能吊起一吨重的货物。", "explanation": "这里应该用〈坚韧〉。坚强用于形容人的意志，描写绳子等物体的韧性应说坚韧。"}, {"text": "他坚强地解释了这个问题，大家都听懂了。", "explanation": "这里应该用〈清楚〉。坚强指面对困难不屈服，讲解的清晰度要说清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一个坚强地母亲，独自养大了三个孩子。", "corrected_sentence": "她是一个坚强的母亲，独自养大了三个孩子。", "error_description": "错误在“坚强”修饰名词时用了“地”：“地”修饰动词，修饰名词应用“的”，应说“坚强的母亲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一次次跌倒，又一次次坚强得站起来。", "corrected_sentence": "他一次次跌倒，又一次次坚强地站起来。", "error_description": "错误在“坚强”后的“得”：作状语修饰动词“站起来”时要用“地”，“得”用于补语，应说“坚强地站起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
