INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94124, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意志强，不怕困难，不易动摇。", "primary_collocate": null, "pronunciation": "jiān qiáng", "ipa": "tɕjɛn˥ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他意志坚强，什么困难都不怕。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚强的意志帮他走完了长路。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人性格坚强，从不低头。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们坚强地守着边防。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一颗坚强的心，不会动摇。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再大的风雨，也打不倒坚强的人。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员坚强的意志让大家佩服。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的意志非常坚强，没人能改变他。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用坚强的毅力完成了训练。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病了三年，她始终坚强地生活着。", "target_word": "坚强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更坚强", "label": "比较"}, {"form": "坚强不屈", "label": "成语"}, {"form": "堅強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "意志强、不易动摇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad04ac1d-4e8d-4c76-a5b4-89d4d504d5ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚强", "is_correct": true, "explanation": "“坚强”指意志强、不怕困难，与“什么困难都不怕”相合。"}, {"text": "软弱", "is_correct": false, "explanation": "语义：“软弱”与“什么困难都不怕”的意思相反，句子不通。"}, {"text": "薄弱", "is_correct": false, "explanation": "语义：“薄弱”指力量不足，与“什么困难都不怕”矛盾。"}, {"text": "清秀", "is_correct": false, "explanation": "搭配：“清秀”形容相貌，不能修饰“意志”。"}], "explanations": {"坚强": "“坚强”指意志强、不怕困难，与“什么困难都不怕”相合。", "软弱": "语义：“软弱”与“什么困难都不怕”的意思相反，句子不通。", "薄弱": "语义：“薄弱”指力量不足，与“什么困难都不怕”矛盾。", "清秀": "搭配：“清秀”形容相貌，不能修饰“意志”。"}, "sentence_index": 0, "correct_answer": "坚强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老城墙很坚强，几百年来经受住了风雨。", "explanation": "这里应该用〈坚固〉。坚强形容人的意志，城墙等建筑的牢固要说坚固。"}, {"text": "他的双手很坚强，能轻松掰断一根铁棍。", "explanation": "这里应该用〈有力〉。坚强形容意志，手的力量要说有力。"}, {"text": "他坚强地吃完了一大块蛋糕。", "explanation": "这里没有困难需要克服，坚强无从说起，应改为“他高兴地吃完了一大块蛋糕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚强", "is_correct": true, "explanation": "“坚强”指意志强、不易动摇，与“运动员的意志让大家佩服”相合。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易被打垮，与令人佩服的意志相反。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”指胆小、意志不坚定，与令人佩服的意志矛盾。"}, {"text": "娇嫩", "is_correct": false, "explanation": "搭配：“娇嫩”多形容皮肤、花草，不能修饰“意志”。"}], "explanations": {"坚强": "“坚强”指意志强、不易动摇，与“运动员的意志让大家佩服”相合。", "脆弱": "语义：“脆弱”指容易被打垮，与令人佩服的意志相反。", "懦弱": "语义：“懦弱”指胆小、意志不坚定，与令人佩服的意志矛盾。", "娇嫩": "搭配：“娇嫩”多形容皮肤、花草，不能修饰“意志”。"}, "sentence_index": 6, "correct_answer": "坚强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种金属很坚强，不容易变形。", "explanation": "这里应该用〈坚韧〉。坚强用于形容人的意志，描写金属、绳子等物体的韧性应说坚韧。"}, {"text": "他坚强地否认了这个说法。", "explanation": "这里应该用〈坚决〉。否认、拒绝等态度要说坚决，坚强指意志在困难中不屈。"}, {"text": "他坚强地把这道简单的题算错了三次。", "explanation": "这里没有困难需要克服，坚强无从说起，应说“他把这道简单的题算错了三次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一颗坚强地心，从不轻易动摇。", "corrected_sentence": "他有一颗坚强的心，从不轻易动摇。", "error_description": "错误在“坚强”修饰名词“心”时用了“地”：修饰名词应用“的”，应说“坚强的心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她坚强得忍受着疼痛，一声也没喊。", "corrected_sentence": "她坚强地忍受着疼痛，一声也没喊。", "error_description": "错误在“坚强”后的“得”：作状语修饰动词“忍受”时要用“地”，“得”用于补语，应说“坚强地忍受”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6c47a85-5320-4f94-96dc-8e7ed6bfc8e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在与外在为反义，指内部、看不见的。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "漫长", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "迟缓", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}], "correct_answer": "内在", "explanations": {"内在": "内在与外在为反义，指内部、看不见的。", "陡峭": "与“外在”没有反义关系，不能作其反义词。", "漫长": "与“外在”没有反义关系，不能作其反义词。", "迟缓": "与“外在”没有反义关系，不能作其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在与外在为反义，指内部、看不见的。"}, {"text": "清脆", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "嘹亮", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}], "correct_answer": "内在", "explanations": {"内在": "内在与外在为反义，指内部、看不见的。", "清脆": "与“外在”没有反义关系，不能作其反义词。", "嘹亮": "与“外在”没有反义关系，不能作其反义词。", "寒冷": "与“外在”没有反义关系，不能作其反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "外在是在外面的，能看得见的。", "primary_collocate": null, "pronunciation": "wài zài", "ipa": "wai˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "他很看重自己的外在形象。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在美很快会变，内在美更长久。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外在的样子很冷淡，心里却很热。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要只看外在的样子。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在的打扮可以改变，性格很难改。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，外在的整洁很重要。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店外在的样子很旧，里面却很漂亮。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很在意外在的美。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在的变化大家都看得见。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的外在形象会给人好印象。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外在美", "label": "复合"}], "register": "中性", "sense_fingerprint": "表面可见的，外表的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”指看得见的外表，与“形象”搭配，表示外表形象。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容坡度，不能修饰“形象”。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：“漫长”形容时间或距离，不能修饰“形象”。"}, {"text": "迟缓", "is_correct": false, "explanation": "语义：“迟缓”形容动作速度，与“形象”的语义不合。"}], "explanations": {"外在": "“外在”指看得见的外表，与“形象”搭配，表示外表形象。", "陡峭": "搭配：“陡峭”形容坡度，不能修饰“形象”。", "漫长": "搭配：“漫长”形容时间或距离，不能修饰“形象”。", "迟缓": "语义：“迟缓”形容动作速度，与“形象”的语义不合。"}, "sentence_index": 0, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的外在运算很快。", "explanation": "这里不应该用〈外在〉，应删去。“外在”指看得见的外表，运算速度属于内部性能，不能说“外在运算”。"}, {"text": "这篇文章的外在很有深度。", "explanation": "这里应该用〈内容〉。“外在”指外表，文章的深度属于内容。"}, {"text": "这次考试的外在成绩很好。", "explanation": "这里不应该用〈外在〉，应删去。“外在”指可见的外表，考试成绩不是外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”指店面的外表，与“里面”相对，符合语境。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来描述样子。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，与“样子”的语义不合。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容味道或睡眠，不能用来描述店面的样子。"}], "explanations": {"外在": "“外在”指店面的外表，与“里面”相对，符合语境。", "清脆": "语义：“清脆”形容声音，不能用来描述样子。", "嘹亮": "语义：“嘹亮”形容声音，与“样子”的语义不合。", "香甜": "搭配：“香甜”形容味道或睡眠，不能用来描述店面的样子。"}, "sentence_index": 6, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好的外在学问会给人好印象。", "explanation": "这里应该用〈内在〉。“外在”指看得见的外表，学问是人内在的修养，不能说“外在学问”。"}, {"text": "这次演讲的外在很有感染力。", "explanation": "这里应该用〈内容〉。感染力来自内容，不属于外在的外表。"}, {"text": "他的外在心情很好。", "explanation": "这里应该用〈内心〉。“外在”指看得见的外表，心情属于内心的感受，不能说“外在心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很在意自己的外在了打扮。", "corrected_sentence": "他很在意自己的外在打扮。", "error_description": "错误：“外在”是修饰“打扮”的形容词，后面不能加“了”。正确：“外在打扮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车外在的样子很外在新。", "corrected_sentence": "这辆车外在的样子很新。", "error_description": "错误：“外在”只修饰名词，不能修饰形容词“新”，多出的“外在”应删去。正确：“这辆车外在的样子很新。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在与外在为反义，指事物内部、固有的。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "热闹", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}], "correct_answer": "内在", "explanations": {"内在": "内在与外在为反义，指事物内部、固有的。", "漂亮": "与“外在”没有反义关系，不能作其反义词。", "热闹": "与“外在”没有反义关系，不能作其反义词。", "整齐": "与“外在”没有反义关系，不能作其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在与外在为反义，指事物内部、固有的。"}, {"text": "鲜艳", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "慷慨", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}], "correct_answer": "内在", "explanations": {"内在": "内在与外在为反义，指事物内部、固有的。", "鲜艳": "与“外在”没有反义关系，不能作其反义词。", "慷慨": "与“外在”没有反义关系，不能作其反义词。", "粗糙": "与“外在”没有反义关系，不能作其反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "存在于事物外部的；非本身固有的。", "primary_collocate": null, "pronunciation": "wài zài", "ipa": "wai˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "成功不只靠外在条件。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在的压力有时会变成动力。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的外在原因很多。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的变化受外在环境影响。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿接受外在的评价。", "target_word": "外在", "complexity_tier": "T3", "furigana": "tā bù yuàn jiē shòu wài zài de píng jià.", "sentence_source": "generated"}, {"text": "内在的想法比外在的条件更重要。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在因素和内在原因都要考虑。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败主要是外在原因。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要让外在的变化影响你的心情。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司遇到了外在的困难。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外在因素", "label": "复合"}], "register": "中性", "sense_fingerprint": "来自事物外部的，非自身固有的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”指事物外部的条件，与“不只靠”的语境相合。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外表，不能修饰“条件”。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面喧闹，与“成功靠条件”的语义不搭。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”指排列有序，不能用来说明成功的条件。"}], "explanations": {"外在": "“外在”指事物外部的条件，与“不只靠”的语境相合。", "漂亮": "搭配：“漂亮”形容外表，不能修饰“条件”。", "热闹": "语义：“热闹”指场面喧闹，与“成功靠条件”的语义不搭。", "整齐": "语义：“整齐”指排列有序，不能用来说明成功的条件。"}, "sentence_index": 0, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的外在硬度很高。", "explanation": "这里应该用〈内在〉。“外在”指外部的、非固有的，硬度是石头自身固有的属性，不能说“外在硬度”。"}, {"text": "他的外在本领很强。", "explanation": "这里应该用〈能力〉。“外在”指非固有的外部因素，本领是人自身固有的能力，不能说“外在本领”。"}, {"text": "他天生的外在性格很开朗。", "explanation": "这里应该用〈内在〉。“外在”指来自外部、非自身固有的，天生的性格是自身固有的，不能说“外在性格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”修饰“因素”，指外部的、非固有的因素，与“内在原因”相对。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能修饰“因素”。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容人的品格，不能用来形容因素。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容质地，不能修饰“因素”。"}], "explanations": {"外在": "“外在”修饰“因素”，指外部的、非固有的因素，与“内在原因”相对。", "鲜艳": "搭配：“鲜艳”形容颜色，不能修饰“因素”。", "慷慨": "语义：“慷慨”形容人的品格，不能用来形容因素。", "粗糙": "搭配：“粗糙”形容质地，不能修饰“因素”。"}, "sentence_index": 6, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这头牛的外在力气很大。", "explanation": "这里应该用〈体力〉。“外在”指非固有的外部因素，力气是牛自身的体力，不能说“外在力气”。"}, {"text": "这篇文章的外在很有深度。", "explanation": "这里应该用〈内容〉。“外在”指非固有的外部因素，文章的深度属于内容，不属于外在。"}, {"text": "这首歌的外在很动听。", "explanation": "这里应该用〈旋律〉。“外在”指事物外部的、非固有的，歌曲好听与否取决于旋律，不能用“外在”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的外在条件比我外在很多。", "corrected_sentence": "他的外在条件比我好很多。", "error_description": "词性误用：“外在”是属性词，只修饰名词，不能作“比”字句的谓语，此处应用“好”。正确：“他的外在条件比我好很多。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛遇到了外在地困难。", "corrected_sentence": "这次比赛遇到了外在的困难。", "error_description": "的/地误用：“外在”修饰名词“困难”，应用“的”，不能用“地”。正确：“外在的困难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
