INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94127, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大干是花很大的力气去做事。", "primary_collocate": null, "pronunciation": "dà gàn", "ipa": "/ta˥˩ kan˥˩/", "syllable_count": 2, "sentences": [{"text": "他们打算大干一场。", "target_word": "大干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们大干一天，把家收拾好。", "target_word": "大干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年公司要大干，不能再慢了。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想赚更多钱，我得大干几年。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们大干了一下午，教室很干净。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一回国，就想大干一场。", "target_word": "大干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人们在工地上大干。", "target_word": "大干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要大干一个夏天，把书写完。", "target_word": "大干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只说不做，快来大干吧。", "target_word": "大干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家大干了一个月，终于完成了。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大干了", "label": "体标（了）"}, {"form": "大干过", "label": "体标（过）"}, {"form": "大干快上", "label": "复合"}], "register": "口语", "sense_fingerprint": "花很大的力气、集中精力去做事，如大干一场、大干几年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病", "is_correct": false, "explanation": "语义：“病”不是人主动去做的事，“打算病一场”不通。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌倒，不能作为“打算”要去做的事。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”是离合词，不能直接接“一场”，“打算洗澡一场”不通。"}, {"text": "大干", "is_correct": true, "explanation": "大干：花很大力气去做事，与“打算……一场”相合。"}], "explanations": {"病": "语义：“病”不是人主动去做的事，“打算病一场”不通。", "摔": "语义：“摔”指跌倒，不能作为“打算”要去做的事。", "洗澡": "搭配：“洗澡”是离合词，不能直接接“一场”，“打算洗澡一场”不通。", "大干": "大干：花很大力气去做事，与“打算……一场”相合。"}, "sentence_index": 0, "correct_answer": "大干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们在家大干了一天，一直躺在沙发上。", "explanation": "这里应该用〈休息〉。大干指花很大力气、集中精力做事，与“一直躺在沙发上”相矛盾。"}, {"text": "孩子们在河边大干，一整天都躺着晒太阳。", "explanation": "这里应该用〈晒太阳〉。大干指花很大力气做事，与整天躺着的懒散状态不符。"}, {"text": "他在树下大干，一会儿就睡着了。", "explanation": "这里应该用〈打盹〉。大干指花很大力气做事，不能形容在树下打盹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩耍", "is_correct": false, "explanation": "语义：“玩耍”与“在工地上”的劳动语境不符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是悠闲走走，与“大干”的干劲相反。"}, {"text": "嬉戏", "is_correct": false, "explanation": "语域：“嬉戏”带文学色彩，与口语叙述不协调，且语义与工地上的劳动不符。"}, {"text": "大干", "is_correct": true, "explanation": "大干：花很大力气干活，与“工人们在工地上”相合。"}], "explanations": {"玩耍": "语义：“玩耍”与“在工地上”的劳动语境不符。", "散步": "语义：“散步”是悠闲走走，与“大干”的干劲相反。", "嬉戏": "语域：“嬉戏”带文学色彩，与口语叙述不协调，且语义与工地上的劳动不符。", "大干": "大干：花很大力气干活，与“工人们在工地上”相合。"}, "sentence_index": 6, "correct_answer": "大干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在街上大干，不知道在做什么。", "explanation": "这里应该用〈游荡〉。大干指花很大力气、集中精力做事，不能形容无目的地闲逛。"}, {"text": "他每天中午大干一觉，醒来精神很好。", "explanation": "这里应该用〈睡〉。大干指花很大力气做事，不能用来形容睡觉。"}, {"text": "他坐在窗前大干，发了一会儿呆。", "explanation": "这里应该用〈发呆〉。大干指花很大力气做事，不能形容坐着发呆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们曾经大干着一场。", "corrected_sentence": "我们曾经大干过一场。", "error_description": "体标错误：表示曾经做过用“过”，不能用“着”（“着”表示动作持续）。应说“大干过一场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们大干着了一个月，房子终于盖好了。", "corrected_sentence": "他们大干了一个月，房子终于盖好了。", "error_description": "体标错误：“大干”后不能接“着了”，只用“了”即可，应说“大干了一个月”（“着了”多见于“睡着了”一类结果补语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
