INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94128, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用很大的气力或拿出很大的干劲去做。", "primary_collocate": null, "pronunciation": "dà gàn", "ipa": "/ta˥˩ kan˥˩/", "syllable_count": 2, "sentences": [{"text": "大家要大干一场，把房子盖好。", "target_word": "大干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赶时间，工人们大干了三天。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月我们要大干一番。", "target_word": "大干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天来了，农民们开始大干。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他决定在公司大干一场。", "target_word": "大干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们大干一个星期，一定能完成。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天我们要大干，你早点休息。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们大干了一个冬天，修好了路。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想早点完工，就得大干。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该大干一番事业。", "target_word": "大干", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大干了", "label": "体标（了）"}, {"form": "大干过", "label": "体标（过）"}, {"form": "大干快上", "label": "复合"}], "register": "口语", "sense_fingerprint": "拿出很大的干劲和气力去做某件事，常说大干一场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大哭", "is_correct": false, "explanation": "语义：“大哭”与“把房子盖好”的干活语境不符。"}, {"text": "大闹", "is_correct": false, "explanation": "语义：“大闹”指吵闹，与“把房子盖好”的目标不相合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能表示为某件事投入很大干劲，与“把房子盖好”的目的相反。"}, {"text": "大干", "is_correct": true, "explanation": "大干：拿出很大干劲去做，与“把房子盖好”相合。"}], "explanations": {"大哭": "语义：“大哭”与“把房子盖好”的干活语境不符。", "大闹": "语义：“大闹”指吵闹，与“把房子盖好”的目标不相合。", "睡": "配价：“睡”是不及物动词，不能表示为某件事投入很大干劲，与“把房子盖好”的目的相反。", "大干": "大干：拿出很大干劲去做，与“把房子盖好”相合。"}, "sentence_index": 0, "correct_answer": "大干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在床上大干，一整天都没起来。", "explanation": "这里应该用〈躺〉。大干指拿出很大干劲去做事，不能形容一整天卧床不起。"}, {"text": "孩子们在操场上大干，一直蹲在角落里一动不动。", "explanation": "这里应该用〈发呆〉。大干指拿出很大干劲去做事，与“一动不动”相矛盾。"}, {"text": "他在沙发上大干，一会儿就睡着了。", "explanation": "这里应该用〈打盹〉。大干指拿出很大干劲去做事，不能形容在沙发上打盹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”不是可以计划去做的事，与“明天我们要……”的句意不符。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”表示忧虑，不是主动去做事，与“明天我们要……”的计划不符。"}, {"text": "呆坐", "is_correct": false, "explanation": "语义：“呆坐”是呆着不动，与“明天我们要……”的计划不符。"}, {"text": "大干", "is_correct": true, "explanation": "大干：拿出很大干劲去做，与“明天我们要……”的计划相合，也解释了为何要早点休息。"}], "explanations": {"哭泣": "语义：“哭泣”不是可以计划去做的事，与“明天我们要……”的句意不符。", "发愁": "语义：“发愁”表示忧虑，不是主动去做事，与“明天我们要……”的计划不符。", "呆坐": "语义：“呆坐”是呆着不动，与“明天我们要……”的计划不符。", "大干": "大干：拿出很大干劲去做，与“明天我们要……”的计划相合，也解释了为何要早点休息。"}, "sentence_index": 6, "correct_answer": "大干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快就把钱大干光了。", "explanation": "这里应该用〈挥霍〉。大干指拿出很大干劲去做事，不能指随便花钱。"}, {"text": "我们在咖啡馆里大干，聊了一下午天。", "explanation": "这里应该用〈聊天〉。大干指拿出很大干劲做事，不能用来形容闲聊。"}, {"text": "她站在舞台上大干，一言不发，只是发抖。", "explanation": "这里应该用〈发抖〉。大干指拿出很大干劲去做事，与“一言不发、只是发抖”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们决定大干一个，把仓库整理好。", "corrected_sentence": "他们决定大干一场，把仓库整理好。", "error_description": "量词错误：“大干”后不能接“个”，应接“场”“番”等（如“大干一场”“大干一番”），不能用“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把大干一场，把仓库整理好了。", "corrected_sentence": "我们大干一场，把仓库整理好了。", "error_description": "“把”误加：“大干”是不及物动词，不能放在“把”的后面；应说“我们大干一场”，“把”只用于后面的“把仓库整理好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小环境", "is_correct": true, "explanation": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。"}, {"text": "历史", "is_correct": false, "explanation": "历史指过去发生的事情，与大环境没有相对关系。"}, {"text": "内心", "is_correct": false, "explanation": "内心指人的心里，与大环境没有相对关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气指一时的冷暖晴雨，与大环境不是相对的词。"}], "correct_answer": "小环境", "explanations": {"小环境": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。", "历史": "历史指过去发生的事情，与大环境没有相对关系。", "内心": "内心指人的心里，与大环境没有相对关系。", "天气": "天气指一时的冷暖晴雨，与大环境不是相对的词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小环境", "is_correct": true, "explanation": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。"}, {"text": "工资", "is_correct": false, "explanation": "工资指劳动报酬，与大环境没有相对关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是房屋的构件，与大环境没有相对关系。"}, {"text": "数学", "is_correct": false, "explanation": "数学是一门学科，与大环境没有相对关系。"}], "correct_answer": "小环境", "explanations": {"小环境": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。", "工资": "工资指劳动报酬，与大环境没有相对关系。", "窗户": "窗户是房屋的构件，与大环境没有相对关系。", "数学": "数学是一门学科，与大环境没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大环境是我们周围很大的一片情况。", "primary_collocate": null, "pronunciation": "dà huán jìng", "ipa": "ta˥˩ xuan˧˥ tɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "现在的大环境对学生来说不太好。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年大环境不好，生意不容易做。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们很难改变大环境，只能改变自己。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境好了，大家的生活也会更好。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说工作难找，是因为大环境。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这样的大环境里，大家都很努力。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境不太好，所以我们要多存一点钱。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了工作，也是考虑到大环境才决定的。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司在大环境不好时，很容易遇到问题。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境变好以后，这个城市的生意又多起来了。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小环境", "label": "复合（相对的词）"}], "register": "中性", "sense_fingerprint": "大环境：我们周围整体的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指整体的社会与经济情况，说它“对学生来说不太好”符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，与“对学生来说不太好”的整体情况无关。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”只用来形容人的外貌，不能用来说整体情况。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪指人的岁数，不能用来表示学生所处的整体情况。"}], "explanations": {"大环境": "大环境指整体的社会与经济情况，说它“对学生来说不太好”符合语境。", "身高": "语义：身高指身体的高矮，与“对学生来说不太好”的整体情况无关。", "长相": "体貌：“长相”只用来形容人的外貌，不能用来说整体情况。", "年纪": "语义：年纪指人的岁数，不能用来表示学生所处的整体情况。"}, "sentence_index": 0, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的大环境很好。", "explanation": "这里应该用〈味道〉。大环境指社会整体条件，不是菜的口味，不能用来评价一道菜。"}, {"text": "他的大环境很高。", "explanation": "这里应该用〈个子〉。大环境不是人的身体，没有高矮，不能这样描述一个人。"}, {"text": "这首歌的大环境很好听。", "explanation": "这里应该用〈旋律〉。大环境指社会整体条件，不是歌曲的旋律，不能用来评价歌好不好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指整体的社会与经济形势，“不太好”说明经济环境不佳，所以要多存钱。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指一时的冷暖晴雨，与“要多存一点钱”的经济原因无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说“大”或“小”，不说“好”或“不好”。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，不能作为影响存钱的整体条件。"}], "explanations": {"大环境": "大环境指整体的社会与经济形势，“不太好”说明经济环境不佳，所以要多存钱。", "天气": "语义：天气指一时的冷暖晴雨，与“要多存一点钱”的经济原因无关。", "年龄": "搭配：“年龄”一般说“大”或“小”，不说“好”或“不好”。", "字体": "语义：字体是文字的样式，不能作为影响存钱的整体条件。"}, "sentence_index": 6, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上的大环境很鲜艳。", "explanation": "这里应该用〈颜色〉。大环境指社会整体条件，不能用来形容墙面的颜色。"}, {"text": "电视的大环境很大。", "explanation": "这里应该用〈音量〉。大环境指整体背景情况，不能用来形容电视声音的大小。"}, {"text": "他的大环境很胖。", "explanation": "这里应该用〈体型〉。大环境不是人的身体，不能用“很胖”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张大环境对学生的影响越来越大。", "corrected_sentence": "这个大环境对学生的影响越来越大。", "error_description": "量词错误：“大环境”应搭配量词“个”，说“这个大环境”；“张”用于平面的东西，不能用于大环境这样抽象的情况。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年大环境的对店铺很不利，很多人都不敢开店了。", "corrected_sentence": "这几年大环境对店铺很不利，很多人都不敢开店了。", "error_description": "“大环境”后多加了“的”，“大环境的对店铺很不利”不成句，应去掉“的”，说“大环境对店铺很不利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
