INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某个人或事物产生影响的广阔社会背景或整体条件。", "primary_collocate": null, "pronunciation": "dà huán jìng", "ipa": "ta˥˩ xuan˧˥ tɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "大环境不好，很多公司都在减少人员。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在现在的大环境下，找工作不容易。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成功，离不开当时好的大环境。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境变了，我们的生活方式也要变。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受大环境的影响，今年的工资没有涨。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济大环境不好的时候，人们花钱会更小心。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司再努力，也很难改变整个行业的大环境。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的大环境能给年轻人更多的机会。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然大环境很难，但是他没有放弃过。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大环境对每个人都有影响，不只是公司。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小环境", "label": "复合（相对的词）"}], "register": "中性", "sense_fingerprint": "大环境：影响个人或行业的整体社会背景与条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指影响各行各业的整体社会与经济背景，与“很多公司都在减少人员”的宏观原因相符。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，不能说明很多公司减少人员的原因。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的外貌，不能用来形容整个社会环境。"}, {"text": "身体", "is_correct": false, "explanation": "语义：“身体”指人的健康状况，与公司减少人员的原因无关。"}], "explanations": {"大环境": "大环境指影响各行各业的整体社会与经济背景，与“很多公司都在减少人员”的宏观原因相符。", "字体": "语义：字体是文字的样式，不能说明很多公司减少人员的原因。", "长相": "体貌：“长相”指人的外貌，不能用来形容整个社会环境。", "身体": "语义：“身体”指人的健康状况，与公司减少人员的原因无关。"}, "sentence_index": 0, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议室里的大环境很轻松。", "explanation": "这里应该用〈气氛〉。大环境指影响行业或个人的整体社会条件，不能用来形容会议室里的轻松氛围。"}, {"text": "这个房间的大环境很大。", "explanation": "这里应该用〈空间〉。“空间”指房间的大小，大环境指社会整体背景，不能用来说房间有多大。"}, {"text": "这只杯子的大环境很精致。", "explanation": "这里应该用〈做工〉。大环境指影响行业或个人的社会整体条件，不是杯子的做工，不能用来评价杯子精不精致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指行业所处的整体社会与经济条件，是“改变”的对象，这里说公司难以改变它。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“改变”的对象不能是“年龄”，年龄不会因公司努力而改变。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物身体的重量，不能指整个行业的条件。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是人的特征，行业没有性别，也不能被改变。"}], "explanations": {"大环境": "大环境指行业所处的整体社会与经济条件，是“改变”的对象，这里说公司难以改变它。", "年龄": "搭配：“改变”的对象不能是“年龄”，年龄不会因公司努力而改变。", "体重": "语义：体重指人或动物身体的重量，不能指整个行业的条件。", "性别": "语义：性别是人的特征，行业没有性别，也不能被改变。"}, "sentence_index": 6, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司里的大环境很高。", "explanation": "这里应该用〈地位〉。大环境指影响整体的社会或经济条件，不是人在组织中的位置，不能用“很高”来形容。"}, {"text": "他的大环境很苗条。", "explanation": "这里应该用〈身材〉。大环境不是人，没有身材，不能用“很苗条”来形容。"}, {"text": "这块蛋糕的大环境很甜。", "explanation": "这里应该用〈味道〉。大环境指社会整体条件，不是蛋糕的味道，不能用来说蛋糕甜不甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只大环境对年轻人很不利。", "corrected_sentence": "这个大环境对年轻人很不利。", "error_description": "量词错误：“大环境”是抽象的社会背景，应搭配量词“个”，说“这个大环境”；“只”用于动物或成对物品中的一只，不能用于大环境。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年大环境的对小公司很不利，很多店都关门了。", "corrected_sentence": "这几年大环境对小公司很不利，很多店都关门了。", "error_description": "“大环境”后多加了“的”，“大环境的对小公司很不利”不成句，应去掉“的”，说“大环境对小公司很不利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
