INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子或院子最外面、通向外边的那扇门。", "primary_collocate": null, "pronunciation": "dà mén", "ipa": "ta˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "回到家，我先关上大门。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的大门是红色的。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在大门外晒太阳。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了锁大门，晚上小偷进来了。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子的大门开着，狗跑出去了。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门时请把大门关好，别让狗跑出去。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大门外有一棵大树。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，爸爸去开大门。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的大门很高，也很重。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节到了，大门上贴着红色的对联。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扇", "label": "量词"}, {"form": "大门口", "label": "复合"}], "register": "中性", "sense_fingerprint": "住宅房子或院子最外面的门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大门", "is_correct": true, "explanation": "“大门”指房子最外面的门，可以关上。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是门窗，不能“关上”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被关上，说不通。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是动物，不能被关上。"}], "explanations": {"大门": "“大门”指房子最外面的门，可以关上。", "作业": "语义：作业不是门窗，不能“关上”。", "空气": "语义：空气不能被关上，说不通。", "老鼠": "语义：老鼠是动物，不能被关上。"}, "sentence_index": 0, "correct_answer": "大门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大门买了一本书。", "explanation": "这里应该用〈书店〉。“大门”是房屋的门，不是卖书的地方。"}, {"text": "他用大门写了一封信。", "explanation": "这里应该用〈纸〉。“大门”不能用来写字。"}, {"text": "他把大门吃完了。", "explanation": "这里应该用〈饭〉。“大门”是建筑，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大门", "is_correct": true, "explanation": "“大门”是房子的正门，门外有树是正常的。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是处所，不能说门外有树。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“外”需要处所词，“脚步”不能用作位置。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是处所，不能说外面有树。"}], "explanations": {"大门": "“大门”是房子的正门，门外有树是正常的。", "考试": "语义：考试不是处所，不能说门外有树。", "脚步": "搭配：“外”需要处所词，“脚步”不能用作位置。", "音乐": "语义：音乐不是处所，不能说外面有树。"}, "sentence_index": 6, "correct_answer": "大门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春节到了，我们把大门吃了。", "explanation": "这里应该用〈饺子〉。“大门”是房屋的门，不能吃。"}, {"text": "春节到了，我们用大门擦地。", "explanation": "这里应该用〈抹布〉。“大门”是建筑，不能用来擦地。"}, {"text": "春节到了，我们用大门包饺子。", "explanation": "这里应该用〈面皮〉。“大门”是建筑，不能用来包饺子，包饺子要用面皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一只大门。", "corrected_sentence": "我家有一扇大门。", "error_description": "错误：门的量词应为“扇”，“只”多用于动物。正确：“一扇大门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子大门的外停着一辆车。", "corrected_sentence": "院子大门外停着一辆车。", "error_description": "错误：“大门外”是方位词组，“大门”和“外”之间不加“的”。正确：“院子大门外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
