INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校、公司、医院等单位或场所的正门。", "primary_collocate": null, "pronunciation": "dà mén", "ipa": "ta˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "学校的大门早上七点开。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在公司大门外等你。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂大门前停着一辆车。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从医院大门进来。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的大门晚上十点关。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行大门上贴着一张通知。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园大门离地铁站很近。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在学校大门前照了相。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安站在单位大门旁边。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从大门走到办公楼要五分钟。", "target_word": "大门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扇", "label": "量词"}, {"form": "大门口", "label": "复合"}], "register": "中性", "sense_fingerprint": "单位、学校等场所的正门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大门", "is_correct": true, "explanation": "“大门”指学校的正门，可以在早上七点开。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“开”用于门窗等可开合的物体，词典不能说“开”。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不能被打开，说不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能作为“开”的对象。"}], "explanations": {"大门": "“大门”指学校的正门，可以在早上七点开。", "词典": "搭配：“开”用于门窗等可开合的物体，词典不能说“开”。", "小鸟": "语义：小鸟不能被打开，说不通。", "老师": "语义：老师是人，不能作为“开”的对象。"}, "sentence_index": 0, "correct_answer": "大门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把学校的大门批改了。", "explanation": "这里应该用〈作业〉。“大门”是建筑，不能被批改。"}, {"text": "我在大门买了一本书。", "explanation": "这里应该用〈书店〉。“大门”是建筑的正门，不是卖书的地方。"}, {"text": "他用大门喝了一杯水。", "explanation": "这里应该用〈水壶〉。“大门”是房屋的门，不能拿来盛水喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大门", "is_correct": true, "explanation": "“大门”是公园的正门，离地铁站近，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是处所，不能说离地铁站近。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“离……很近”需要处所词，“音乐”不能作主语。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是时间，不能说离地铁站近。"}], "explanations": {"大门": "“大门”是公园的正门，离地铁站近，符合语境。", "作业": "语义：作业不是处所，不能说离地铁站近。", "音乐": "搭配：“离……很近”需要处所词，“音乐”不能作主语。", "夏天": "语义：夏天是时间，不能说离地铁站近。"}, "sentence_index": 6, "correct_answer": "大门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把大门煮了一锅汤。", "explanation": "这里应该用〈菜〉。“大门”是房屋的门，不是食材，不能用来煮汤。"}, {"text": "他用大门写完了作业。", "explanation": "这里应该用〈铅笔〉。“大门”是单位的正门，不能用来写字。"}, {"text": "他用大门洗了一个澡。", "explanation": "这里应该用〈浴室〉。“大门”不能用来洗澡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看见一条大门。", "corrected_sentence": "我看见一扇大门。", "error_description": "错误：“大门”的量词应为“扇”，“条”多用于细长的东西。正确：“一扇大门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在公园大门的前照了相。", "corrected_sentence": "他们在公园大门前照了相。", "error_description": "错误：“大门前”是方位词组，“大门”和“前”之间不加“的”。正确：“公园大门前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
