INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94133, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "委托是请别人替自己做一件事。", "primary_collocate": null, "pronunciation": "wěi tuō", "ipa": "weɪ˨˩˦ tʰuo˥", "syllable_count": 2, "sentences": [{"text": "他委托同学替他交作业。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我委托姐姐帮我寄信。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶委托我去买药。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经委托他处理这个问题了。", "target_word": "委托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她委托朋友帮忙找房子。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把孩子委托给了亲戚。", "target_word": "委托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我委托同事替我开会。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他委托邻居收快递。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想委托你办一件小事。", "target_word": "委托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老李委托我给他带点东西。", "target_word": "委托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "委托了", "label": "体标"}, {"form": "委托过", "label": "体标"}], "register": "通用", "sense_fingerprint": "请别人替自己做一件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "委托", "is_correct": true, "explanation": "正确：“委托”表示请别人替自己做事，与“同学替他交作业”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“同学”不能被吃，句子荒谬。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，“同学”不能被洗，句子不通。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：“支付”后接钱款，不能接“同学”。"}], "explanations": {"委托": "正确：“委托”表示请别人替自己做事，与“同学替他交作业”相符。", "吃": "语义：“吃”指进食，“同学”不能被吃，句子荒谬。", "洗": "语义：“洗”指清洗，“同学”不能被洗，句子不通。", "支付": "搭配：“支付”后接钱款，不能接“同学”。"}, "sentence_index": 0, "correct_answer": "委托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我已经委托他去睡觉了。", "explanation": "这里应该用〈让〉。“委托”是请人代为办事，叫人去做自己的事应用〈让〉，不能说委托他去睡觉。"}, {"text": "我已经委托他一本书了。", "explanation": "这里应该用〈送〉。“委托”后面要接人和要办的事，不能直接接“一本书”这样的物品；把东西给人应说“送他一本书”。"}, {"text": "我已经委托天气处理这个问题了。", "explanation": "这里应该用〈交给〉。“委托”的接受者必须是能办事的人，“天气”不能接受委托；把事务交给人应说“交给他”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "委托", "is_correct": true, "explanation": "正确：“委托”表示请别人替自己做事，与“同事替我开会”相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，“同事”不能被咬，句子不通。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”指击打，“同事”不能被打去替我开会，句子荒谬。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”后接商品，不能接“同事”。"}], "explanations": {"委托": "正确：“委托”表示请别人替自己做事，与“同事替我开会”相符。", "咬": "语义：“咬”指用牙齿咬，“同事”不能被咬，句子不通。", "打": "语义：“打”指击打，“同事”不能被打去替我开会，句子荒谬。", "购买": "搭配：“购买”后接商品，不能接“同事”。"}, "sentence_index": 6, "correct_answer": "委托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我委托他一份礼物。", "explanation": "这里应该用〈送〉。“委托”是交付要办的事务，送礼物应用〈送〉。"}, {"text": "老李委托我给他生气。", "explanation": "这里应该用〈惹〉。“委托”的宾语必须是待办的事务，不能是情绪，应说“惹他生气”。"}, {"text": "我委托老李的生日。", "explanation": "这里应该用〈庆祝〉。“委托”的宾语是待办的事务，不能是“生日”，应说“庆祝老李的生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我委托替我交材料。", "corrected_sentence": "我委托他替我交材料。", "error_description": "错误：“委托替我交材料”；正确：“委托他替我交材料”。“委托”需要说明由谁来办事，“他”不能省略，否则句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我委托你了办一件小事。", "corrected_sentence": "我委托你办了一件小事。", "error_description": "错误：“委托你了办”；正确：“委托你办了”。“了”应放在动词“办”之后表示完成，放在“委托你”后面是位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
