INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用枪炮等武器向目标发射弹药。", "primary_collocate": null, "pronunciation": "shè jī", "ipa": "ʂɤ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "士兵向敌人的方向射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "命令一下，炮兵马上开始射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的人朝我们射击，我们赶快趴下。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们朝山上射击了很久。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人停止了射击，山谷安静下来。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有命令，谁也不能射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察向天空射击，提醒大家离开。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队用大炮向远处的阵地射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们躲在墙后面，向进攻的敌人射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我军的炮火猛烈射击着敌人的阵地。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "射击了", "label": "体标：了"}, {"form": "射击过", "label": "体标：过"}, {"form": "射击着", "label": "体标：着"}, {"form": "射击手", "label": "复合词"}, {"form": "射擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "射击：用枪炮向敌人或目标发射弹药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94c76b39-0b43-41b7-acc8-e7c4649e2034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "射击", "is_correct": true, "explanation": "射击是用枪炮向目标发射弹药。"}, {"text": "设计", "is_correct": false, "explanation": "shè jì 与 shè jī 的第二音节声调不同（第四声与第一声），意思是设计。"}, {"text": "涉及", "is_correct": false, "explanation": "jí 与 jī 声调不同（第二声与第一声），意思是涉及。"}, {"text": "舍己", "is_correct": false, "explanation": "shě jǐ 与 shè jī 的两个音节都只差声调（第三声对第四声、第三声对第一声），意思是牺牲自己。"}], "explanations": {"射击": "射击是用枪炮向目标发射弹药。", "设计": "shè jì 与 shè jī 的第二音节声调不同（第四声与第一声），意思是设计。", "涉及": "jí 与 jī 声调不同（第二声与第一声），意思是涉及。", "舍己": "shě jǐ 与 shè jī 的两个音节都只差声调（第三声对第四声、第三声对第一声），意思是牺牲自己。"}, "sentence_index": null, "correct_answer": "射击"}, "level_3": {"options": [{"text": "射击", "is_correct": true, "explanation": "射击是用武器向目标发射弹药，与“向敌人的方向”相符。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”的对象是人，且不能说“向……的方向拥抱”。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是朝某方向进行的动作，不能说“向敌人的方向睡觉”。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是闲走，与面对敌人的战斗情境不符。"}], "explanations": {"射击": "射击是用武器向目标发射弹药，与“向敌人的方向”相符。", "拥抱": "搭配：“拥抱”的对象是人，且不能说“向……的方向拥抱”。", "睡觉": "语义：“睡觉”不是朝某方向进行的动作，不能说“向敌人的方向睡觉”。", "散步": "语义：“散步”是闲走，与面对敌人的战斗情境不符。"}, "sentence_index": 0, "correct_answer": "射击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月光射击在湖面上，一片银白。", "explanation": "这里应该用〈照射〉。光线照到物体上要说照射；射击只指用武器发射弹药。"}, {"text": "护士给他射击了一针。", "explanation": "这里应该用〈注射〉。打针要说注射；射击只指用武器发射弹药。"}, {"text": "油漆从喷枪里射击出来，溅了一地。", "explanation": "这里应该用〈喷射〉。液体从管口喷出要说喷射；射击只指用武器发射。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "射击", "is_correct": true, "explanation": "射击是用武器向目标发射弹药，与“向天空射击，提醒大家离开”相符。"}, {"text": "劝说", "is_correct": false, "explanation": "搭配：“劝说”的对象是人，不能说向天空劝说。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“提醒大家离开”的警示动作不相干，表达不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”不是警示动作，与“向天空”搭配不通。"}], "explanations": {"射击": "射击是用武器向目标发射弹药，与“向天空射击，提醒大家离开”相符。", "劝说": "搭配：“劝说”的对象是人，不能说向天空劝说。", "唱歌": "语义：“唱歌”与“提醒大家离开”的警示动作不相干，表达不通。", "跳舞": "语义：“跳舞”不是警示动作，与“向天空”搭配不通。"}, "sentence_index": 6, "correct_answer": "射击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力射击一块石头，打中了树。", "explanation": "这里应该用〈投掷〉。把石块扔出去要说投掷；射击只指用武器发射弹药。"}, {"text": "他们射击了敌人的士气。", "explanation": "这里应该用〈打击〉。针对士气要说打击；射击只指用武器发射弹药。"}, {"text": "灯的影子射击在墙上，轮廓很清楚。", "explanation": "这里应该用〈投射〉。影子落在墙面上叫投射；射击只用于发射弹药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "炮兵朝城墙猛烈的射击。", "corrected_sentence": "炮兵朝城墙猛烈地射击。", "error_description": "错误形式是“猛烈的射击”，正确形式是“猛烈地射击”。“猛烈”修饰动词“射击”时应用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舰船向港口的目标进行了一个射击。", "corrected_sentence": "舰船向港口的目标进行了一次射击。", "error_description": "错误形式是“一个射击”，正确形式是“一次射击”。“射击”作名词时，动作的量词应用“次”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
