INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小开是有钱人家里年纪轻的儿子。", "primary_collocate": null, "pronunciation": "xiǎo kāi", "ipa": "ɕiɑʊ̯˨˩˦ kʰaɪ̯˥", "syllable_count": 2, "sentences": [{"text": "他是有钱人家的小开，从来不用打工。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位小开每天坐豪车来上课。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小开的爸爸有三家大公司。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁给了一位有钱的小开。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都叫他小开，因为他家很有钱。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小开花钱很大方，请朋友吃大餐。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家富人的小开不爱工作，只爱玩。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小开穿着名牌衣服，手上戴着金表。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学是个小开，周末常开跑车出去玩。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家很有钱，却不像小开那样乱花钱。", "target_word": "小开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小開", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "有钱人家里年纪轻的儿子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94137, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小开", "is_correct": true, "explanation": "小开：有钱人家年纪轻的儿子，是正确答案。"}, {"text": "笑开", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，“笑开”意思是笑出来。"}, {"text": "小楷", "is_correct": false, "explanation": "kǎi（第三声）与 kāi（第一声）声调不同，“小楷”是一种字体。"}, {"text": "小康", "is_correct": false, "explanation": "第二音节 kāng 的韵尾与 kāi 不同（ng 与 i），“小康”意思是生活比较宽裕。"}], "explanations": {"小开": "小开：有钱人家年纪轻的儿子，是正确答案。", "笑开": "xiào（第四声）与 xiǎo（第三声）声调不同，“笑开”意思是笑出来。", "小楷": "kǎi（第三声）与 kāi（第一声）声调不同，“小楷”是一种字体。", "小康": "第二音节 kāng 的韵尾与 kāi 不同（ng 与 i），“小康”意思是生活比较宽裕。"}, "sentence_index": null, "correct_answer": "小开"}, "level_3": {"options": [{"text": "小开", "is_correct": true, "explanation": "小开：有钱人家年纪轻的儿子，与“从来不用打工”相合。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机要靠开车工作，与“从来不用打工”矛盾。"}, {"text": "女儿", "is_correct": false, "explanation": "体貌：“他”是男性，不能说成女儿，性别不合。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民要干活，与有钱人家的“从来不用打工”矛盾。"}], "explanations": {"小开": "小开：有钱人家年纪轻的儿子，与“从来不用打工”相合。", "司机": "语义：司机要靠开车工作，与“从来不用打工”矛盾。", "女儿": "体貌：“他”是男性，不能说成女儿，性别不合。", "农民": "语义：农民要干活，与有钱人家的“从来不用打工”矛盾。"}, "sentence_index": 0, "correct_answer": "小开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位退休多年的小开，每天在茶馆里喝茶。", "explanation": "这里应该用〈老人〉。小开指年轻的富家子弟，不能形容退休多年的人。"}, {"text": "他家里很穷，他却是个小开，每天都在地里干活。", "explanation": "这里不能用〈小开〉。小开专指有钱人家年轻的儿子，家境贫穷的人不能叫小开。"}, {"text": "他是个年轻的小开，正在找工作养家。", "explanation": "这里应该用〈小伙子〉。小开专指不用打工的富家子弟，一般年轻人找工作养家要用小伙子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小开", "is_correct": true, "explanation": "小开：有钱人家年纪轻的儿子，与“不爱工作，只爱玩”相合。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：富人家里不会有乞丐，与“富人”的前提矛盾。"}, {"text": "童工", "is_correct": false, "explanation": "语义：富人家里不会有童工，与“富人”的前提矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "体貌：婴儿还谈不上工作与否，与“不爱工作”的年龄前提不合。"}], "explanations": {"小开": "小开：有钱人家年纪轻的儿子，与“不爱工作，只爱玩”相合。", "乞丐": "语义：富人家里不会有乞丐，与“富人”的前提矛盾。", "童工": "语义：富人家里不会有童工，与“富人”的前提矛盾。", "婴儿": "体貌：婴儿还谈不上工作与否，与“不爱工作”的年龄前提不合。"}, "sentence_index": 6, "correct_answer": "小开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名小开，每天给病人看病。", "explanation": "这里应该用〈医生〉。小开是对富家年轻儿子的称呼，不是职业，不能说“一名小开”给人看病。"}, {"text": "那位七十岁的小开每天去公园散步。", "explanation": "这里应该用〈老人〉。小开指年轻的富家子弟，不能形容七十岁的老人。"}, {"text": "她是一位女小开，经常在法庭上为客户辩护。", "explanation": "这里应该用〈律师〉。小开专指有钱人家年轻的儿子，是男性身份，不能指女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小开每天开豪车去俱乐部。", "corrected_sentence": "这位小开每天开豪车去俱乐部。", "error_description": "错误：“小开”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物）。正确为“这位小开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只小开很会做生意。", "corrected_sentence": "这位小开很会做生意。", "error_description": "错误：“小开”指人，量词“只”多用于动物，应用“位”。正确为“这位小开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
