INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94141, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94141, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得道是明白了很深很大的道理。", "primary_collocate": null, "pronunciation": "dé dào", "ipa": "tɤ˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老人想了一辈子，终于得道了。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师说，人要多年思考才能得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过很多书，可是还没有得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得道以后，他看事情更清楚了。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己没有得道，不敢讲大道理。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人想得道，先要多想、多问。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得道的人说话很简单，却很有道理。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生一生读书思考，晚年才得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遇到难题后反复琢磨，慢慢得道了。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都觉得这位老人已经得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "得道了", "label": "体标"}, {"form": "得道高僧", "label": "复合"}], "register": "书面", "sense_fingerprint": "想明白了很深很大的道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94141, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“终于吃了”与前文“想了一辈子”的思考语义无关。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“终于做饭了”与“想了一辈子”的语义不合。"}, {"text": "得道", "is_correct": true, "explanation": "正确：老人想了一辈子，终于想明白了道理。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差与前文“想了一辈子”的思考语义无关，语义不合。"}], "explanations": {"吃": "语义：“终于吃了”与前文“想了一辈子”的思考语义无关。", "做饭": "语义：“终于做饭了”与“想了一辈子”的语义不合。", "得道": "正确：老人想了一辈子，终于想明白了道理。", "出差": "语义：出差与前文“想了一辈子”的思考语义无关，语义不合。"}, "sentence_index": 0, "correct_answer": "得道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛他终于得道了，拿到了冠军。", "explanation": "这里不能用〈得道〉。此处指赢得比赛、取得胜利，得道只指人想明白深刻的道理，不表示取得胜利。"}, {"text": "我的电脑终于得道了，能正常开机了。", "explanation": "此处说电脑修好、恢复正常运行，得道不能表示机器修好或恢复运转。"}, {"text": "这个小孩子很快得道了，两天就学会了游泳。", "explanation": "此处说孩子学会了游泳这项技能，得道不能表示掌握某种技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出错", "is_correct": false, "explanation": "语义：“出错的人说话很简单，却很有道理”前后矛盾。"}, {"text": "得道", "is_correct": true, "explanation": "正确：得道的人说话很简单，却很有道理。"}, {"text": "瞎说", "is_correct": false, "explanation": "语域：“瞎说”是口语中带贬义的说法，与“却很有道理”矛盾，语域也不合。"}, {"text": "挨饿", "is_correct": false, "explanation": "语义：“挨饿的人”说话却很有道理，搭配上不合逻辑。"}], "explanations": {"出错": "语义：“出错的人说话很简单，却很有道理”前后矛盾。", "得道": "正确：得道的人说话很简单，却很有道理。", "瞎说": "语域：“瞎说”是口语中带贬义的说法，与“却很有道理”矛盾，语域也不合。", "挨饿": "语义：“挨饿的人”说话却很有道理，搭配上不合逻辑。"}, "sentence_index": 6, "correct_answer": "得道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器已经得道了，不用再修了。", "explanation": "此处说机器已经修好、不用再修，得道不能表示机器修好，只用于人领悟深刻道理。"}, {"text": "他的感冒吃了三天药，终于得道了。", "explanation": "此处说感冒痊愈，得道不能表示病愈。"}, {"text": "这只猫很快就得道了，会自己开门。", "explanation": "此处说猫学会了自己开门，得道不能表示学会某种技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于得道了了。", "corrected_sentence": "他终于得道了。", "error_description": "错误在句末的“了”。句末只用一个“了”，应说“终于得道了”；“得道了了”多出一个“了”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是得道人的。", "corrected_sentence": "他是得道的人。", "error_description": "错误在“的”的位置。“的”应放在修饰语“得道”之后、中心词“人”之前，应说“得道的人”；“得道人的”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
