INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修行有成，达到佛教或道教所说的最高境界。", "primary_collocate": null, "pronunciation": "dé dào", "ipa": "tɤ˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这位和尚修行了几十年，终于得道了。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说他在山上得道成仙。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真练功，希望有一天能得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父告诉他，得道要靠自己的心。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在寺里坐了三年，最后得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老和尚得道后，心里很平静。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得道以后，不再害怕生死。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里说，他在树下静坐得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都说那位老道士已经得道了。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修行了一辈子，到老才得道。", "target_word": "得道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "得道了", "label": "体标"}, {"form": "得道高僧", "label": "复合"}], "register": "书面", "sense_fingerprint": "修行有成，达到佛道或道家境界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发财", "is_correct": false, "explanation": "语义：修行与发财无关，“修行了几十年，终于发财了”前后不合。"}, {"text": "得道", "is_correct": true, "explanation": "正确：这位和尚修行了几十年，终于修行有成。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”与修行的语义不合。"}, {"text": "出差", "is_correct": false, "explanation": "语义：修行与出差无关，“修行了几十年，终于出差了”前后不合。"}], "explanations": {"发财": "语义：修行与发财无关，“修行了几十年，终于发财了”前后不合。", "得道": "正确：这位和尚修行了几十年，终于修行有成。", "做饭": "语义：“做饭”与修行的语义不合。", "出差": "语义：修行与出差无关，“修行了几十年，终于出差了”前后不合。"}, "sentence_index": 0, "correct_answer": "得道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的洗衣机终于得道了，可以洗衣服了。", "explanation": "此处说洗衣机修好、能正常使用，得道不能表示机器修好或恢复使用。"}, {"text": "这台电脑终于得道了，能正常开机了。", "explanation": "此处说电脑恢复正常、能开机了，得道不能表示机器修好。"}, {"text": "这只狗训练了三天，就得道了。", "explanation": "此处说狗学会了某个动作、训练成功，得道不能表示动物学会动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃饭", "is_correct": false, "explanation": "语义：“他吃饭以后，不再害怕生死”语义不通，与前文语境不合。"}, {"text": "得道", "is_correct": true, "explanation": "正确：他修行有成以后，不再害怕生死。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班与不再害怕生死没有逻辑关系，语义不合。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差与“不再害怕生死”没有逻辑关系，语义不合。"}], "explanations": {"吃饭": "语义：“他吃饭以后，不再害怕生死”语义不通，与前文语境不合。", "得道": "正确：他修行有成以后，不再害怕生死。", "上班": "语义：上班与不再害怕生死没有逻辑关系，语义不合。", "出差": "语义：出差与“不再害怕生死”没有逻辑关系，语义不合。"}, "sentence_index": 6, "correct_answer": "得道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车终于得道了，跑得很快。", "explanation": "此处说车的性能好、跑得快，得道不能表示车辆性能好。"}, {"text": "他的手表用了十年，终于得道了。", "explanation": "此处说手表经久耐用，得道不能表示物件用得久或经久耐用。"}, {"text": "他的孙子很快就得道了，两天就学会了骑车。", "explanation": "此处说孙子学会了骑车，得道不能表示学会某项技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位和尚终于得道了了。", "corrected_sentence": "这位和尚终于得道了。", "error_description": "错误在句末的“了”。句末只用一个“了”，应说“终于得道了”；“得道了了”多出一个“了”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位得道地老人很平静。", "corrected_sentence": "那位得道的老人很平静。", "error_description": "错误在“得道”后的助词。“得道”修饰名词“老人”时应用“的”，不能用“地”（“地”用于修饰动词或形容词）。应说“得道的老人”；“得道地老人”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
