INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "心脏在胸口里面，一直在跳，让血在身体里流动。", "primary_collocate": null, "pronunciation": "xīn zàng", "ipa": "ɕin˥ tsɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的心脏跳得很快。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手放在胸口，感到心脏在跳。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我的心脏跳得特别快。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏在胸口里，一直不停地跳。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听，你的心脏跳得多有力！", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看恐怖电影时，我的心脏跳得厉害。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她紧张得心脏都要跳出来了。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把耳朵贴在爸爸胸口，听到他的心脏在跳。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬了三层楼，奶奶觉得心脏很难受。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟的心脏很小，跳得也很快。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗心脏", "label": "量词"}, {"form": "心脏病", "label": "复合"}], "register": "通用", "sense_fingerprint": "胸口里一直在跳的器官，能感觉到跳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心脏", "is_correct": true, "explanation": "正确：「心脏」是跳动的器官，「心脏跳得很快」符合语义。"}, {"text": "手", "is_correct": false, "explanation": "搭配：「手」不会「跳」得很快，心跳的主语应是心脏。"}, {"text": "嗓子", "is_correct": false, "explanation": "搭配：「嗓子」不能用「跳」来形容快慢，语境不通。"}, {"text": "肺", "is_correct": false, "explanation": "语义：「肺」负责呼吸，不会跳动，与「跳得很快」矛盾。"}], "explanations": {"心脏": "正确：「心脏」是跳动的器官，「心脏跳得很快」符合语义。", "手": "搭配：「手」不会「跳」得很快，心跳的主语应是心脏。", "嗓子": "搭配：「嗓子」不能用「跳」来形容快慢，语境不通。", "肺": "语义：「肺」负责呼吸，不会跳动，与「跳得很快」矛盾。"}, "sentence_index": 0, "correct_answer": "心脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生从冰箱里拿出了一条心脏。", "explanation": "这里应该用〈颗〉。心脏用量词「颗」，「条」用于细长的东西，不能用于心脏。"}, {"text": "这个人心脏很坏。", "explanation": "这里应该用〈心肠〉。说人的性格或品行坏要用「心肠」，「心脏」指身体器官。"}, {"text": "他的心脏很快。", "explanation": "这里应该用〈心跳〉。形容心跳快慢要说「心脏跳得很快」或「心跳很快」，「心脏很快」不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心脏", "is_correct": true, "explanation": "正确：「心脏都要跳出来」是紧张时心跳剧烈的常用说法，符合语境。"}, {"text": "肝", "is_correct": false, "explanation": "语义：「肝」不会跳出来，紧张时跳动的应是心脏。"}, {"text": "胃", "is_correct": false, "explanation": "语义：「胃」不是跳动的器官，「胃都要跳出来」不合常理。"}, {"text": "膝盖", "is_correct": false, "explanation": "搭配：「膝盖」不能与「跳出来」搭配，语境不通。"}], "explanations": {"心脏": "正确：「心脏都要跳出来」是紧张时心跳剧烈的常用说法，符合语境。", "肝": "语义：「肝」不会跳出来，紧张时跳动的应是心脏。", "胃": "语义：「胃」不是跳动的器官，「胃都要跳出来」不合常理。", "膝盖": "搭配：「膝盖」不能与「跳出来」搭配，语境不通。"}, "sentence_index": 6, "correct_answer": "心脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生拿出了一张心脏。", "explanation": "这里应该用〈颗〉。「张」用于平面的东西，心脏是立体器官，应该用「颗」。"}, {"text": "他的心脏很宽。", "explanation": "这里应该用〈心胸〉。形容气量大要说「心胸宽」，「心脏」指身体器官，不能说宽。"}, {"text": "谢谢你的心脏。", "explanation": "这里应该用〈心意〉。感谢别人的好意要说「心意」，「心脏」不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑得太快了，心脏跳厉害。", "corrected_sentence": "他跑得太快了，心脏跳得厉害。", "error_description": "错误：「跳厉害」，缺少补语标记「得」。正确：「跳得厉害」。动词后面描述程度的补语要用「得」引出，缺少「得」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，我的心脏突然跳得快很。", "corrected_sentence": "听到这个消息，我的心脏突然跳得很快。", "error_description": "错误：「跳得快很」，程度副词「很」放错了位置。正确：「跳得很快」。「很」应放在形容词前面表示程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
