INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和高等动物体内推动血液循环的器官。", "primary_collocate": null, "pronunciation": "xīn zàng", "ipa": "ɕin˥ tsɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "心脏是推动血液流动的器官。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的心脏有一点问题。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病人需要做心脏检查。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏把血送到全身。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的心脏不好，要天天吃药。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动对心脏很有好处。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器检查了她的心脏。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的心脏比人的大得多。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心脏做了手术，现在好多了。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏和肺都是身体里重要的器官。", "target_word": "心脏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗心脏", "label": "量词"}, {"form": "心脏病", "label": "复合"}], "register": "书面", "sense_fingerprint": "体内推动血液循环的器官（医学、生理）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心脏", "is_correct": true, "explanation": "正确：「心脏」是推动血液流动的器官，符合定义。"}, {"text": "肾", "is_correct": false, "explanation": "语义：「肾」负责过滤和排出废物，不推动血液。"}, {"text": "胃", "is_correct": false, "explanation": "语义：「胃」负责消化食物，不推动血液。"}, {"text": "心口", "is_correct": false, "explanation": "语义：「心口」指胸口的位置，不是器官，不能推动血液流动。"}], "explanations": {"心脏": "正确：「心脏」是推动血液流动的器官，符合定义。", "肾": "语义：「肾」负责过滤和排出废物，不推动血液。", "胃": "语义：「胃」负责消化食物，不推动血液。", "心口": "语义：「心口」指胸口的位置，不是器官，不能推动血液流动。"}, "sentence_index": 0, "correct_answer": "心脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验室里有一根心脏。", "explanation": "这里应该用〈颗〉。心脏用量词「颗」，「根」用于细长的东西，不能用于心脏。"}, {"text": "他身体里有一座心脏。", "explanation": "这里应该用〈颗〉。「座」用于山、楼房等大型物体，心脏应用「颗」。"}, {"text": "他花了很多心脏。", "explanation": "这里应该用〈心血〉。「心血」比喻付出的精力，「心脏」不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心脏", "is_correct": true, "explanation": "正确：「心脏」是可以用机器检查的器官，符合语境。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是心理状态，不能用机器检查。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：「笑容」是表情，不是身体部位，不能用机器检查。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：「脚印」是地面留下的痕迹，不是器官，不能用机器检查。"}], "explanations": {"心脏": "正确：「心脏」是可以用机器检查的器官，符合语境。", "心情": "语义：「心情」是心理状态，不能用机器检查。", "笑容": "语义：「笑容」是表情，不是身体部位，不能用机器检查。", "脚印": "语义：「脚印」是地面留下的痕迹，不是器官，不能用机器检查。"}, "sentence_index": 6, "correct_answer": "心脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生拿出了一支心脏。", "explanation": "这里应该用〈颗〉。「支」用于细长的笔、枪之类的东西，心脏应用「颗」。"}, {"text": "他的心脏很快乐，总是笑呵呵的。", "explanation": "这里应该用〈心里〉。表示内心的感受要说「心里很快乐」，「心脏」指身体器官，不能表示感情。"}, {"text": "他终于实现了自己的心脏。", "explanation": "这里应该用〈心愿〉。「实现」搭配愿望、目标，「心脏」不能被实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只青蛙有一根小小的心脏。", "corrected_sentence": "这只青蛙有一颗小小的心脏。", "error_description": "错误：「一根心脏」，量词用错了。正确：「一颗心脏」。「根」用于细长的东西，心脏要用量词「颗」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体检结果显示他的心脏不有问题。", "corrected_sentence": "体检结果显示他的心脏没有问题。", "error_description": "错误：「不有问题」，否定「有」要用「没有」，不能用「不」。正确：「没有问题」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
