INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94147, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“愈来愈”即“越来越”，表示程度或数量一直在不断加深、增加。", "primary_collocate": null, "pronunciation": "yù", "ipa": "y˥˩", "syllable_count": 1, "sentences": [{"text": "天气愈来愈冷，大家都穿上了厚衣服。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市愈来愈大。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得愈来愈好。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来的人愈来愈多，房间都坐满了。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近我愈来愈忙，没时间看电影。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜愈来愈深，街上很安静。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愈来愈喜欢这个新学校。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的云愈来愈黑，可能要下雨。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的价格愈来愈便宜。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子愈来愈高，去年的裤子都短了。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愈加", "label": "复合"}, {"form": "愈发", "label": "复合"}], "register": "书面", "sense_fingerprint": "愈来愈：越来越，程度不断加深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愈", "is_correct": true, "explanation": "愈（yù，第四声）是本词，在“愈来愈”中表示程度不断加深。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ，第三声）与愈（yù，第四声）声调不同，意思是雨水。"}, {"text": "语", "is_correct": false, "explanation": "语（yǔ，第三声）与愈（yù，第四声）声调不同，意思是语言。"}, {"text": "余", "is_correct": false, "explanation": "余（yú，第二声）与愈（yù，第四声）声调不同，意思是剩余。"}, {"text": "渔", "is_correct": false, "explanation": "渔（yú，第二声）与愈（yù，第四声）声调不同，意思是捕鱼。"}], "explanations": {"愈": "愈（yù，第四声）是本词，在“愈来愈”中表示程度不断加深。", "雨": "雨（yǔ，第三声）与愈（yù，第四声）声调不同，意思是雨水。", "语": "语（yǔ，第三声）与愈（yù，第四声）声调不同，意思是语言。", "余": "余（yú，第二声）与愈（yù，第四声）声调不同，意思是剩余。", "渔": "渔（yú，第二声）与愈（yù，第四声）声调不同，意思是捕鱼。"}, "sentence_index": null, "correct_answer": "愈"}, "level_3": {"options": [{"text": "愈", "is_correct": true, "explanation": "愈与后面的“来”组成“愈来愈”，表示天气越来越冷，句子通顺。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定变化的过程，与“天气越来越冷”的描述相矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与天气持续变冷的意思不符。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，无法表示天气不断变冷的程度加深。"}], "explanations": {"愈": "愈与后面的“来”组成“愈来愈”，表示天气越来越冷，句子通顺。", "不": "语义：“不”否定变化的过程，与“天气越来越冷”的描述相矛盾。", "刚": "语义：“刚”表示刚刚发生，与天气持续变冷的意思不符。", "只": "语义：“只”表示限定，无法表示天气不断变冷的程度加深。"}, "sentence_index": 0, "correct_answer": "愈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他愈来愈是中国人。", "explanation": "“愈来愈”后面要接能不断加深的程度或数量，“是中国人”不能逐渐加深。"}, {"text": "我愈来愈有一个哥哥。", "explanation": "“有一个哥哥”是固定事实，不会逐渐增加，不能用“愈来愈”。"}, {"text": "老师愈来愈讲了一遍课文。", "explanation": "“讲了一遍”是一次完成的动作，没有程度变化，不能用“愈来愈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
