INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94148, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度加深，相当于“越”“更加”。", "primary_collocate": null, "pronunciation": "yù", "ipa": "y˥˩", "syllable_count": 1, "sentences": [{"text": "雨愈下愈大，我们只好回家。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山愈高，风愈大。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愈想愈生气，一句话也不说。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天色愈晚，街上的人愈少。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水愈深，鱼愈多。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路愈走愈远，天也慢慢黑了。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愈说愈快，大家都听不清了。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题愈讨论愈清楚。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情愈难，他愈不想放弃。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书读得愈多，愈觉得自己知道得少。", "target_word": "愈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愈加", "label": "复合"}, {"form": "愈发", "label": "复合"}], "register": "书面", "sense_fingerprint": "愈A愈B：程度随之加深，相当于越", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94148, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愈", "is_correct": true, "explanation": "愈（yù，第四声）是本词，意思是越、更加，表示程度随之加深。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ，第三声）与愈（yù，第四声）声调不同，意思是雨水。"}, {"text": "鱼", "is_correct": false, "explanation": "鱼（yú，第二声）与愈（yù，第四声）声调不同，意思是鱼类。"}, {"text": "语", "is_correct": false, "explanation": "语（yǔ，第三声）与愈（yù，第四声）声调不同，意思是语言。"}, {"text": "渔", "is_correct": false, "explanation": "渔（yú，第二声）与愈（yù，第四声）声调不同，意思是捕鱼。"}], "explanations": {"愈": "愈（yù，第四声）是本词，意思是越、更加，表示程度随之加深。", "雨": "雨（yǔ，第三声）与愈（yù，第四声）声调不同，意思是雨水。", "鱼": "鱼（yú，第二声）与愈（yù，第四声）声调不同，意思是鱼类。", "语": "语（yǔ，第三声）与愈（yù，第四声）声调不同，意思是语言。", "渔": "渔（yú，第二声）与愈（yù，第四声）声调不同，意思是捕鱼。"}, "sentence_index": null, "correct_answer": "愈"}, "level_3": {"options": [{"text": "愈", "is_correct": true, "explanation": "愈是表示程度加深的副词，与后面的“愈大”配成“愈下愈大”，句子通顺。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“下”，与“雨在下”的情况矛盾，句子说不通。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示最高程度，不能与“愈……愈……”的递进结构同用。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与雨势持续加大的“愈下愈大”不符。"}], "explanations": {"愈": "愈是表示程度加深的副词，与后面的“愈大”配成“愈下愈大”，句子通顺。", "不": "语义：“不”否定“下”，与“雨在下”的情况矛盾，句子说不通。", "最": "搭配：“最”表示最高程度，不能与“愈……愈……”的递进结构同用。", "刚": "语义：“刚”表示刚刚发生，与雨势持续加大的“愈下愈大”不符。"}, "sentence_index": 0, "correct_answer": "愈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我愈高。", "explanation": "这里应该用〈更〉。“愈”要用在“愈A愈B”里表示程度随之加深，不能直接用在“比”字句里。"}, {"text": "这是我愈喜欢的菜。", "explanation": "这里应该用〈最〉。“愈”表示程度随着变化加深，不表示最高程度。"}, {"text": "这张照片愈拍了三次。", "explanation": "这里应该用〈又〉。“愈”不表示动作的重复，表示“又”的意思要用“又”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94148, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "愈", "is_correct": true, "explanation": "愈（yù，第四声）是本词，意思是越、更加，表示程度随之加深。"}, {"text": "余", "is_correct": false, "explanation": "余（yú，第二声）与愈（yù，第四声）声调不同，意思是剩下的。"}, {"text": "娱", "is_correct": false, "explanation": "娱（yú，第二声）与愈（yù，第四声）声调不同，意思是娱乐。"}, {"text": "羽", "is_correct": false, "explanation": "羽（yǔ，第三声）与愈（yù，第四声）声调不同，意思是羽毛。"}, {"text": "愚", "is_correct": false, "explanation": "愚（yú，第二声）与愈（yù，第四声）声调不同，意思是愚笨。"}, {"text": "与", "is_correct": false, "explanation": "与（yǔ，第三声）与愈（yù，第四声）声调不同，意思是和、给。"}], "explanations": {"愈": "愈（yù，第四声）是本词，意思是越、更加，表示程度随之加深。", "余": "余（yú，第二声）与愈（yù，第四声）声调不同，意思是剩下的。", "娱": "娱（yú，第二声）与愈（yù，第四声）声调不同，意思是娱乐。", "羽": "羽（yǔ，第三声）与愈（yù，第四声）声调不同，意思是羽毛。", "愚": "愚（yú，第二声）与愈（yù，第四声）声调不同，意思是愚笨。", "与": "与（yǔ，第三声）与愈（yù，第四声）声调不同，意思是和、给。"}, "sentence_index": null, "correct_answer": "愈"}, "level_3": {"options": [{"text": "愈", "is_correct": true, "explanation": "愈与后面的“愈快”配成“愈说愈快”，表示说话的速度随之加快，句子通顺。"}, {"text": "没", "is_correct": false, "explanation": "语义：“没”否定“说”，与“她愈说愈快”描述的说话过程相矛盾。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚开始，不能表达持续加深的“愈……愈……”。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”表示过去的经历，与句末“大家都听不清了”描述的当前情况不符。"}], "explanations": {"愈": "愈与后面的“愈快”配成“愈说愈快”，表示说话的速度随之加快，句子通顺。", "没": "语义：“没”否定“说”，与“她愈说愈快”描述的说话过程相矛盾。", "才": "语义：“才”表示刚开始，不能表达持续加深的“愈……愈……”。", "曾": "语义：“曾”表示过去的经历，与句末“大家都听不清了”描述的当前情况不符。"}, "sentence_index": 6, "correct_answer": "愈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是全班愈高的学生。", "explanation": "这里应该用〈最〉。“愈”不表示最高程度。"}, {"text": "她比姐姐愈漂亮。", "explanation": "这里应该用〈更〉。“比”字句要用“更”，“愈”要用在“愈A愈B”里。"}, {"text": "他愈去了一次北京。", "explanation": "这里应该用〈又〉。“愈”不表示动作的重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路愈走窄。", "corrected_sentence": "这条路愈走愈窄。", "error_description": "错误：后半句缺少“愈”。正确形式应为“愈……愈……”，前后各用一个“愈”，所以应说“这条路愈走愈窄”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑愈愈快。", "corrected_sentence": "他愈跑愈快。", "error_description": "错误：“愈”放错了位置。“愈”应放在动词“跑”之前，构成“愈跑愈快”，不能放在动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
