INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为达到目的而自觉努力、克服困难的心理力量。", "primary_collocate": null, "pronunciation": "yì zhì", "ipa": "i˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "运动员靠意志跑完了全部比赛。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难再大，也要用意志去面对。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他意志很强，受伤后还在训练。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病时，坚强的意志比药还重要。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山不但要有力气，还要有意志。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的意志让医生非常佩服。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要锻炼意志，就要每天坚持。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在沙漠里，他靠意志走了三天。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败了几次，他的意志没有变弱。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学游泳需要胆量，也需要意志。", "target_word": "意志", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "意志力", "label": "复合"}], "register": "书面", "sense_fingerprint": "为达到目的自觉努力、克服困难的心理力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医治", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是治疗。"}, {"text": "一纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是一张（纸）。"}, {"text": "意志", "is_correct": true, "explanation": "正确。意志指为达到目的而自觉努力、克服困难的心理力量。"}, {"text": "以至", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是以致、直到。"}, {"text": "意指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是指的是、意思是。"}], "explanations": {"医治": "yī（第一声）与 yì（第四声）声调不同，意思是治疗。", "一纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是一张（纸）。", "意志": "正确。意志指为达到目的而自觉努力、克服困难的心理力量。", "以至": "yǐ（第三声）与 yì（第四声）声调不同，意思是以致、直到。", "意指": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是指的是、意思是。"}, "sentence_index": null, "correct_answer": "意志"}, "level_3": {"options": [{"text": "操场", "is_correct": false, "explanation": "配价：“靠”后应接表示凭借的力量或品质，“操场”是场地，不能作凭借。"}, {"text": "意志", "is_correct": true, "explanation": "正确。“靠意志”表示凭借坚持的力量，与“跑完了全部比赛”相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不能使人跑完比赛，不是跑步的凭借。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不能作为跑完全部比赛的凭借，句意不通。"}], "explanations": {"操场": "配价：“靠”后应接表示凭借的力量或品质，“操场”是场地，不能作凭借。", "意志": "正确。“靠意志”表示凭借坚持的力量，与“跑完了全部比赛”相符。", "地图": "语义：地图不能使人跑完比赛，不是跑步的凭借。", "食物": "语义：食物不能作为跑完全部比赛的凭借，句意不通。"}, "sentence_index": 0, "correct_answer": "意志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听到这个消息，意志就变得很激动。", "explanation": "这里应该用〈情绪〉。“激动”形容情绪，意志指坚持做事的力量，不能说“意志激动”。"}, {"text": "他的意志很暴躁，一句话就生气了。", "explanation": "这里应该用〈脾气〉。“暴躁”形容脾气，意志指坚持做事的力量，不能用来形容一个人的性情。"}, {"text": "他下了很大的意志要参加比赛。", "explanation": "这里应该用〈决心〉。“下决心”是固定说法，意志不能与“下”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94150, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一直", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是连续、不间断。"}, {"text": "一只", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是一个（用于动物等）。"}, {"text": "意志", "is_correct": true, "explanation": "正确。意志指为达到目的而自觉努力、克服困难的心理力量。"}, {"text": "一致", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是相同、统一。"}, {"text": "遗志", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是死者留下的愿望。"}], "explanations": {"一直": "zhí（第二声）与 zhì（第四声）声调不同，意思是连续、不间断。", "一只": "zhī（第一声）与 zhì（第四声）声调不同，意思是一个（用于动物等）。", "意志": "正确。意志指为达到目的而自觉努力、克服困难的心理力量。", "一致": "yí（第二声）与 yì（第四声）声调不同，意思是相同、统一。", "遗志": "yí（第二声）与 yì（第四声）声调不同，意思是死者留下的愿望。"}, "sentence_index": null, "correct_answer": "意志"}, "level_3": {"options": [{"text": "运气", "is_correct": false, "explanation": "搭配：“锻炼”多用于身体、能力或品质，“运气”不能被锻炼。"}, {"text": "意志", "is_correct": true, "explanation": "正确。“锻炼意志”即培养坚持的力量，与“每天坚持”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能被锻炼，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被锻炼，与“每天坚持”也不搭配。"}], "explanations": {"运气": "搭配：“锻炼”多用于身体、能力或品质，“运气”不能被锻炼。", "意志": "正确。“锻炼意志”即培养坚持的力量，与“每天坚持”相符。", "年龄": "语义：年龄不能被锻炼，句意不通。", "颜色": "语义：颜色不能被锻炼，与“每天坚持”也不搭配。"}, "sentence_index": 6, "correct_answer": "意志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的意志是环游世界。", "explanation": "这里应该用〈愿望〉。意志指坚持努力的力量，不能用来说想达到的目标。"}, {"text": "她对小狗有深厚的意志。", "explanation": "这里应该用〈感情〉。“深厚”修饰感情，意志不能表示对小狗的情感。"}, {"text": "她的意志很漂亮，大家都夸她。", "explanation": "这里应该用〈外貌〉。“漂亮”形容外貌，意志指坚持做事的力量，不能用来形容一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他靠一只坚强的意志熬过了冬天。", "corrected_sentence": "他靠一种坚强的意志熬过了冬天。", "error_description": "错误：「一只」用于动物或成对的东西，不能修饰「意志」；这里应用「一种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他凭很强意志爬完了山。", "corrected_sentence": "他凭很强的意志爬完了山。", "error_description": "错误：「很强意志」，形容词「很强」修饰名词「意志」时中间要加「的」，应说「很强的意志」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
