INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "紧紧抓住，不放过；掌握。", "primary_collocate": null, "pronunciation": "bǎ wò", "ipa": "pa˨˩ wo˥˩", "syllable_count": 2, "sentences": [{"text": "读文章时，要把握重点。", "target_word": "把握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "说话要把握好分寸。", "target_word": "把握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师帮我们把握学习的方向。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要把握好市场的变化。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会把握说话的时间和节奏。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章不长，但我没能把握住主要意思。", "target_word": "把握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作文要把握主题，不能离题。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把握着事情的大方向，细节让别人做。", "target_word": "把握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生需要准确把握病人的情况。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要写好故事，先要把握人物的性格。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "把握住", "label": "结果补语"}, {"form": "把握好", "label": "结果补语"}, {"form": "把握着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "把握重点、方向、分寸：牢牢抓住并掌握", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽略", "is_correct": false, "explanation": "语义：“忽略重点”与“读文章时要……”的要求相反，句意不通。"}, {"text": "把握", "is_correct": true, "explanation": "正确。“读文章时要把握重点”即抓住并掌握要点，语义通顺。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃重点”与读文章的要求相悖，句意不通。"}, {"text": "摒弃", "is_correct": false, "explanation": "语义：“摒弃”是舍弃不要，“摒弃重点”与读文章应抓住要点的要求相反，句意不通。"}], "explanations": {"忽略": "语义：“忽略重点”与“读文章时要……”的要求相反，句意不通。", "把握": "正确。“读文章时要把握重点”即抓住并掌握要点，语义通顺。", "放弃": "语义：“放弃重点”与读文章的要求相悖，句意不通。", "摒弃": "语义：“摒弃”是舍弃不要，“摒弃重点”与读文章应抓住要点的要求相反，句意不通。"}, "sentence_index": 0, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要把握好这次的晚饭。", "explanation": "这里应该用〈做〉。“做好晚饭”是常见说法，“把握”不能用于做饭。"}, {"text": "他很会把握做饭的油烟。", "explanation": "这里应该用〈排〉。“排油烟”是常见说法，“把握”不能用于油烟。"}, {"text": "我们一定要把握住这扇窗户。", "explanation": "这里应该用〈关〉。“关”用于门窗，“把握”不能用于窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏离", "is_correct": false, "explanation": "语义：“偏离主题”就是离题，与“不能离题”的要求矛盾。"}, {"text": "把握", "is_correct": true, "explanation": "正确。“写作文要把握主题”即掌握并围绕主题写作，与“不能离题”相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记主题”与“不能离题”的要求矛盾，句意不通。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除主题”与“要把握主题”的要求相反，句意不通。"}], "explanations": {"偏离": "语义：“偏离主题”就是离题，与“不能离题”的要求矛盾。", "把握": "正确。“写作文要把握主题”即掌握并围绕主题写作，与“不能离题”相符。", "忘记": "语义：“忘记主题”与“不能离题”的要求矛盾，句意不通。", "删除": "语义：“删除主题”与“要把握主题”的要求相反，句意不通。"}, "sentence_index": 6, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把握了那件新衣服。", "explanation": "这里应该用〈穿〉。“穿”用于衣服，“把握”不能用于衣物。"}, {"text": "工人们正在把握这座楼的玻璃。", "explanation": "这里应该用〈装〉。“装玻璃”是常见说法，“把握”不能用于安装玻璃。"}, {"text": "他把握了一盒牛奶。", "explanation": "这里应该用〈喝〉。“喝”用于牛奶等饮品，“把握”不能用于牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对市场的变化把握的很准确。", "corrected_sentence": "他对市场的变化把握得很准确。", "error_description": "“把握”后的程度补语要用“得”，不能用“的”，应说“把握得很准确”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把握住了文章的重点。", "corrected_sentence": "他没把握住文章的重点。", "error_description": "“没”表示否定时不能与“了”同用，应说“没把握住”，不能说“没把握住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
