INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94153, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94153, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抛弃是把东西或人丢下，不再要了。", "primary_collocate": null, "pronunciation": "pāo qì", "ipa": "pʰɑʊ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "有人把小狗抛弃在路边。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿意抛弃自己的孩子。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抛弃了家人，一个人走了。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人抛弃了这只猫。", "target_word": "抛弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人抛弃了妻子和女儿。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要抛弃你的好朋友。", "target_word": "抛弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们抛弃了旧房子，搬到了城里。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说过，永远不会抛弃我。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有人抛弃了一只受伤的小狗。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从来没有抛弃过我们。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抛弃了", "label": "体标"}, {"form": "抛弃过", "label": "体标"}, {"form": "拋棄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "抛弃：把人或东西丢下不管，不再要了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94153, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抛弃", "is_correct": true, "explanation": "正确：「抛弃」表示把小狗丢下不管，与「在路边」的语境相符。"}, {"text": "收养", "is_correct": false, "explanation": "语义：「收养」是接纳并抚养，与「丢在路边」的意思相反。"}, {"text": "照顾", "is_correct": false, "explanation": "配价：「照顾」的对象是需要照料的人或动物，不带「在路边」这样的处所补语。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：「把小狗保护在路边」不成立，「保护」不说放在某处。"}], "explanations": {"抛弃": "正确：「抛弃」表示把小狗丢下不管，与「在路边」的语境相符。", "收养": "语义：「收养」是接纳并抚养，与「丢在路边」的意思相反。", "照顾": "配价：「照顾」的对象是需要照料的人或动物，不带「在路边」这样的处所补语。", "保护": "搭配：「把小狗保护在路边」不成立，「保护」不说放在某处。"}, "sentence_index": 0, "correct_answer": "抛弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抛弃了这次比赛。", "explanation": "这里应该用〈放弃〉。抛弃多指丢下人或具体的东西，「比赛」这类活动要用〈放弃〉。"}, {"text": "他抛弃了这场晚会，独自回家。", "explanation": "这里应该用〈缺席〉。〈抛弃〉指丢下人或东西、不再要了，与〈晚会〉这类活动不搭配。"}, {"text": "他抛弃了那杯热茶，一口一口喝完了。", "explanation": "这里应该用〈端起〉。〈抛弃〉表示丢下不要，与〈一口一口喝完〉矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抛弃", "is_correct": true, "explanation": "正确：「抛弃」表示丢下旧房子不要了，与「搬到了城里」的情节相符。"}, {"text": "抚养", "is_correct": false, "explanation": "配价：「抚养」的对象是人或动物，不能说「抚养旧房子」。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：「欺骗」的对象是人，与「旧房子」搭配不成立。"}, {"text": "辞退", "is_correct": false, "explanation": "配价：「辞退」的对象是人，不能用于房子。"}], "explanations": {"抛弃": "正确：「抛弃」表示丢下旧房子不要了，与「搬到了城里」的情节相符。", "抚养": "配价：「抚养」的对象是人或动物，不能说「抚养旧房子」。", "欺骗": "语义：「欺骗」的对象是人，与「旧房子」搭配不成立。", "辞退": "配价：「辞退」的对象是人，不能用于房子。"}, "sentence_index": 6, "correct_answer": "抛弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸从来没有抛弃过这个笑话。", "explanation": "这里应该用〈讲〉或〈忘掉〉。〈抛弃〉表示丢下人或不要的东西，「笑话」不能被丢下，搭配不通。"}, {"text": "爸爸从来没有抛弃过一次考试。", "explanation": "这里应该用〈放弃〉。〈抛弃〉指丢下人或东西，〈考试〉这类活动要用〈放弃〉。"}, {"text": "爸爸从来没有抛弃过这个好天气。", "explanation": "这里应该用〈错过〉。〈抛弃〉指丢下人或东西，不能用于〈天气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧沙发抛弃仓库里。", "corrected_sentence": "他把旧沙发抛弃在仓库里。", "error_description": "错误在「抛弃」后缺少介词「在」。表示处所时要说「抛弃在……」，不能直接接处所词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈从来没有抛弃过了孩子。", "corrected_sentence": "妈妈从来没有抛弃过孩子。", "error_description": "错误在「抛弃过」后多加了「了」。「没有……过」表示从未有过的经历，不能与「了」同用；应说「从来没有抛弃过孩子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
