INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94154, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "舍弃想法、原则、习惯等，不再顾及。", "primary_collocate": null, "pronunciation": "pāo qì", "ipa": "pʰɑʊ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "为了成功，他抛弃了一切。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能抛弃自己的梦想。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抛弃了原来的想法。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司抛弃了旧方法，用了新办法。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了工作，抛弃了自己的爱好。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些坏习惯，我们应该抛弃。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抛弃了原则，只想着赚钱。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划太难了，大家决定抛弃它。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别抛弃希望，我们还有机会。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子，她抛弃了城里的工作。", "target_word": "抛弃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抛弃了", "label": "体标"}, {"form": "抛弃过", "label": "体标"}, {"form": "拋棄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "抛弃：舍弃想法、原则、习惯等，不再顾及", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抛弃", "is_correct": true, "explanation": "正确：「抛弃」表示舍弃，与「为了成功」所表示的牺牲语境一致。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：「珍惜」是重视，与「为了成功」所表示的舍弃相反。"}, {"text": "保留", "is_correct": false, "explanation": "语义：「保留」是留下，与「抛弃了一切」的语境矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：「享受一切」搭配不当，「享受」一般说享受生活或待遇。"}], "explanations": {"抛弃": "正确：「抛弃」表示舍弃，与「为了成功」所表示的牺牲语境一致。", "珍惜": "语义：「珍惜」是重视，与「为了成功」所表示的舍弃相反。", "保留": "语义：「保留」是留下，与「抛弃了一切」的语境矛盾。", "享受": "搭配：「享受一切」搭配不当，「享受」一般说享受生活或待遇。"}, "sentence_index": 0, "correct_answer": "抛弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司抛弃了旧方法，但一直在用它。", "explanation": "这里应该用〈保留〉。〈抛弃〉表示不再要了，与〈一直在用它〉矛盾。"}, {"text": "他抛弃了这份工作，每天准时上班。", "explanation": "这里与〈每天准时上班〉矛盾。〈抛弃〉表示不再要了，应该用〈继续〉或〈保留〉。"}, {"text": "他抛弃了那个问题，却天天在想它。", "explanation": "这里与〈天天在想它〉矛盾。〈抛弃〉表示不再顾及，应该用〈放下〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抛弃", "is_correct": true, "explanation": "正确：「抛弃」表示舍弃原则，与后句「只想着赚钱」的语境相符。"}, {"text": "坚持", "is_correct": false, "explanation": "语义：「坚持」是保持，与后句「只想着赚钱」的语境矛盾。"}, {"text": "秉持", "is_correct": false, "explanation": "语义：「秉持」是坚持原则，与后句「只想着赚钱」矛盾。"}, {"text": "遵守", "is_correct": false, "explanation": "语义：「遵守」是遵循，与后句「只想着赚钱」的语境矛盾。"}], "explanations": {"抛弃": "正确：「抛弃」表示舍弃原则，与后句「只想着赚钱」的语境相符。", "坚持": "语义：「坚持」是保持，与后句「只想着赚钱」的语境矛盾。", "秉持": "语义：「秉持」是坚持原则，与后句「只想着赚钱」矛盾。", "遵守": "语义：「遵守」是遵循，与后句「只想着赚钱」的语境矛盾。"}, "sentence_index": 6, "correct_answer": "抛弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了孩子，她抛弃了城里的工作，却每天都回去上班。", "explanation": "这里应该用〈保留〉。〈抛弃〉表示舍弃，与〈每天都回去上班〉矛盾。"}, {"text": "为了孩子，她抛弃了城里的房子，至今还住在那里。", "explanation": "这里应该用〈留着〉。〈抛弃〉表示不再要，与〈至今还住在那里〉矛盾。"}, {"text": "为了孩子，她抛弃了城里的朋友，却天天和他们见面。", "explanation": "这里应该用〈留住〉。〈抛弃〉表示不再顾及，与〈天天和他们见面〉矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "无论多难，我们都不能抛弃过自己的理想。", "corrected_sentence": "无论多难，我们都不能抛弃自己的理想。", "error_description": "错误在「过」的使用。「不能」后面的动词不带「过」，应去掉「过」，说「不能抛弃自己的理想」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她抛弃得这个念头，专心工作。", "corrected_sentence": "她抛弃了这个念头，专心工作。", "error_description": "错误在「抛弃」后用了「得」。「得」要接补语，「抛弃得这个念头」不成话；应改为「抛弃了这个念头」，表示已经舍弃。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
