INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94155, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出是把东西从里面拿到外面来。", "primary_collocate": null, "pronunciation": "ná chū", "ipa": "na˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他从包里拿出一本书。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从冰箱里拿出了一个苹果。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把作业本拿出，放在桌子上。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明从口袋里拿出钥匙开门。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从盒子里拿出一支笔。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从书包里拿出了雨伞。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱包从包里拿出，放在桌上。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从柜子里拿出一床被子。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从箱子里拿出一件旧衣服。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开抽屉，拿出了一张照片。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿出了", "label": "体标"}, {"form": "拿出过", "label": "体标"}, {"form": "拿出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，把具体的东西从包、盒、柜等里面取到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拿出", "is_correct": true, "explanation": "拿出：从包里取到外面，与“从包里”和“一本书”的语境相符。"}, {"text": "放入", "is_correct": false, "explanation": "语义：“放入”表示放进去，与“从包里”所表示的由内向外的方向相反。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是用钱换来的东西，不能说从包里买书。"}, {"text": "借", "is_correct": false, "explanation": "搭配：“借”表示向别人暂时取得，句中没有借入的对象，不能说从包里借书。"}], "explanations": {"拿出": "拿出：从包里取到外面，与“从包里”和“一本书”的语境相符。", "放入": "语义：“放入”表示放进去，与“从包里”所表示的由内向外的方向相反。", "买": "搭配：“买”的对象是用钱换来的东西，不能说从包里买书。", "借": "搭配：“借”表示向别人暂时取得，句中没有借入的对象，不能说从包里借书。"}, "sentence_index": 0, "correct_answer": "拿出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明拿出了一座房子。", "explanation": "这里应该用〈盖〉。“拿出”只能用于可以搬动的具体物品，房子不能被拿出，说建房子要用“盖”。"}, {"text": "小明拿出了一句谎话。", "explanation": "这里应该用〈编造〉。“拿出”指从里面取到外面，不能用于“谎话”这类言语，编造谎话要用“编造”。"}, {"text": "小明往口袋里拿出钥匙。", "explanation": "这里应该用〈装〉。“拿出”是从里往外取，与“往口袋里”的方向相反，这里要表示放进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿出", "is_correct": true, "explanation": "拿出：从包里取到外面，与“把钱包从包里”和“放在桌上”的动作顺序相符。"}, {"text": "掏", "is_correct": false, "explanation": "配价：“掏”需要带结果补语或宾语，单独说不完整，句中缺少“掏出”的结果。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指整体移动，不指从包中取出一件物品。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”表示把东西倾倒出来，与钱包被整体取出再放在桌上的动作不协调。"}], "explanations": {"拿出": "拿出：从包里取到外面，与“把钱包从包里”和“放在桌上”的动作顺序相符。", "掏": "配价：“掏”需要带结果补语或宾语，单独说不完整，句中缺少“掏出”的结果。", "搬": "语义：“搬”指整体移动，不指从包中取出一件物品。", "倒": "语义：“倒”表示把东西倾倒出来，与钱包被整体取出再放在桌上的动作不协调。"}, "sentence_index": 6, "correct_answer": "拿出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她拿出了一场雨。", "explanation": "这里应该用〈下〉。“雨”是自然现象，不能被拿出，说下雨要用“下”。"}, {"text": "她拿出了一阵风。", "explanation": "这里应该用〈刮〉。风是自然现象，不能被拿在手里取出，说刮风要用“刮”。"}, {"text": "她拿出了一条河。", "explanation": "这里应该用〈看见〉。河是大型景物，不能被拿出，说看见一条河要用“看见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他往箱子里拿出一件毛衣。", "corrected_sentence": "他从箱子里拿出一件毛衣。", "error_description": "错误：“往箱子里”表示动作朝箱子内部进行，与“拿出”由内向外取出的方向相反。正确：“从箱子里”表示从箱子内取出，与“拿出”的方向相符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从书架上拿出的一本词典。", "corrected_sentence": "她从书架上拿出一本词典。", "error_description": "错误：“拿出”后多出结构助词“的”，使“拿出的一本词典”变成名词短语，句子缺少谓语。正确：“拿出一本词典”是动词短语作谓语，“的”不应加在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
