INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94156, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把证件、证据、办法、勇气等亮出来给人看，或投入使用。", "primary_collocate": null, "pronunciation": "ná chū", "ipa": "na˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "请拿出你的护照给我看。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出了证据，大家都相信了。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要拿出办法解决这个问题。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出勇气，向老师说了真话。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，大家都拿出了真本事。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司拿出一百万帮助学校。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出诚意，向朋友道歉。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请拿出你的学生证，给我检查一下。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察让他拿出身份证。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要拿出信心，别怕考试。", "target_word": "拿出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿出了", "label": "体标"}, {"form": "拿出过", "label": "体标"}, {"form": "拿出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，把证件、证据、办法、勇气等拿出来给人看或投入使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拿出", "is_correct": true, "explanation": "拿出：亮出、出示，与“请……给我看”的语境相符。"}, {"text": "放出", "is_correct": false, "explanation": "语义：“放出”表示释放、放走，与“给我看”的出示动作不符。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”表示取回已经交出的东西，与请对方出示证件的语境相反。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“给我看”的意思完全矛盾。"}], "explanations": {"拿出": "拿出：亮出、出示，与“请……给我看”的语境相符。", "放出": "语义：“放出”表示释放、放走，与“给我看”的出示动作不符。", "收回": "语义：“收回”表示取回已经交出的东西，与请对方出示证件的语境相反。", "扔": "语义：“扔”表示丢弃，与“给我看”的意思完全矛盾。"}, "sentence_index": 0, "correct_answer": "拿出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿出了冠军。", "explanation": "这里应该用〈取得〉。“拿出”表示亮出或投入使用，不能用于“冠军”这类通过努力获得的结果。"}, {"text": "听到噪音，他拿出一声尖叫。", "explanation": "这里应该用〈发出〉。“拿出”用于亮出或投入使用的东西、勇气等，不能用于声音，发出声音要用“发出”。"}, {"text": "他拿出了真话，告诉老师。", "explanation": "这里应该用〈说出〉。“拿出”不用于言语，说真话要用“说出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿出", "is_correct": true, "explanation": "拿出：投入、使用，与“诚意”和“向朋友道歉”的语境相符。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”多用于门窗、盒子等具体物体，不能用于“诚意”这类抽象概念。"}, {"text": "交给", "is_correct": false, "explanation": "配价：“交给”需要接受者，如“交给朋友”，句中只有对象，缺少接受的人。"}, {"text": "收起", "is_correct": false, "explanation": "语义：“收起”表示收拢或收藏，与向朋友道歉时表达诚意的意思相反。"}], "explanations": {"拿出": "拿出：投入、使用，与“诚意”和“向朋友道歉”的语境相符。", "打开": "搭配：“打开”多用于门窗、盒子等具体物体，不能用于“诚意”这类抽象概念。", "交给": "配价：“交给”需要接受者，如“交给朋友”，句中只有对象，缺少接受的人。", "收起": "语义：“收起”表示收拢或收藏，与向朋友道歉时表达诚意的意思相反。"}, "sentence_index": 6, "correct_answer": "拿出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你要拿出恐惧，别怕考试。", "explanation": "这里应该用〈克服〉。“拿出”表示亮出或投入使用，不能用于“恐惧”这类情绪，要说“克服恐惧”。"}, {"text": "你要拿出感冒，别怕考试。", "explanation": "这里应该用〈治好〉。“拿出”指亮出或投入使用证件、勇气、办法等，“感冒”是疾病，不能拿出来使用。"}, {"text": "你要拿出失败，别怕考试。", "explanation": "这里应该用〈面对〉。“失败”是结果，不是能亮出或投入使用的能力、态度，要说“面对失败”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她了拿出耐心，帮孩子做完了作业。", "corrected_sentence": "她拿出耐心，帮孩子做完了作业。", "error_description": "错误：“了”放在动词“拿出”之前，位置不对；“了”表示完成，只能放在动词或补语之后。正确：“她拿出耐心”，“拿出”前不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都了拿出了干劲，把工作做完了。", "corrected_sentence": "大家都拿出了干劲，把工作做完了。", "error_description": "错误：多出一个“了”，放在副词“都”与动词“拿出”之间。“了”表示完成，只能放在动词或补语之后，不能放在动词之前。正确：“大家都拿出了干劲”，“拿出”前不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
