INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把意见、想法、方案等交给别人看或处理。", "primary_collocate": null, "pronunciation": "tí jiāo", "ipa": "tʰi³⁵ tɕjɑʊ⁵⁵", "syllable_count": 2, "sentences": [{"text": "我把照片提交给老师了。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请明天把表格提交给我。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一份很好的报告提交给了领导。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把意见提交给经理。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把你的想法写下来提交给我。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想提交一个新的计划。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把自己的看法提交给了小组。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把方案提交给公司，等着回复。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提交过很多次意见。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我会提交给大家讨论。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提交了", "label": "体标"}, {"form": "提交过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，把意见、想法、方案等交给别人看或处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提交", "is_correct": true, "explanation": "“提交”指把照片交给老师，与“把……给老师”的交付结构相符。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉照片，不能交给老师，与句意不合。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”是毁掉照片，与“给老师”的交付意思相反。"}, {"text": "撤回", "is_correct": false, "explanation": "搭配：“撤回”是收回已交出的东西，与“给老师”的交付方向相反，不能这样搭配。"}], "explanations": {"提交": "“提交”指把照片交给老师，与“把……给老师”的交付结构相符。", "删除": "语义：“删除”是去掉照片，不能交给老师，与句意不合。", "撕碎": "语义：“撕碎”是毁掉照片，与“给老师”的交付意思相反。", "撤回": "搭配：“撤回”是收回已交出的东西，与“给老师”的交付方向相反，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "提交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们提交了礼物。", "explanation": "这里应该用〈交换〉。“提交”指把文件、意见交给有关方面处理，不能用于互相交换礼物。"}, {"text": "公司提交了免费午餐。", "explanation": "这里应该用〈提供〉。“提交”指交给有关方面处理，给员工的免费午餐应该用“提供”。"}, {"text": "我把朋友提交给了老师。", "explanation": "这里应该用〈推荐〉。“提交”的对象是文件、意见等东西，不能是人，推荐人要用“推荐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提交", "is_correct": true, "explanation": "“提交”指把看法交给小组，与“把……给了小组”的结构相符。"}, {"text": "保密", "is_correct": false, "explanation": "搭配：“保密”不能带“把……给了小组”的交付结构，句子不通。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”是藏起来，与把看法交给小组的意思相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽别人，与把看法交给小组的意思完全不符。"}], "explanations": {"提交": "“提交”指把看法交给小组，与“把……给了小组”的结构相符。", "保密": "搭配：“保密”不能带“把……给了小组”的交付结构，句子不通。", "隐藏": "语义：“隐藏”是藏起来，与把看法交给小组的意思相反。", "嘲笑": "语义：“嘲笑”是讥讽别人，与把看法交给小组的意思完全不符。"}, "sentence_index": 6, "correct_answer": "提交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校提交了这位老师。", "explanation": "这里应该用〈提拔〉。“提拔”指把人调到更高职位，“提交”只能用于文件、意见等。"}, {"text": "他在会上提交了专家。", "explanation": "这里应该用〈提问〉。“提问”是向人发问，“提交”指把东西交给有关方面，不能用来指向人。"}, {"text": "这次培训提交了我们的效率。", "explanation": "这里应该用〈提高〉。效率是可以提高的水平，不能说提交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把论文提交了教授。", "corrected_sentence": "他把论文提交给了教授。", "error_description": "错误形式：“他把论文提交了教授”，漏掉了引出接收者的“给”。正确形式：“他把论文提交给了教授”，“提交”后要用“给”引出接收的人，句子才通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她明天会提交过报告。", "corrected_sentence": "她明天会提交报告。", "error_description": "错误形式：“她明天会提交过报告”，“过”表示已经发生的经历，不能与“明天”这种将来的时间搭配。正确形式：“她明天会提交报告”，去掉“过”，将来的动作只用“会”表示。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
