INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94160, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把文件、作业或问题交给有关方面处理。", "primary_collocate": null, "pronunciation": "tí jiāo", "ipa": "tʰi³⁵ tɕjɑʊ⁵⁵", "syllable_count": 2, "sentences": [{"text": "今天我要提交作业。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在五点前提交报告。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经提交了申请表。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把文件提交给老师了。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要提交给经理处理。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们都提交过作业。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提交以后，你就不能改了。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忘了提交论文，很着急。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上提交比去现场快。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议前，请把材料提交给秘书。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提交了", "label": "体标"}, {"form": "提交过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，把文件、作业、问题等正式交给有关方面处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a99f3118-40b9-42d8-afd1-8d636cb5135f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提交", "is_correct": true, "explanation": "“提交”指把作业交上去，与“今天我要……作业”的意思相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能接“作业”。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是撕毁，与“我要……作业”表达的交作业意思不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能接“作业”。"}], "explanations": {"提交": "“提交”指把作业交上去，与“今天我要……作业”的意思相符。", "吃": "搭配：“吃”的宾语应是食物，不能接“作业”。", "撕": "语义：“撕”是撕毁，与“我要……作业”表达的交作业意思不符。", "喝": "搭配：“喝”的宾语应是饮品，不能接“作业”。"}, "sentence_index": 0, "correct_answer": "提交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院提交了免费体检。", "explanation": "这里应该用〈提供〉。“提交”指交给有关方面处理，供人免费使用的东西要用“提供”。"}, {"text": "学生在课堂上提交了老师。", "explanation": "这里应该用〈提问〉。“提问”是向人发问，“提交”不能用来指向人。"}, {"text": "公司提交了一位年轻员工。", "explanation": "这里应该用〈提拔〉。“提拔”指把人调到更高职位，“提交”不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提交", "is_correct": true, "explanation": "“提交”指把作业或材料交上去，“提交以后”表示交上去之后的状态，与“你就不能改了”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“你就不能改了”之间没有逻辑关系，句子不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”和“不能改了”没有关系，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是走路休闲，与“以后不能改”的意思毫无关联。"}], "explanations": {"提交": "“提交”指把作业或材料交上去，“提交以后”表示交上去之后的状态，与“你就不能改了”相符。", "睡觉": "语义：“睡觉”与“你就不能改了”之间没有逻辑关系，句子不通。", "吃饭": "语义：“吃饭”和“不能改了”没有关系，句意不通。", "散步": "语义：“散步”是走路休闲，与“以后不能改”的意思毫无关联。"}, "sentence_index": 6, "correct_answer": "提交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国提交了大使。", "explanation": "这里应该用〈互派〉。“提交”是把文件、作业交给有关方面处理，两国派遣大使要用“互派”。"}, {"text": "我用现金提交了房租。", "explanation": "这里应该用〈支付〉。“提交”指把文件、作业交给有关方面处理，付房租要用“支付”。"}, {"text": "新的方法提交了产量。", "explanation": "这里应该用〈提高〉。产量是可以提高的数量，不能说提交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把申请表提交了给办公室。", "corrected_sentence": "我把申请表提交给了办公室。", "error_description": "错误形式：“我把申请表提交了给办公室”，“了”放在“给”之前，位置错误。正确形式：“我把申请表提交给了办公室”，“给了”连在一起表示已经完成的交付。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下午提交给了一份报告。", "corrected_sentence": "他下午提交了一份报告。", "error_description": "错误形式：“提交给了一份报告”，“给”需要接收的人作宾语，后面不能直接接“一份报告”。正确形式：“提交了一份报告”，“提交”直接带被交的东西，不需要“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da13949c-4240-418b-92bd-fe8f3e3d4d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
