INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旅馆是出门在外的人可以花钱睡觉的地方。", "primary_collocate": null, "pronunciation": "lǚ guǎn", "ipa": "ly˨˩˦ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们走了一天，累得不行，就在车站旁边找了一家旅馆。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家旅馆很干净，晚上也很安静。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在旅馆里住了三天。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅馆的床很小，可是我睡得很好。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在网上订了一家旅馆。", "target_word": "旅馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅馆离火车站不远，走路十分钟就到了。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太晚了，我们只好住旅馆。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅馆的门口有一棵大树。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门旅行时，我常常住便宜的旅馆。", "target_word": "旅馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，附近有没有旅馆？", "target_word": "旅馆", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "旅館", "label": "繁体"}, {"form": "小旅馆", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，出门在外的人付钱住宿的地方，常说住旅馆、订旅馆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅馆", "is_correct": true, "explanation": "正确：“旅馆”是供出门在外的人住宿的地方，与“找了一家”搭配。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场以种植养殖为主，累了要过夜时一般不会去农场，与“累得不行”的语境不合。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不接待过夜的旅客，与“累得不行”要休息的语境不合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，句中要的是休息过夜的住处，与“累得不行”后找地方住的语境不合。"}], "explanations": {"旅馆": "正确：“旅馆”是供出门在外的人住宿的地方，与“找了一家”搭配。", "农场": "语义：农场以种植养殖为主，累了要过夜时一般不会去农场，与“累得不行”的语境不合。", "工厂": "语义：工厂是生产场所，不接待过夜的旅客，与“累得不行”要休息的语境不合。", "医院": "语义：医院是看病的地方，句中要的是休息过夜的住处，与“累得不行”后找地方住的语境不合。"}, "sentence_index": 0, "correct_answer": "旅馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅馆很愉快。", "explanation": "这里应该用〈旅途〉。“旅馆”指供人住宿的地方，不指行程；说整段行程要用“旅途”。"}, {"text": "他每天坐旅馆上班。", "explanation": "这里应该用〈地铁〉。“旅馆”是住宿场所，不是交通工具，“坐”后要接交通工具。"}, {"text": "他的职业是旅馆。", "explanation": "这里应该用〈医生〉。“旅馆”是地方，不是职业，说职业要用“医生”这类名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅馆", "is_correct": true, "explanation": "正确：“太晚了，只好住”后接住宿的场所，“旅馆”符合句意。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是吃饭的地方，不供人住宿，与“只好住”冲突。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是卖书的地方，不能用来住宿。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“住”要接住宿的场所，不说“住银行”。"}], "explanations": {"旅馆": "正确：“太晚了，只好住”后接住宿的场所，“旅馆”符合句意。", "饭馆": "语义：饭馆是吃饭的地方，不供人住宿，与“只好住”冲突。", "书店": "语义：书店是卖书的地方，不能用来住宿。", "银行": "搭配：“住”要接住宿的场所，不说“住银行”。"}, "sentence_index": 6, "correct_answer": "旅馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天穿了蓝色的旅馆。", "explanation": "这里应该用〈衣服〉。“穿”后接的是衣物，旅馆不能穿。"}, {"text": "我们在车站吃了一顿旅馆。", "explanation": "这里应该用〈饭〉。“吃一顿”后接的是食物，旅馆不能吃。"}, {"text": "来这里的旅馆很多。", "explanation": "这里应该用〈旅客〉。“旅馆”是地点，不能指来住宿的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在火车站附近找了一只旅馆。", "corrected_sentence": "我们在火车站附近找了一家旅馆。", "error_description": "错误：“一只旅馆”。正确：“一家旅馆”。“只”用于动物或成对的东西，旅馆是营业场所，量词用“家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天快黑了，我们只好把旅馆住下来。", "corrected_sentence": "天快黑了，我们只好在旅馆住下来。", "error_description": "错误：“把旅馆住下来”。正确：“在旅馆住下来”。“住”后接处所时常用“在”引出处所，“把”字句接“住下来”很不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
