INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94167, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94167, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "死刑是对做了特别坏的事的人，让他失去生命的处罚。", "primary_collocate": null, "pronunciation": "sǐ xíng", "ipa": "sɨ˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法官判了他死刑。", "target_word": "死刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家没有死刑。", "target_word": "死刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他杀了人，法官判他死刑。", "target_word": "死刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人不同意死刑。", "target_word": "死刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他听到死刑的消息，哭了。", "target_word": "死刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院今天决定对他执行死刑。", "target_word": "死刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些国家还有死刑。", "target_word": "死刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不怕坐牢，但是怕死刑。", "target_word": "死刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和我们谈了死刑的问题。", "target_word": "死刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "死刑是很重的处罚。", "target_word": "死刑", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "死刑犯", "label": "复合"}], "register": "书面", "sense_fingerprint": "对犯了重罪的人让其失去生命的处罚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死刑", "is_correct": true, "explanation": "“判……死刑”是常用搭配，表示法院判处最重的刑罚，句子通顺。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”不是刑罚，法官不能判处生日。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“判”不能搭配“手术”，法官判决的对象是刑罚，不是手术。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是处罚，与“法官判了他”的语境不符。"}], "explanations": {"死刑": "“判……死刑”是常用搭配，表示法院判处最重的刑罚，句子通顺。", "生日": "语义：“生日”不是刑罚，法官不能判处生日。", "手术": "搭配：“判”不能搭配“手术”，法官判决的对象是刑罚，不是手术。", "天气": "语义：“天气”不是处罚，与“法官判了他”的语境不符。"}, "sentence_index": 0, "correct_answer": "死刑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为超速，被处以死刑。", "explanation": "这里应该用〈罚款〉。“死刑”只用于杀人等极重的罪，超速不能判死刑。"}, {"text": "他被判死刑三年。", "explanation": "这里应该用〈坐牢〉。死刑不是有刑期的刑罚，不能说“判死刑三年”。"}, {"text": "他在考试中作弊，被学校判了死刑。", "explanation": "这里应该用〈处分〉。“死刑”是法院对重罪判的刑罚，学校不能判死刑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死刑", "is_correct": true, "explanation": "“死刑”是刑罚，“有些国家还有死刑”指部分国家仍保留这一刑罚，句子通顺。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：“晚饭”不是刑罚或制度，“还有晚饭”与句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是刑罚或制度，“还有天气”说不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，“还有星期”与句意不符。"}], "explanations": {"死刑": "“死刑”是刑罚，“有些国家还有死刑”指部分国家仍保留这一刑罚，句子通顺。", "晚饭": "语义：“晚饭”不是刑罚或制度，“还有晚饭”与句意不符。", "天气": "语义：“天气”不是刑罚或制度，“还有天气”说不通。", "星期": "语义：“星期”是时间单位，“还有星期”与句意不符。"}, "sentence_index": 6, "correct_answer": "死刑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为抢劫犯了死刑。", "explanation": "这里应该用〈死罪〉。“死刑”是刑罚，不是罪行，“犯”后面应接罪行。"}, {"text": "他被判了十年死刑。", "explanation": "这里应该用〈徒刑〉。死刑没有刑期，不能说“判十年死刑”。"}, {"text": "他在广场上死刑了三个人。", "explanation": "这里应该用〈枪毙〉。“死刑”是刑罚名称，不能作动词带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个杀人犯被判了死刑犯。", "corrected_sentence": "那个杀人犯被判了死刑。", "error_description": "错误：把刑罚“死刑”说成了“死刑犯”（被判死刑的人）。“判”的对象应是刑罚，正确说法是“判了死刑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位律师坚决反对死刑犯。", "corrected_sentence": "这位律师坚决反对死刑。", "error_description": "错误：把刑罚“死刑”说成了“死刑犯”（被判死刑的人）。“反对”的对象应是刑罚本身，正确说法是“反对死刑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94168, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
