INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彻底消灭，彻底破坏。", "primary_collocate": null, "pronunciation": "huǐ miè", "ipa": "xuei˨˩ mie˥˩", "syllable_count": 2, "sentences": [{"text": "核战争会毁灭整个人类。", "target_word": "毁灭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "战争会毁灭一个国家的文明。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏消息毁灭了他所有的希望。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想毁灭这个国家的历史和文化。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人说，世界会在一场大战中毁灭。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不断的污染可能会毁灭海里所有的生命。", "target_word": "毁灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，坏人想用机器毁灭地球。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次失败毁灭了他对生活的信心。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不保护环境，地球就会毁灭。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争毁灭过很多古老的文明，也毁灭过无数家庭。", "target_word": "毁灭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毁灭了", "label": "体标（了）"}, {"form": "毁灭过", "label": "体标（过）"}, {"form": "毁灭性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "彻底消灭或破坏：人类、文明、希望、世界等大的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c10993-6c0d-4c6e-abf6-f9f8ecce14d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毁灭", "is_correct": true, "explanation": "毁灭指彻底消灭，这里说核战争会彻底消灭整个人类。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是防止伤害，与核战争造成的彻底消灭相反。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”一般搭配“希望、机会”，不能以“人类”为对象。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏美好的事物，核战争不会欣赏人类。"}], "explanations": {"毁灭": "毁灭指彻底消灭，这里说核战争会彻底消灭整个人类。", "保护": "语义：“保护”是防止伤害，与核战争造成的彻底消灭相反。", "放弃": "搭配：“放弃”一般搭配“希望、机会”，不能以“人类”为对象。", "欣赏": "语义：“欣赏”是赞赏美好的事物，核战争不会欣赏人类。"}, "sentence_index": 0, "correct_answer": "毁灭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石碑被毁灭了一个角，但还能看清上面的字。", "explanation": "这里应该用〈损坏〉。毁灭指彻底消灭、什么也不剩，只缺一个角、字还能看清，应说“损坏”。"}, {"text": "老人把技艺毁灭给了年轻人。", "explanation": "这里应该用〈传承〉。毁灭指彻底消失，不能用于把技艺交给年轻人。"}, {"text": "他们在工地上毁灭了一座新大楼，现在大楼已经完工了。", "explanation": "这里应该用〈建造〉。毁灭是彻底破坏，后文说大楼已经完工，前后矛盾，应说“建造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毁灭", "is_correct": true, "explanation": "毁灭指彻底破坏，这里说坏人想用机器彻底摧毁地球。"}, {"text": "拯救", "is_correct": false, "explanation": "语义：“拯救”是把人或物从危险中救出，与坏人的意图相反。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”一般用于房间、节日等，不说“装饰地球”这样的宏大对象。"}, {"text": "保卫", "is_correct": false, "explanation": "语义：“保卫”是保护安全，与“坏人想用机器”的意图矛盾。"}], "explanations": {"毁灭": "毁灭指彻底破坏，这里说坏人想用机器彻底摧毁地球。", "拯救": "语义：“拯救”是把人或物从危险中救出，与坏人的意图相反。", "装饰": "搭配：“装饰”一般用于房间、节日等，不说“装饰地球”这样的宏大对象。", "保卫": "语义：“保卫”是保护安全，与“坏人想用机器”的意图矛盾。"}, "sentence_index": 6, "correct_answer": "毁灭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家暂时毁灭了这项新技术，过几天又拿出了改进版。", "explanation": "这里应该用〈搁置〉。毁灭指彻底消灭、无法恢复，不能用于暂时放下、之后又拿出来的情况。"}, {"text": "老师毁灭了那份作业的最后一页。", "explanation": "这里应该用〈撕掉〉。毁灭指彻底消灭、什么也不剩，只撕掉最后一页、作业还在，不能说毁灭。"}, {"text": "医生用药毁灭了病人的感冒，感冒却一直没有好。", "explanation": "这里应该用〈治好〉。毁灭指彻底消灭，后文说感冒一直没有好，说明并没有彻底消灭，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场战争正在毁灭了一个民族的文化。", "corrected_sentence": "这场战争正在毁灭一个民族的文化。", "error_description": "“正在”表示动作正在进行，不能和“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次背叛把她对朋友的信任毁灭。", "corrected_sentence": "这次背叛把她对朋友的信任毁灭了。", "error_description": "“把”字句中动词后要带“了”或其他补语，只说“毁灭”不完整，应加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722a437b-ea6e-48c9-a8a8-29820c564131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
