INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "毒是吃了或碰了会让人生病甚至死掉的东西。", "primary_collocate": null, "pronunciation": "dú", "ipa": "tu³⁵", "syllable_count": 1, "sentences": [{"text": "这种蘑菇有毒，不能吃。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蛇有很强的毒，一定要小心。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人在水里下了毒。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草的毒会让人生病。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗吃了有毒的东西，一直吐。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠吃了屋角放的毒，很快就死了。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的毒不多，但小孩别碰。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人想在饭里下毒。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种贝类里有毒，吃了会生病。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说蜘蛛的毒会让人发烧。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种毒", "label": "量词"}, {"form": "毒药", "label": "复合"}, {"form": "毒蛇", "label": "复合"}, {"form": "中毒", "label": "复合"}], "register": "中性", "sense_fingerprint": "动植物或药物里吃了、碰了会让人或动物生病、死亡的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94171, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：毒，dú（第二声），指吃了或碰了会让人生病的东西。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，意思是赌博。"}, {"text": "度", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，意思是程度。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}], "explanations": {"毒": "正确：毒，dú（第二声），指吃了或碰了会让人生病的东西。", "赌": "dǔ（第三声）与 dú（第二声）声调不同，意思是赌博。", "度": "dù（第四声）与 dú（第二声）声调不同，意思是程度。", "图": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}, "sentence_index": null, "correct_answer": "毒"}, "level_3": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：这种蘑菇有毒，所以不能吃，毒作“有害物质”讲。"}, {"text": "营养", "is_correct": false, "explanation": "语义：营养是对身体有益的成分，与“不能吃”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：说蘑菇有颜色不能作为不能吃的理由，这一说法不合适。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味通常让人想吃，与“不能吃”矛盾。"}], "explanations": {"毒": "正确：这种蘑菇有毒，所以不能吃，毒作“有害物质”讲。", "营养": "语义：营养是对身体有益的成分，与“不能吃”矛盾。", "颜色": "搭配：说蘑菇有颜色不能作为不能吃的理由，这一说法不合适。", "香味": "语义：香味通常让人想吃，与“不能吃”矛盾。"}, "sentence_index": 0, "correct_answer": "毒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝毒，身体一直很好，从来没有生过病。", "explanation": "这里应该用〈牛奶〉。毒会让人生病甚至死亡，不能当饮料喝，与“身体一直很好”也矛盾。"}, {"text": "这种草里有一个毒，吃了会生病。", "explanation": "这里应该用〈种〉。作“有害物质”讲时，毒用量词〈种〉，不说〈一个毒〉。"}, {"text": "医生给他开了毒，让他一天吃三次。", "explanation": "这里应该用〈药〉。毒会伤害身体，不能开给病人吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94171, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：毒，dú（第二声），指吃了或碰了会让人生病的东西。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，意思是堵住。"}, {"text": "肚", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，意思是肚子。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}], "explanations": {"毒": "正确：毒，dú（第二声），指吃了或碰了会让人生病的东西。", "堵": "dǔ（第三声）与 dú（第二声）声调不同，意思是堵住。", "肚": "dù（第四声）与 dú（第二声）声调不同，意思是肚子。", "图": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}, "sentence_index": null, "correct_answer": "毒"}, "level_3": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：这种花的毒不多，但小孩别碰，毒指有害物质。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味是闻的，不能用手碰，与“小孩别碰”的提醒不合。"}, {"text": "光", "is_correct": false, "explanation": "语义：光是看见的，不能被碰到，与“小孩别碰”的提醒不合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：说声音不多不符合习惯，这里的说法不合适。"}], "explanations": {"毒": "正确：这种花的毒不多，但小孩别碰，毒指有害物质。", "气味": "语义：气味是闻的，不能用手碰，与“小孩别碰”的提醒不合。", "光": "语义：光是看见的，不能被碰到，与“小孩别碰”的提醒不合。", "声音": "搭配：说声音不多不符合习惯，这里的说法不合适。"}, "sentence_index": 6, "correct_answer": "毒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去医院打了毒，希望能预防疾病。", "explanation": "这里应该用〈疫苗〉。毒会伤人，不能用来预防疾病。"}, {"text": "他做菜时放了一点毒，味道很好。", "explanation": "这里应该用〈盐〉。毒会致命，不能当调料放进菜里。"}, {"text": "他每天都吃毒，说是对身体好。", "explanation": "这里应该用〈补品〉。毒会伤害身体，不能当作补品每天吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种野果有一个毒，千万不要吃。", "corrected_sentence": "这种野果有毒，千万不要吃。", "error_description": "“毒”是物质名词，前面不能加量词“个”，这里应直接说“有毒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种树的叶子毒有，牛吃了会生病。", "corrected_sentence": "这种树的叶子有毒，牛吃了会生病。", "error_description": "“毒”是名词，“有”要放在它前面，应说“有毒”，不能说“毒有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
