INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能损害人或动物健康乃至危及生命的物质。", "primary_collocate": null, "pronunciation": "dú", "ipa": "tu³⁵", "syllable_count": 1, "sentences": [{"text": "烟里有很多毒，对身体不好。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的水里有毒，不能喝。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些毒会伤害我们的身体。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车尾气里有毒，在路边不要久留。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种毒对孩子特别不好。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里的毒越来越多，大家都戴上了口罩。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法把水里的毒去掉了。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种油漆里有毒，房间要多通风。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那种药水里的毒会让鱼死掉。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农药里有毒，用完要洗手。", "target_word": "毒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种毒", "label": "量词"}, {"form": "毒药", "label": "复合"}, {"form": "毒气", "label": "复合"}, {"form": "解毒", "label": "复合"}], "register": "中性", "sense_fingerprint": "烟、水、空气、农药等中损害健康的有害物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：毒，dú（第二声），指能损害健康的有害物质。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，意思是赌博。"}, {"text": "肚", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，意思是肚子。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}], "explanations": {"毒": "正确：毒，dú（第二声），指能损害健康的有害物质。", "赌": "dǔ（第三声）与 dú（第二声）声调不同，意思是赌博。", "肚": "dù（第四声）与 dú（第二声）声调不同，意思是肚子。", "图": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}, "sentence_index": null, "correct_answer": "毒"}, "level_3": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：烟里有很多毒，对身体不好，毒指有害物质。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：维生素对身体有益，与“对身体不好”矛盾。"}, {"text": "矿物质", "is_correct": false, "explanation": "语义：矿物质是人体需要的营养，与“对身体不好”矛盾。"}, {"text": "汗", "is_correct": false, "explanation": "搭配：说烟里有很多汗不合习惯，烟不会含汗。"}], "explanations": {"毒": "正确：烟里有很多毒，对身体不好，毒指有害物质。", "维生素": "语义：维生素对身体有益，与“对身体不好”矛盾。", "矿物质": "语义：矿物质是人体需要的营养，与“对身体不好”矛盾。", "汗": "搭配：说烟里有很多汗不合习惯，烟不会含汗。"}, "sentence_index": 0, "correct_answer": "毒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生让他每天吃毒，身体会好起来。", "explanation": "这里应该用〈维生素〉。毒会损害健康，不能当营养品吃，与“身体会好起来”也矛盾。"}, {"text": "土里有很多毒，庄稼长得很好。", "explanation": "这里应该用〈养分〉。毒会损害作物，不能让庄稼长得好。"}, {"text": "这种毒很苦，医生让他每天喝。", "explanation": "这里应该用〈药〉。毒会伤害身体，不能开给病人喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94172, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：毒，dú（第二声），指能损害健康的有害物质。"}, {"text": "度", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，意思是程度。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，意思是堵住。"}], "explanations": {"毒": "正确：毒，dú（第二声），指能损害健康的有害物质。", "度": "dù（第四声）与 dú（第二声）声调不同，意思是程度。", "图": "tú（第二声）与 dú（第二声）声母不同，t 与 d 对立，意思是图画。", "堵": "dǔ（第三声）与 dú（第二声）声调不同，意思是堵住。"}, "sentence_index": null, "correct_answer": "毒"}, "level_3": {"options": [{"text": "毒", "is_correct": true, "explanation": "正确：他想办法把水里的毒去掉了，毒指有害物质。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：说去掉温度不合习惯，一般说降低温度。"}, {"text": "形状", "is_correct": false, "explanation": "语义：水里的形状不能被去掉，整句说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不存在于水中，不能去掉，与句意不合。"}], "explanations": {"毒": "正确：他想办法把水里的毒去掉了，毒指有害物质。", "温度": "搭配：说去掉温度不合习惯，一般说降低温度。", "形状": "语义：水里的形状不能被去掉，整句说不通。", "时间": "语义：时间不存在于水中，不能去掉，与句意不合。"}, "sentence_index": 6, "correct_answer": "毒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生让孩子去打毒，预防感冒。", "explanation": "这里应该用〈疫苗〉。毒会伤人，不能用来预防感冒。"}, {"text": "他每天都吃毒，说是对身体好。", "explanation": "这里应该用〈补品〉。毒会伤害身体，不能当作补品吃。"}, {"text": "工厂排出了一只毒，很多人都生病了。", "explanation": "这里应该用〈种〉。毒作“有害物质”讲，量词用〈种〉，不说〈一只毒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
